    var adt = new ca.uhn.hl7v2.model.v25.message.ADT^A01(adt);

    // Extracting patient name, SSN, MRN, and other details
    var familyName = adt.PID.PID_5.PID_5_1.toString();
    var givenNames = [adt.PID.PID_5.PID_5_2.toString()];
    var ssnNumber = adt.PID.PID_3.PID_3_1.toString();
    var mrnSystem = "http://hospital.example.org";
    var mrnValue = adt.PID.PID_3.PID_3_1.toString();

