        resourceType: "Patient",
        identifier: [
            {
                system: mrnSystem,
                value: mrnValue
            }
        ],
        name: [
            {
                use: "official",
                family: [familyName],
                given: givenNames
            }
        ],
        telecom: [
            {
                system: "phone",
                value: adt.PID.PID_5.PID_5_1.toString(),
                use: "home"
            }
        ]
    };

    return fhirPatient;
}

// Main transformer logic
try {
    var adtMessage = msg.get("ADT");
    if (adtMessage) {
        var fhirPatient = parseADT(adtMessage);

        // Set the FHIR patient resource in a global map for use across channels
        channelMap.put("FHIR_Patient", JSON.stringify(fhirPatient));
    } else {
        throw new Error("No ADT message received.");
    }
