import org.hl7.v3.MSH;

// ...

public boolean isValidMessage(MSH message) {
    // Check if the message contains only standard HL7 segments
    for (Segment segment : message.getSegments()) {
        if (!isStandardSegment(segment)) {
            return false; // Invalid segment, stop processing!
        }
    }

    return true;
}

private boolean isStandardSegment(Segment segment) {
    switch (segment.getComponent(0).getValue().substring(0, 3)) { // Get the segment ID (e.g., PID-1)
        case "MSH":
            // MSH segment is a standard HL7 segment
            return true;
        case "PV1":
            // PV1 segment is also a standard HL7 segment
            return true;
        default:
            // Z-segment or custom-defined segment, stop processing!
            return false;
    }
}
```
