// Import necessary libraries
var hl7v2 = new Packages.ca.uhn.hl7v2.model.v25;
var fhirR4 = new Packages.org.hl7.fhir.r4;

function convertToFHIR(hl7Message) {
    try {
        // Parse the HL7 v2 message
        var adtA01 = hl7v2.ADT_A01.parse(hl7Message);

        // Extract patient information from ADT^A01
        var pid = adtA01.PID(1);
        var name = pid.XPN(3).toString();
        var familyName = pid.XPN(4).XPN(2).toString();
        var givenNames = pid.XPN(4).XPN(1).map(x -> x.toString());
        var birthDate = pid.DTM(7).toString();

        // Create a FHIR Patient resource
        var patientResource = new fhirR4.Patient();
        patientResource.id = generateUUID(); // Generate a unique ID for the patient
        patientResource.text.status = "generated";
        patientResource.name.add(new fhirR4.HumanName().setUse("official").addGiven(givenNames).setFamily(familyName));
        if (birthDate) {
            var birthTime = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ").parse(birthDate);
            patientResource.birthTime = new fhirR4.Instant().setValue(birthTime.toInstant());
        }

        // Create a FHIR Encounter resource
        var encounterResource = new fhirR4.Encounter();
        encounterResource.id = generateUUID(); // Generate a unique ID for the encounter
        encounterResource.text.status = "generated";
        adtA01.PID(1).XPN(3).toString() && (encounterResource.identifier.add(new fhirR4.Identifier().setSystem("http://hospital.example.org").setValue(adtA01.PID(1).XPN(3).toString())));

        // Add patient to encounter
        var participant = new fhirR4.Encounter.Participant();
        if ("ADT" == adtA01.PID(1).PID_2.XPN(1).toString()) {
            participant.setRole(new fhirR4.CodeableConcept().addCoding(new fhirR4.Coding("http://terminology.hl7.org/CodeSystem/v2-0296", "ADT", null))));
        }
        encounterResource.participant.add(participant);

        // Return the FHIR resources as JSON
        return new java.lang.StringBuilder()
            .append(patientResource.toJSON())
            .append("\n")
            .append(encounterResource.toString());

    } catch (e) {
        log.error("Error converting HL7 v2 to FHIR R4: " + e);
        throw e;
    }
}

function generateUUID() {
    return java.util.UUID.randomUUID().toString();
}
```

