public static String getAccessToken(String client_id, String jwt_assertion) {
    // Set the client ID and JWT assertion as environment variables or file contents
    String clientId = System.getenv("EPIC_CLIENT_ID");
    String jwtAssertion = new File("/path/to/jwt/assertion.txt").readAllBytes();

    // Exchange the JWT for an access token using the `jwt` library
    Jwts.builder()
            .setAudience("https://fhir.epic.com")
            .setIssuedAt(DateTime.now())
            .setExpirationTime(DateTime.now().plusMinutes(1))
            .verify(JwsVerifier.verify(jwtAssertion, "https://fhir.epic.com", clientId));

    // Return the access token
    return Jwts.builder()
