Here's an example of how you could implement a simple retry wrapper in JavaScript using the `axios` library:
```
const axios = require('axios');

function tryAgain(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      func();
      break;
    } catch (error) {
      if (!/timeout/.test(error.message)) {
        console.error(`Error calling API: ${error}`);
        return;
      }
      retries++;
      if (retries < maxRetries) {
        console.log(`Retrying... attempt ${i+1}/${maxRetries}`);
        setTimeout(() => func(), 1000 * i); // wait for 1 second before retrying
      } else {
        console.error('Failed to call API after multiple retries');
      }
    }
  }
}

async function tryAgainAsync(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      await func();
      break;
    } catch (error) {
      if (!/timeout/.test(error.message)) {
        console.error(`Error calling API: ${error}`);
        return;
      }
      retries++;
      if (retries < maxRetries) {
        console.log(`Retrying... attempt ${i+1}/${maxRetries}`);
        setTimeout(() => func(), 1000 * i); // wait for 1 second before retrying
      } else {
        console.error('Failed to call API after multiple retries');
      }
    }
  }
}

async function tryAgainAsyncWithLogging(func, maxRetries=5) {
  let retries=0;
  const log = (str) => console.log(`API request: ${str}`);
  for (let i=0; i<=maxRetries; i++) {
    try {
      await func();
      break;
    } catch (error) {
      if (!/timeout/.test(error.message)) {
        const str = JSON.stringify(func().then((response)=> response.data));
        log(str);
        console.error(`Error calling API: ${error}`);
        return;
      }
      retries++;
      if (retries < maxRetries) {
        console.log(`Retrying... attempt ${i+1}/${maxRetries}`);
        setTimeout(() => func(), 1000 * i); // wait for 1 second before retrying
      } else {
        console.error('Failed to call API after multiple retries');
      }
    }
  }
}
```
This code defines three functions: `tryAgain`, `tryAgainAsync`, and `tryAgainAsyncWithLogging`. The first two functions take a synchronous function as an argument, and the third function takes an asynchronous function as an argument. Each of these functions uses a simple retry loop to call the given API endpoint multiple times until it gets a successful response or reaches its maximum number of retries.

Note that this code does not actually log any output - you will need to add your own logging logic if you want to see what is being logged!

