Here's an example code snippet using Java and the popular FHIR client library, HAPI-Fhir:
```java
import ca.uhn.fhir.context.FhirContext;
import ca.uhn.fhir.model.api.BundleDefinition;
import ca.uhn.fhir.model.dstu2.resource.Patient;
import ca.uhn.fhir.model.dstu2.resource.Observation;
import ca.uhn.fhir.model.dstu2.resource.DiagnosticReport;

public class FHIRBundleTransaction {
    public static void main(String[] args) {
        // Set up the FHIR client instance
        FhirContext ctx = FhirContext.forR4();

        // Create a new Bundle transaction with Patient, Observation, and DiagnosticReport resources
        BundleDefinition bundle = ctx.newBundle();
        bundle.setType(BundleType.TRANSACTION);

        Patient patient = new Patient().withId("example").withName(new HumanName().given(Arrays.asList("John", "Michael")).family("Smith"));
        Observation observation = new Observation().withCode(ObservationComponentCodes.SNOMEDCT_123456).valueQuantity(new Quantity(25.5, Units.MILLIMETER_OF_MERCURY));
        DiagnosticReport diagnosticReport = new DiagnosticReport().withCode(DiagnosticReportComponentCodes.SNOMEDCT_789012).withSection(new Section().withText("Patient is experiencing symptoms"));

        // Add the FHIR resources to the Bundle transaction
        bundle.addEntry(patient);
        bundle.addEntry(observation);
        bundle.addEntry(diagnosticReport);

        try {
            // Send the Bundle transaction to your preferred API or server-side system (e.g., EHR, RIS, or Mirth)
            String response = sendBundleTransaction(bundle);

            if (!response.isEmpty()) {
                System.out.println("Bundle Transaction successful: " + response);
            } else {
                System.err.println("Error sending Bundle Transaction");
            }
        } catch (Exception e) {
            // Handle errors and exceptions
            System.err.println("Error handling error: " + e.getMessage());
        }
