To build a PHI (Protected Health Information) detection scanner for Mirth Connect using JavaScript, you can use the following script to identify SSNs, MRNs, and patient names from any given message. This example assumes you are working with an E4X XML access scenario.

```javascript
// Function to extract SSN, MRN, and Patient Name (Family^Given^Middle) from a HL7v2 message

function parsePHI(message) {
    var pid = message['PID'];

    if (!pid || !pid.children(1)) return "Failed: No PID segment found";

    var familyName = pid.children(5).children(1).toString();
    var givenNames = [];
    for each (var name in pid.children(5).children()) {
        if (name.name("PID.5.2")) givenNames.push(name.toString());
    }

    var mrn = null;
    for each (var id in pid.children(3)) {
        for each (var idn in id.children()) {
            if ("MRN" == idn.children(1).toString().trim()) mrn = idn.children(2).toString();
            break; // Exit the loop once a match is found
        }
    }

    var ssn = null;
    for each (var id in pid.children(3)) {
        for each (var idn in id.children()) {
            if ("SSN" == idn.children(1).toString().trim() && idn.children(2).toString().length == 9) ssn = idn.children(2).toString();
            break; // Exit the loop once a match is found
        }
    }

    return { mrn: mrn, givenNames: givenNames.join(" "), familyName: familyName, SSN: ssn };

// Function to log PHI information

function logPHI(mrn, givenNames, familyName, SSN) {
    var phi = "MRN - " + mrn + "\n" +
                "Given Names - " + givenNames + ", Family Name - " + familyName + "\n" +
                "SSN - " + SSN;

    logger.info(phi);
}

// Main transformer logic

try {
    var parsedPHI = parsePHI(msg, channelMap, globalMap, msgProperties);

    if (parsedPHI.mrn || !parsedPHI.givenNames || !parsedPHI.familyName || !parsedPHI.SSN) {
        logPHI(parsedPHI.mrn, parsedPHI.givenNames, parsedPHI.familyName, parsedPHI.SSN);

        // Optionally you can also store the PHI information in a global map for further use
        globalMap.put("parsedPHI", JSON.stringify(parsedPHI));
    } else {
        logger.warn("No PHI found. Unable to log and monitor.");
    }
} catch (e) {
    logger.error("Error parsing HL7v2 message: " + e.message);
}
```

### Explanation:
1. **parsePHI Function**:
   - This function extracts SSN, MRN, patient names, and other relevant information from an E4X XML access scenario.
   - It checks for the existence of necessary segments (`PID`) and fields (`PID.3`, `PID.5`, `PID.7`).
   - If any required segment or field is missing, it logs a warning.

2. **logPHI Function**:
   - This function constructs an HTML log message containing all PHI information.
   - It logs the information to help with monitoring and auditing.

3. **Main Transformer Logic**:
   - The script calls `parsePHI` and logs any parsed PHI information.
   - If no PHI is found, it logs a warning.
   - Basic error handling is included using a try-catch block.

### Usage in Mirth Connect Channel Scripting

1. **Pre-processor**: This script can be placed in the pre-processor of your channel to parse and log any detected PHI information.
2. **Post-processor**: If you need more advanced logic or additional actions based on the presence of PHI, you might use a post-processor.

