To create a FHIR bulk data export client for population health analytics using Epic's SMART on FHIR (OAuth 2.0) API, we need to follow these steps:

1. Register an app at App Orchard.
2. Generate RSA key pair and upload the public key.
3. Create a signed JWT assertion.
4. Exchange the JWT for an access token.
5. Kick-off a bulk data export.
6. Poll status until completion.
7. Download NDJSON files.

Below is a Python script using `requests` to achieve this:

```python
import requests
import time
from datetime import datetime, timedelta

# Constants
BASE_URL = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4"
TOKEN_ENDPOINT = f"{BASE_URL}/oauth2/token"

# RSA key pair and JWT assertion (not shown here for brevity)

def get_access_token(client_assertion):
    # Step 3: Create a signed JWT assertion
    jwt_assertion = client_assertion

    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }

    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": jwt_assertion
    }

    response = requests.post(TOKEN_ENDPOINT, headers=headers, data=data)

    if response.status_code == 200:
        return response.json().get("access_token")
    else:
        raise Exception(f"Failed to get access token: {response.text}")

def kick_off_bulk_export(access_token):
    # Step 5: Kick-off a bulk data export
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/fhir+json"
    }

    response = requests.get(f"{BASE_URL}/Patient/$export", headers=headers, stream=True)

    if response.status_code == 202:
        return response.headers["Location"]
    else:
        raise Exception(f"Failed to kick-off bulk data export: {response.text}")

def poll_status(status_url):
    # Step 6: Poll status until completion
    while True:
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get(status_url, headers=headers)

        if response.status_code == 200 and "output" in response.json():
            return [link["url"] for link in response.json()["output"]]
        elif response.status_code == 202:
            time.sleep(5)  # Wait before polling again
        else:
            raise Exception(f"Failed to poll status: {response.text}")

def download_files(file_urls):
    # Step 7: Download NDJSON files
    for file_url in file_urls:
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get(file_url, headers=headers)

        if response.status_code == 200:
            with open(f"{datetime.now().strftime('%Y%m%d%H%M%S')_{file_url}.ndjson}", "wb") as file:
                file.write(response.content)
            print(f"Downloaded {file_url}")
        else:
            raise Exception(f"Failed to download file: {response.text}")

# Example usage
if __name__ == "__main__":
    client_assertion = "your_client_assertion_here"

    try:
        global access_token, status_urls
        access_token = get_access_token(client_assertion)
        status_url = kick_off_bulk_export(access_token)

        for url in poll_status(status_url):
            download_files([url])

```

### Explanation:

1. **get_access_token**: This function sends a POST request to the token endpoint with the client assertion and retrieves an access token.

2. **kick_off_bulk_export**: This function sends a GET request to kick-off a bulk data export and returns the URL from which you can poll status.

3. **poll_status**: This function polls for the completion of the bulk data export by making repeated GET requests to the status URL until it reaches a successful state (e.g., "export completed").

4. **download_files**: This function downloads NDJSON files from the provided file URLs.

### Error Handling:
- The script includes basic error handling using `try-except` blocks.
- It checks HTTP response codes and raises exceptions if something goes wrong.

### Comments:
- Basic comments are included to explain each step of the process.

