To create a FHIR bulk data export client for population health analytics using Epic's SMART on FHIR (OAuth 2.0) API, we need to follow these steps:

1. Register an app at App Orchard.
2. Generate RSA key pair and upload the public key.
3. Create a signed JWT assertion.
4. Exchange the JWT for an access token.
5. Kick-off a bulk data export.
6. Poll status until completion.
7. Download NDJSON files.

Below is a Python script using `requests` to achieve this:

```python
import requests
import time
from datetime import datetime, timedelta

# Constants
BASE_URL = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4"
TOKEN_ENDPOINT = f"{BASE_URL}/oauth2/token"

# RSA key pair and JWT assertion (not shown here for brevity)

def get_access_token(client_assertion):
    headers = {
        "Content-Type": "application/x-www-form-urlencoded",
    }
    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": client_assertion,
    }

    response = requests.post(TOKEN_ENDPOINT, headers=headers, data=data)
    if response.status_code == 200:
        return response.json().get("access_token")
    else:
        raise Exception(f"Failed to get access token: {response.text}")

def kick_off_bulk_export(access_token):
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json",
        "Accept": "application/fhir+json",
        "Prefer": "respond-async"
    }
    data = {
        "resourceType": "Patient",
        "status": "active"
    }

    response = requests.post(f"{BASE_URL}/Patient/$export", headers=headers, json=data)
    if response.status_code == 202:
        return response.headers["Content-Location"]
    else:
        raise Exception(f"Failed to kick off bulk export: {response.text}")

def poll_status(status_url):
    while True:
        time.sleep(5)  # Wait for 5 seconds before polling

        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get(status_url, headers=headers)
        if response.status_code == 200 and "output" in response.json():
            return [link["url"] for link in response.json()["output"]]
        elif response.status_code == 202:
            print("Export status: Waiting...")
        else:
            raise Exception(f"Failed to poll status: {response.text}")

def download_files(file_urls):
    headers = {
        "Authorization": f"Bearer {access_token}"
    }

    for file_url in file_urls:
        response = requests.get(file_url, headers=headers)
        if response.status_code == 200:
            with open(f"{datetime.now().strftime('%Y%m%d%H%M%S')}.ndjson", "wb") as ndjson_file:
                ndjson_file.write(response.content)

def main():
    global access_token

    # Step 1: Get an access token
    client_assertion = RSA_KEY_PAIR["signed_jwt"]  # Replace with your RSA key pair and JWT assertion
    access_token = get_access_token(client_assertion)

    # Step 2: Kick-off a bulk data export
    status_url = kick_off_bulk_export(access_token)

    # Step 3: Poll status until completion
    file_urls = poll_status(status_url)

    # Step 4: Download NDJSON files
    download_files(file_urls)

if __name__ == "__main__":
    main()
```

### Explanation:

1. **get_access_token**: This function sends a POST request to the token endpoint with your client assertion and gets an access token.

2. **kick_off_bulk_export**: This function sends a GET request to kick off a bulk data export for patients that are active.

3. **poll_status**: This function polls the status URL until it reaches completion (status code 200).

4. **download_files**: This function downloads NDJSON files from the provided URLs and saves them locally with a timestamp in their name.

### Error Handling:
- The script includes basic error handling to check HTTP response codes and raise exceptions if something goes wrong.
- You need to replace `RSA_KEY_PAIR["signed_jwt"]` with your actual RSA key pair and JWT assertion.

