    .catch((error) => tryAgain(() => axios.get(`${apiEndpoint}/${patientId}`, { params: { _format: 'json' } })) // log the full request and response
      .then((response) => console.error(`Error calling API, retrying... attempt 1/5: ${response.data}`))
      .catch((error2) => tryAgain(() => axios.get(`${apiEndpoint}/${patientId}`, { params: { _format: 'json' } })) // log the full request and response
        .then((response3) => console.error(`Error calling API, retrying... attempt 2/5: ${response3.data}`))
