          .catch((error2) => tryAgain(() => axios.get(`${apiEndpoint}/${patientId}`, { params: { _format: 'json' } } })) // log the full request and response
            .then((response5) => console.error(`Error calling API, retrying... attempt 4/5: ${response5.data}`))
            .catch((error1) => tryAgain(() => axios.get(`${apiEndpoint}/${patientId}`, { params: { _format: 'json' } } })) // log the full request and response
              .then((response6) => console.error(`Error calling API, retrying... attempt 5/5: ${response6.data}`))
              .catch((error2) => console.error('Max retries reached. Aborting.', error2));
      );
