const axios = require('axios');

function tryAgain(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      func();
      break;
    } catch (e) {
      if (!/retrying/.test(e.message)) { // log and retry only on non-retryable errors
        console.log(`Error calling API: ${e}`);
        setTimeout(() => tryAgain(func), 1000 * i); // wait for a second before trying again
      }
    }
  }
}

async function patientApiCall(patientId) {
