    console.log(`API call successful: ${url}`);
    return response.data;
  } else {
    tryAgain(() => axios.get(url), maxRetries=5).then((response) => {
      if (response.status >= 400 && response.status < 500) { // bad request, but not a server-side error
        console.log(`API call failed: ${url} - retrying`);
        setTimeout(() => tryAgain(() => axios.get(url), maxRetries=5).then((response)));
      } else {
        console.error(`Error calling API: ${url} - giving up`);
      }
    });
  }
}

