public class Hl7v2MessageValidator {
    public static void validate(String hl7v2Message) throws Exception {
        // Create an HL7 v2 message object from the input string
        Message hl7v2MessageObj = new Message(hl7v2Message);

        // Validate the MSH header segment
        Segment mshSeg = hl7v2MessageObj.getSegments().get(0);
        if (!validateMshSegment(mshSeg)) {
            throw new Exception("Invalid HL7 v2 message: " + hl7v2Message);
        }

        // Validate required segments and field lengths
        List<Segment> segList = hl7v2MessageObj.getSegments();
        for (int i = 1; i <= 3; i++) { // PID, PV1, or ORU segment(s) are required
            Segment seg = segList.get(i);
            if (!validateRequiredSegments(seg)) {
                throw new Exception("Invalid HL7 v2 message: " + hl7v2Message);
            }
        }

        // Validate field lengths for each segment
        for (Segment seg : segList) {
            for (int i = 0; i <= seg.getFields().size() - 1; i++) { // PID, PV1, or ORU segment(s)
                if (!validateFieldLength(seg, i + 1)) {
                    throw new Exception("Invalid HL7 v2 message: " + hl7v2Message);
                }
            }
        }
    }

    private static boolean validateMshSegment(Segment mshSeg) {
        // Validate the MSH header segment
        String sendingApplication = mshSeg.getField(3).getValue();
        if (sendingApplication == null || !isValidSendApp(sendingApplication)) {
            return false;
        }
        return true;
    }

    private static boolean validateRequiredSegments(Segment seg) {
