            if (seg.equals(reqSeg)) {
                return true;
            }
        }
        return false;
    }

    private static boolean validateFieldLength(Segment seg, int fieldIndex) {
        // Validate field lengths for each segment
        String fieldValue = seg.getField(fieldIndex).getValue();
        int fieldValueLen = fieldValue.length();

        if (seg.getSegmentId().equals("PID") && !isValidPidFieldValue(seg, fieldValueLen)) { // PID segment(s)
            return false;
