    // Check for versions 2.3 or below
    if (currentVersion === "2.3" || currentVersion < "2.4") {
        return setSegmentField(message, "MSH", 3, "2.5"); // Update the version to 2.5
    }

    return message; // No update needed
}

// Function to get a field from an HL7 segment
function getSegmentField(message, segmentName, fieldIndex) {
    var segments = message.split("\n");
    for (var i = 0; i < segments.length; i++) {
        if (segments[i].split("|")[1] === segmentName) { // Assuming the first segment is always MSH
            return segments[i].split("|")[fieldIndex];
        }
    }

    throw new Error("Segment or field not found in HL7 message");
}

// Function to set a field in an HL7 segment
function setSegmentField(message, segmentName, fieldIndex, newValue) {
    var segments = message.split("\n");
    for (var i = 0; i < segments.length; i++) {
        if (segments[i].split("|")[1] === segmentName) { // Assuming the first segment is always MSH
            return segments[i].replace(segmentName + "|" + fieldIndex, newValue);
        }
    }

