        var al1Child = al1Segment.getChild(0);
        allergyIntolerance.code = { coding: [{ system: "http://snomed.info/sct", code: "713463007" }] } };  // Code for Allergen Intolerance (Snomed CT)

        if (!al1Child.hasChildren()) {
            throw new Error("No child segments found in the AL1 segment.");
        }

        var al1Grandchild = al1Child.getChild(0);
        allergyIntolerance.subject = { reference: "Patient/" + al1Grandchild.getChild(3).toString() };  // Code for Patient ID (XCN-2.5)

        if (!al1Grandchild.hasChildren()) {
            throw new Error("No grandchild segments found in the AL1 segment.");
        }

        var al1GreatGrandchild = al1Grandchild.getChild(0);
        allergyIntolerance.onsetDateTime = al1GreatGrandChild.getChild(3).toString();  // Code for Allergen Onset Date/Time (AL1-2.5)

    } catch (e) {
