```
const axios = require('axios');

function tryAgain(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      func();
      break;
    } catch (error) {
      if (!/retrying/.test(error.message)) {
        console.log(`Error calling API: ${error}`);
        if (i < maxRetries) {
          console.log(`Retrying... attempt ${retries+1}/${maxRetries}`);
          setTimeout(() => tryAgain(func, maxRetries), 1000); // wait for a second before retrying
        } else {
          throw error;
        }
      }
    }
    retries++;
  }
}
```
This code defines a simple `tryAgain` function that takes an API call as input and attempts to execute it up to `maxRetries` times. If the first attempt fails, it logs the full request and response using axios' built-in logging mechanism.

