As a healthcare integration expert specializing in mirth, I'll provide you with a comprehensive solution to create an HL7 v2 message validator using JavaScript.

**Why?**

To ensure the integrity of our healthcare data exchange, we need to validate incoming messages against specific rules and constraints. We'll focus on checking MSH header, required segments, and field lengths for this example.
```javascript
// Import required libraries
const hl7 = require('hl7-js');
const { HL7Message } = require('@mirth/connect-client');

// Define a function to validate an HL7 v2 message
function validateHl7Message(message) {
  // Check MSH header (1.3)
  if (!message.getMSH().getHeader(1).getValue()) throw new Error('Invalid MSH header');

  // Verify required segments and field lengths
  const requiredSegments = ['PID', 'PV1'];
  hl7.segments.forEach((segment) => {
    if (requiredSegments.includes(segment.getName())) {
      if (!segment.getFieldLength()) throw new Error(`Invalid ${segment.getName()} segment: ${segment.getValue()}`);
    }
  });

  // Check for any errors
  if (!/^[A-Z0-9_-]+$/.test(message.getMSH().getHeader(1).getValue())) throw new Error('Invalid MSH header');
}
```
