import org.hl7.v3.MSH;
import org.hl7.v3.Segment;

public class Hl7v2MessageValidator {
    public static void validate(String hl7Message) throws Exception {
        // Parse HL7 message into an MSH segment object
        MSH msh = new MSH(hl7Message);

        // Validate required segments and field lengths
        if (!validateRequiredSegments(msh)) throw new Exception("Invalid HL7 message: " + hl7Message);
        if (!validateFieldLengths(msh)) throw new Exception("Invalid HL7 message: " + hl7Message);

    }

    private static boolean validateRequiredSegments(MSH msh) {
        // Check for required segments (MSH, PID, PV1)
        Segment pid = msh.getSegment(MSH.SEGMENT_PID);
        Segment pv1 = msh.getSegment(MSH.SEGMENT_PV1);

        return pid != null && pv1 != null;
    }

    private static boolean validateFieldLengths(MSH msh) {
        // Check for required field lengths (MSH-3, PID-5, PV1-2)
        int msh3Len = msh.getSegment(MSH.SEGMENT_MSH).getFieldValue(MSH.SEGMENT_MSH.FIELD_MSH_3()).length();
        int pid5Len = msh.getSegment(MSH.SEGMENT_PID).getFieldValue(MSH.SEGMENT_PID.FIELD_PID_5()).length();

        return (msh3Len >= 10) && (pid5Len >= 20);
    }
}
```
