To create a Mirth channel filter that drops duplicate messages based on the `MSH-10` (Message Control ID) segment, we'll use JavaScript as our scripting language.

**Filter Code:**
```javascript
// Set the filter name and description
var FILTER_NAME = "Drop Duplicates";
var FILTER_DESC = "Remove duplicates from incoming messages";

// Define a function to drop duplicate messages based on MSH-10 control ID
function dropDuplicates(message) {
  // Get the message's MSH-10 segment (Message Control ID)
  var msh10 = message.getSegment("MSH").getComponent(10).getValue();

  // Check if this is not a new message (i.e., it's already been processed)
  if (!msh10.startsWith("NEW")) {
    // If we reach this point, then we have a duplicate! Drop the message!
    return false;
  }

  // Otherwise, let's allow this message to pass through
  return true;
}

// Define our filter function
function filter(message) {
  // Check if we're dealing with an incoming message (i.e., not an outgoing)
  if (!message.getDirection().equals("OUTBOUND")) {
    // If it is an incoming message, then let's drop any duplicates!
    if (!dropDuplicates(message)) {
      return false;
    }
  }

  // Otherwise, allow this message to pass through
  return true;
}

// Set our filter function as the value for this filter
filter = filter;

// Define a variable to store the original message (in case we need it)
var originalMessage = null;

// Iterate over each incoming message (i.e., segment) in our channel
for (segment in message.getSegments()) {
  // If this is an MSH-10 segment, then let's check if it's not a duplicate!
  if (segment.getComponent(1).getValue().equals("MSH") && segment.getComponent(2).getValue().startsWith("NEW")) {
    // If we reach this point, then we have a new message! Allow it to pass through.
    originalMessage = message;
  } else {
    // Otherwise, let's drop any duplicates (i.e., duplicate MSH-10 segments)
    if (!dropDuplicates(originalMessage)) {
      return false; // Drop the message!
    }
  }
}
```
