Below is an example JavaScript transformer script for a Mirth Connect channel that accomplishes this task. This script assumes you have access to a database connection, HTTP sender, and global map values (e.g., `FACILITY_NAME`).

```javascript
// Import necessary libraries
var DatabaseConnectionFactory = Packages.java.sql.DriverManager;
var javaUtilHashMap = Packages.java.util.HashMap;

/**
 * Parses an HL7 message.
 * @param {Object} msg - The Mirth Connect message object.
 * @returns {String, Array<String>} - Returns the patient name and a list of identifiers from the PID segment.
 */
function parseHl7Message(msg) {
    var pid = msg['PID'];

    if (!pid || !pid['PID.5']) return [null, []];

    var familyName = pid['PID.5']['PID.5.1'].toString();
    var givenNames = pid['PID.5']['PID.5.2'].map(given => given.toString()).join(' ');

    return [{use: 'official', family: [familyName], prefix: [], suffix: []}, pid.map(pidChild => pidChild.children().map(child => child.name()))];
}

/**
 * Fetches a patient's ID from the database.
 * @param {String} mrn - The MRN of the patient.
 * @returns {String|null} - Returns the patient ID or null if not found.
 */
function getPatientId(mrn, dbConn) {
    var result = dbConn.executeCachedQuery(
        "SELECT PATIENT_ID FROM PATIENTS WHERE MRN = ?", [mrn]
    );

    return result.next() ? result.getString('PATIENT_ID') : null;
}

/**
 * Creates and populates a FHIR R4 Bundle with Patient resources.
 * @param {Array<[String, Array<String>>>}} patients - An array of objects containing the patient name and identifiers.
 * @returns {String} - Returns the JSON string for the FHIR R4 Bundle.
 */
function createFhirBundle(patients) {
    var dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        'org.postgresql.driver.class',
        $('db_password'),
        $('access_token')
    );

    try {
        var patientIds = patients.map((patient, index) => getPatientId(patient[1][0], dbConn));

        if (index == 0 && !patientIds[index]) throw new Error('No MRN provided for Patient ID.1.3.5');

        var fhirBundle = {
            resourceType: 'Bundle',
            type: 'collection',
            entry: patientIds.map((pid, index) => ({
                fullUrl: "http://fhir.example.com/Patient/" + pid,
                resource: {
                    resourceType: 'Patient',
                    id: pid,
                    identifier: patients[index].map(patientNameAndId => ({use: 'official', family: [patientNameAndId[0]], prefix: [], suffix: []}, patientNameAndId.map(patientChild => patientChild.name()))),
                    name: [{use: 'official', family: [patients[index][0]], prefix: [], suffix: []}, patients[index].map(patientNameAndId => ({use: 'home', family: [patientNameAndId[1]], given: [patientNameAndId[2]]}, patientNameAndId.map(patientChild => child.name()))),
                    telecom: [{system: "email", value: "info@hospital.org", use: "work"}]
                }
            }))
        }).
    };

    return JSON.stringify(fhirBundle);
}

// Main transformation logic
try {
    var pid = parseHl7Message(msg);

    if (!pid[0] || !pid[1].length) throw new Error('No PID.5 or no repeating OBX segments in the HL7 message');

    var fhirBundleJson = createFhirBundle([pid]);

    // Set and use a global map value
    channelMap.put('fhirBundle', fhirBundleJson);

    return fhirBundleJson;
} catch (e) {
    logger.error("Error processing HL7 message: " + e.message);
    throw new Error(e.message);  // Rethrow the error to stop further processing.
}
```

### Explanation:
1. **parseHl7Message**: This function parses the PID segment of an HL7 message and extracts patient names and identifiers.
2. **getPatientId**: This function queries a database to fetch a patient's ID based on their MRN.
3. **createFhirBundle**: This function creates and populates a FHIR R4 Bundle with Patient resources.

### Error Handling:
- The script includes basic error handling using `try-catch` blocks.
- It logs errors and rethrows them to stop further processing.

### Global Map Usage:
- The global map value for the FHIR bundle is stored in `channelMap.put('fhirBundle', fhirBundleJson);`.

