public class Hl7v2SegmentParser {
    public static void parse(HL7v2Message message) throws Exception {
        // Get the segment(s) from the message
        List<HL7v2Segment> segments = new ArrayList<>();
        for (String segment : message.getSegments()) {
            HL7v2Segment hl7v2Segment = new HL7v2Segment(segment);
            segments.add(hl7v2Segment);
        }

        // Loop through each segment and parse its fields
        for (HL7v2Segment segment : segments) {
            String fieldSeparator = "|"; // default value, can be updated to a custom value if needed

            while (!segment.isEmpty()) {
                HL7v2Field field = new HL7v2Field(segment.substring(0, segment.indexOf("|")));
                if (field.getRepetitions() > 1) { // repeating fields have multiple values
                    for (int i = 0; i <= field.getRepetitions(); i++) {
                        System.out.println("Field: " + field.getName() + " (" + i + ")");
                        parse(field.getValue()); // recursively parse the value of this field
                    }
                } else {
                    System.out.println("Field: " + field.getName());
                    parse(field.getValue()); // recursively parse the value of this field

                    segment = segment.substring(segment.indexOf("|") + 1);
                }

                if (segment.isEmpty()) { // no more fields, exit loop
                    break;
                }
            }
        }
    }

