from fastapi import Depends, HTTPException
from sqlalchemy import create_engine, Column, Integer, String
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

# Create an engine for the database (in this case SQLite)
engine = create_engine('sqlite:///patient_records.db')

# Create a table to store patient records in the database
Base = declarative_base()

class PatientRecord(Base):
    __tablename__ = 'patients'
    id = Column(Integer, primary_key=True)
    name = Column(String)

# Create an instance of SQLAlchemy's Base class and define how it should map to your Python objects
base = Base

# Create a session for the database (in this case SQLite)
Session = sessionmaker(bind=engine)

class PatientAPI(FastAPI):
    def __init__(self):
        self.session = Session()

    @api.text('Create', 'Application/JSON')
    def create_patient_record(self, request: Request):
        patient_record = base()
        patient_record.name = request.json['name']
        return self.session.add(patient_record)

    @api.text('Read', 'Application/JSON')
    def read_patient_records(self):
        for record in self.session.query(base).all():
            return {'id': record.id, 'name': record.name}

    @api.text('Update', 'Application/JSON')
    def update_patient_record(self, request: Request):
        patient_record = self.session.query(base).filter_by(id=request.json['id']).first()
        if not patient_record:
            raise HTTPException(404)
        for key in [k for k in request.json]:
            setattr(patient_record, key, request.json[key])
        return self.session.commit()

    @api.text('Delete', 'Application/JSON')
    def delete_patient_record(self, request: Request):
        patient_record = self.session.query(base).filter_by(id=request.json['id']).first()
        if not patient_record:
            raise HTTPException(404)
        for record in [record for record in self.session.query(base) if record.name == patient_record.name]:
            return self.session.delete(record)

    @api.text('Get', 'Application/JSON')
    def get_patient_records(self, request: Request):
        return {'id': record.id, 'name': record.name} for record in self.session.query(base).all()

if __name__ == '__main__':
    api = PatientAPI()
    app = FastAPI(api=api)
```

