public class Hl7v2SegmentParser {
    public static void parseHl7v2Segment(String hl7v2Segment) throws Exception {
        // Regular expression pattern for matching the HL7 v2 segment format (e.g. PID-1: Patient Name)
        String regexPattern = "^[A-Z0-9_-]+";

        List<String> segments = new ArrayList<>();

        while (hl7v2Segment.matches(regexPattern)) {
            // Extract the individual segment components (e.g. patient name, SSN, MRN) using a regular expression
            String[] segmentComponents = hl7v2Segment.split("([A-Z0-9_-]+)(?:~|\\S+)?");

            for (String component : segmentComponents) {
                if (!component.isEmpty()) {
                    // Handle escaped delimiters (e.g. ~, \^)
                    int delimiterIndex = component.indexOf("|");
                    String patientName = component.substring(0, delimiterIndex);
                    String[] nameParts = patientName.split("\\s*");

                    System.out.println("Patient Name: " + nameParts[0] + " " + nameParts[1]);

                    // Handle null fields (e.g. ~)
                    if (!component.equals("~")) {
                        System.out.println("SSN/MRN: " + component);
                    }
                }
            }

            hl7v2Segment = segmentComponents[segmentComponents.length - 1];
        }
    }
}
