// Function to parse the incoming HL7 v2.3 message
function parseHl7Message(message) {
    var parsedMessage = {};

    // Example segment names and field indices for simplicity
    var pidSegmentName = "PID";
    var pd1SegmentName = "PD1";

    if (message.get("MSH").get(9).toString().includes(pidSegmentName)) {
        parsedMessage.pid = message.get(pidSegmentName);
    }

    if (message.get("MSH").get(9).toString().includes(pd1SegmentName)) {
        parsedMessage.pd1 = message.get(pd1SegmentName);
    }

    return parsedMessage;
}

