function updateAdtMessage(parsedMessage) {
    var adtMessage = new com.mirth.connect.model.datatypes.HL7v25.Message();

    // Example segment names and field indices for simplicity
    var pidSegmentName = "PID";
    var pd1SegmentName = "PD1";

