        adtMessage.get(pidSegmentName).set(3, parsedMessage.pid.get(2).toString());  // Update PID-3.2 to ADT-PID-3.2
        adtMessage.get(pidSegmentName).set(4, parsedMessage.pid.get(5).toString());  // Update PID-4.1 to ADT-PID-4.1
    }

    if (parsedMessage.pd1 != null) {
        adtMessage.getPd1().set(3, parsedMessage.pd1.get(2).toString());  // Update PD1-3.2 to ADT-PD1-3.2
        adtMessage.getPd1().set(4, parsedMessage.pd1.get(5).toString());  // Update PD1-4.1 to ADT-PD1-4.1
    }

    return adtMessage;
}

// Main transformer logic
