  var channelConfig = router.getChannel();

  // Create an E4X XML writer to write the output file
  var xmlWriter = java.io.FileWriter(filePath);
  var e4xXmlWriter = org.apache.axis2.AxisException.createXMLSerializer();
  e4xXmlWriter.setIndent(32);

  // Loop through each channel config element and export it as E4X XML
  for (var prop in channelConfig) {
    var propValue = channelConfig[prop];
    if (prop instanceof java.lang.String) {
      xmlWriter.write('<' + prop + '>' + propValue + '</' + prop + '>\\r\n');
    } else if (prop instanceof org.apache.axis2.AxisException.ChannelMap) {
      for each (var key in prop.keySet()) {
        var keyValue = prop.get(key);
        if (keyInstanceof(org.apache.axis2.AxisException.ChannelConfig)) {
          xmlWriter.write('<' + key.getName() + '>' + keyValue.getChannel().getLocalName() + '</' + key.getName() + '>\\r\n');
        } else if (keyInstanceof(org.apache.axis2.AxisException.ChannelMap)) {
          for each (var subKey in keyValue.keySet()) {
            var subKeyValue = keyValue.get(subKey);
            xmlWriter.write('<' + key.getName() + '/' + subKey.getName() + '>' + subKeyValue.getChannel().getLocalName() + '</' + key.getName() + '/' + subKey.getName() + '>\\r\n');
          }
        }
      }
    }
  }

  // Close the E4X XML writer
  xmlWriter.close();
