This script will parse the MSH-9 event type and route messages based on it.

```javascript
// Example transformer script

try {
    var hl7Message = msg; // The incoming HL7 message

    if (!hl7Message) {
        log.error("No HL7 message received.");
        throw new Error("No HL7 message received.");
    }

    var msh9Event = parseMsh9(hl7Message); // Parse the MSH-9 event type

    if (msh9Event && isValidEvent(msh9Event)) {
        routeMessageBasedOnEventType(msh9Event, hl7Message); // Route messages based on the MSH-9 event type
    } else {
        log.warn("Invalid HL7 message received: " + msh9Event);

        throw new Error("Invalid HL7 message received.");
    }
} catch (e) {
    log.error("Transformer error: " + e.message);
    throw e; // Rethrow the exception to stop processing
}

function parseMsh9(hl7Message) {
    var msh9Event = hl7Message.getSegment("MSH").getField(9); // Extract MSH-9 event type from HL7 message

    if (msh9Event && !isValidEventType(msh9Event)) {
        log.warn("Unsupported E4X segment: " + msh9Event);

        throw new Error("Unsupported E4X segment: " + msh9Event);
    }

    return msh9Event;
}

function isValidEvent(eventType) {
    // List of supported event types
    var supportedEvents = ["ADT^A01", "ORU^R01", "OBR^O03"];

    for (var i in supportedEvents) {
        if (eventType === supportedEvents[i]) {
            return true;
        }
    }

    return false;
}

function routeMessageBasedOnEventType(eventType, hl7Message) {
    var destinationNames = ["Destination A", "Destination B", "Destination C"]; // Example destinations

    for (var i in destinationNames) {
        var destinationName = "Destination " + i;

        try {
            channelMap.put(destinationName, new ChannelMap().put("message", hl7Message.toString()), new ChannelMap().put("contentType", "application/hl7")).save(); // Save the message to a specific destination

            log.info("Message routed to " + destinationName);
        } catch (e) {
            log.error("Failed to route message to " + destinationName + ": " + e.message);

            throw new Error("Failed to route message to " + destinationName);
        }
    }

    return eventType;
}
```

