To create a patient search API in Mirth Connect using HL7 v2, we need to follow these steps:

1. Define an HTTP Listener connector to receive incoming requests.
2. Parse the incoming message (HL7v2) to extract relevant information.
3. Perform the database query to retrieve patient data based on the provided parameters.
4. Log the search parameters for debugging and auditing purposes.

Below is a complete Mirth Connect script that fulfills this request:

```javascript
// Define an HTTP Listener connector to receive incoming requests

function handleIncomingMessage(message) {
    try {
        // Parse the incoming message (HL7v2)
        var pidSegment = getPIDSegmentFromMessage(message);

        if (!pidSegment) {
            log.error("No PID segment found in the HL7 message.");
            throw new Error("Invalid HL7 format");
        }

        // Extract patient details from the PID segment
        var familyName = pidSegment[5][1].toString();
        var givenNames = pidSegment[5][2].toString().split('^');
        var mrn = pidSegment[3][1].toString();

        if (!familyName || !givenNames.length) {
            log.error("Patient name details are missing.");
            throw new Error("Invalid HL7 format");
        }

        // Perform the database query to retrieve patient data
        var dbConn = DatabaseConnectionFactory.getDatabaseConnection(
            'org.postgresql.Driver',
            'jdbc:postgresql://localhost:5432/clinical',
            $('db_user'), $('db_password')
        );

        try {
            var result = dbConn.executeCachedQuery(
                "SELECT * FROM patients WHERE family_name = ? AND given_names = ? AND mrn = ?", [familyName, givenNames.join('^'), mrn]
            );

            if (!result.next()) {
                log.info("No patient data found for the provided parameters.");
                throw new Error("Patient not found");
            }

            // Log the search parameters
            var logMessage = "Search Parameters - Family Name: " + familyName + ", Given Names: " + givenNames.join('^') + ", MRN: " + mrn;
            log.info(logMessage);

            // Return a success message from the API (optional)
            return "<apiResponse><status>0</status><data>No data to return.</data></apiResponse>";

        } finally {
            dbConn.close();
        }
    } catch (e) {
        log.error("Database query failed: " + e.message);
        throw new Error("Failed to retrieve patient data from the database");
    }

    // Log any errors that occur during processing
    var errorMessage = "Error Processing Message - " + pidSegment[1][1].toString();
    log.error(errorMessage);

    // Return an error message from the API (optional)
    return "<apiResponse><status>500</status><data>Error processing request.</data></apiResponse>";

}

// Function to extract the PID segment from a HL7v2 message
function getPIDSegmentFromMessage(message) {
    var pidSegments = message.get("pid");

    if (!pidSegments || !pidSegments.length) {
