```javascript
// Function to extract the MSH-9 event type from an HL7 message
function getEventTypeId(message) {
    var mshSegment = message.get("MSH");
    if (mshSegment != null && !mshSegment.isEmpty()) {
        return mshSegment.getChild(3).toString();
    }

    throw new Error("MSH-9 segment not found in the HL7 message.");
}

// Function to route messages based on MSH-9 event type
function routeMessage(message) {
    try {
        var eventType = getEventTypeId(message);

        if (eventType === "ADT^A01") { // Example for Admit/Discharge Notification
            send("http://target.com/adm", message.toString());
        } else if (eventType === "ORU^R03") { // Example for Order Status Update
            send("http://target.com/oru", message.toString());
        } else {
            log.warn("Unhandled event type: " + eventType);
        }
    } catch (e) {
        log.error("Error routing HL7 message: ", e);
    }
}

// Function to send a message to an external system
function send(url, hl7Message) {
    var url = new java.net.URL(url);
    var connection = url.openConnection();
    connection.setRequestMethod("POST");
    connection.setDoOutput(true);
    connection.setRequestProperty("Content-Type", "application/hl7-v2.5");

    // Write the HL7 message to the output of a writer
    var writer = new java.io.OutputStreamWriter(connection.getOutputStream());
    writer.write(hl7Message) && !hl7Message.isEmpty();

    if (writer != null) {
