  }

  // Loop through each field in the original message
  for (var fld : seg.getFields()) {
    // Check if the field is an MSH-2 (Sending Application) field
    if (!fld.getComponent(1).toString().equals("MSH-2")) {
      // If not, exit this transformer
      return;
