      // Check if the component is an MSH-3 (Receiving Facility) field
      if (!cmp.getComponent(1).toString().equals("MSH-3")) {
        // If not, exit this transformer
        return;
      }

      // Upgrade the original message to version 2.5
      msg.getSegments()[0].getFields()[0].getComponents()[0] = cmp.getComponent(1) + " " + cmp.getComponent(2);
    }
  }
}
