```
const axios = require('axios');

function tryAgain(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      func();
      break;
    } catch (error) {
      if (!/timeout/.test(error.message)) {
        console.error(`Error calling API: ${error}`);
        return;
      }
      retries++;
      if (retries < maxRetries) {
        console.log(`Retrying... attempt ${i+1}/${maxRetries}`);
        setTimeout(() => func(), 1000 * i); // wait for 1 second before retrying
      } else {
        console.error('Failed to connect to API. Aborting.');
        return;
      }
    }
  }
}

async function tryAgainAsync(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      await func();
      break;
    } catch (error) {
      if (!/timeout/.test(error.message)) {
        console.error(`Error calling API: ${error}`);
        return;
      }
      retries++;
      if (retries < maxRetries) {
        console.log(`Retrying... attempt ${i+1}/${maxRetries}`);
        setTimeout(() => func(), 1000 * i); // wait for 1 second before retrying
      } else {
        console.error('Failed to connect to API. Aborting.');
        return;
      }
    }
  }
}

// Example usage:
async function getPatientApi() {
  try {
    await axios.get(`https://api.example.com/patient`);
  } catch (error) {
    tryAgainAsync(() => getPatientApi());
  }
}
```
