// Define the conversion function
function convertAdt(adtMessage) {
  // Create an empty HL7 v2.5.1 message
  var adt25_01 = new hl7.Message();

  // Set the MSH-3 (message type) segment to "ADT"
  adt25_01.addSegment(new hl7.Segment("MSH", "ADT"));

  // Loop through each PID-1 (patient identification) segment in the original message
  for (var i = 0; i < adtMessage.getSegments().size(); i++) {
    var pid = adtMessage.getSegments()[i];
    if (pid.getComponent(3).getValue() != null) { // Check for a non-null Patient ID value

      // Create an empty PID-1 segment
      var newPid = new hl7.Segment("PID", "1");

      // Set the patient identification fields
      newPid.addComponent(new hl7.Component("XPN", pid.getComponent(3).getValue()));
      newPid.addComponent(new hl7.Component("XCN", pid.getComponent(4).getValue()));

      // Add the PID-1 segment to our converted message
      adt25_01.addSegment(newPid);
    }
  }

  return adt25_01;
}

// Define a sample input ADT v2.3 message (in this case, an "ADT_A04" (Patient Update) message)
