```typescript
import * as fs from 'fs';
import * as xml2js from 'xml2js';

const fhirSchemaR4 = require('fhir-schema-r4');

function validateFhirJson(fhirJson: string): boolean {
  const fhirXml = new XML('<FHIR><' + fhirJson.replace(/[^A-Z]/g,'') + '</FHIR>')[0].toString();
  try {
    // Load the FHIR schema R4 XML file
    const fhirSchemaR4Xml = fs.readFileSync('/path/to/fhir-schema-r4-2.0.1.xml', 'utf8');
    const fhirSchemaR4XmlObj: any = xml2js.parseString(fhirSchemaR4Xml);

    // Create a new FHIR R4 XML document
    const fhirR4XmlDoc = new XML('<FHIR><' + fhirJson.replace(/[^A-Z]/g,'') + '</FHIR>')[0].toString());
  } catch (err) {
    console.error('Error loading the FHIR schema R4 XML file:', err);
    return false;
  }

  try {
    // Validate the FHIR R4 JSON against the official schema
    const fhirValidator = new fhirSchemaR4.FhirValidator();
    if (!fhirValidator.validate(fhirXmlDoc, fhirSchemaR4XmlObj)) {
      console.error('Error validating the FHIR R4 JSON:', err);
      return false;
    }
  } catch (err) {
    console.error('Error validating the FHIR R4 JSON:', err);
    return false;
  }

  // If we reach this point, that means our validation was successful!
  console.log(`FHIR R4 JSON validated successfully! ${fhirJson}`);
  return true;
}

// Example usage:
const fhirJson = '<FHIR><Patient><name><given>' + 'John' + '</given></name></Patient></FHIR>';
