// Function to generate a signed JWT assertion
function createJwtAssertion() {
  const payload = {
    iss: CLIENT_ID,
    aud: TOKEN_ENDPOINT,
    exp: Math.floor(new Date().getTime() + (60 * 5)), // Token expires in 5 minutes
  };

  with (jwt) {
    return encode(payload, PRIVATE_KEY_PATH);
}

// Function to exchange the JWT for an access token
async function getAccessToken() {
  try {
    const jwtAssertion = createJwtAssertion();
    const response = await axios.post(TOKEN_ENDPOINT, `grant_type=client_credentials&assertion=${jwtAssertion}`, {
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
    });

    if (response.status === 200) {
      return response.data.access_token;
    } else {
      throw new Error('Failed to get access token');
    }
  } catch (error) {
    console.error(error);
    throw error;
  }
}

// Function to make a request with an authorization header
async function makeRequest(url, method = 'GET', headers = {}) {
  try {
    const accessToken = await getAccessToken();
    const response = await axios.request({
      url,
      method: method.toLowerCase(),
      data: headers.data ? { [headers.name]: headers.data } : null,
      params: headers.params || {},
      headers: {
        ...{ Authorization: `Bearer ${accessToken}` },
        ...headers,
      },
    });

    if (response.status === 200) {
      return response.data;
    } else {
      throw new Error(`Failed to make request. Status code: ${response.status}`);
    }
  } catch (error) {
    console.error(error);
    throw error;
  }
}

