**Segment Parser Code**
```python
import re

def parse_hl7_segment(segment):
    """
    Parse an HL7 v2 segment (MSH, PID, PV1, etc.) into individual fields and values.

    Args:
        * segment: The raw HL7 v2 segment string (e.g. "MSH|^~\&|1234567890|...")

    Returns:
        A dictionary containing the parsed field names (Field Separator) and values (Component).
    """
    def _parse_field(name, value):
        """
        Parse a single field into its constituent parts (component(s)).

        Args:
	        * name: The HL7 v2 segment field name (e.g. "PID-1" for Patient ID).
	        * value: The raw HL7 v2 field value (string).
	"""
	components = []
	for i, c in enumerate(re.finditer(r"([0-9]+)([^\s]*)", value)):
		if not i:
			component = f"{name}{c}"
		else:
			component += f"{c}~{c}"
	components.append(component)
	return dict(zip(components, [value] * len(components)))

    parsed_segment = {}
	for field in segment.split("|"):
		if field.startswith("MSH"):  # MSH segment (only)
			parsed_segment["Field Separator"] = "|"
		else:
			parsed_segment[field[:3]] = _parse_field(field[4:], value=re.sub(r"~", "", field))
	return dict(**parsed_segment)

# Example usage
