// Pre-processor script for Mirth

// Define a function to validate the HL7 message structure
function validateHl7Message(message) {
  // Check if the message is not null or empty
  if (message == null || !message.isEmpty()) {
    try {
      // Get an E4X XML Access object from the Mirth context
      var hl7 = org.milyn.xml.HL7.getXml(message);

      // Validate the HL7 segment structure using a regular expression
      var regex = /MSH\|.*?~\&/; // example: MSH-1 (Message Header) followed by any characters (~\^~\)
      if (!hl7.matches(regex)) {
        throw new Error("Invalid HL7 message structure");
      }
    } catch (e) {
      // Log an error if the validation fails
      log.error("Error validating HL7 message: " + e.getMessage());
      return false;
    }
  }

  // If we reach this point, it means the message is null or empty. Return true to indicate success.
  return true;
}

// Call the function and store its result in a variable
var isValid = validateHl7Message(getInboundMessage());

if (!isValid) {
  // If the validation fails, stop processing and log an error
  log.error("Invalid HL7 message structure: " + getInboundMessage());
}
