}

function sendRequest(url, method, data, contentType) {
    var client = java.net.URL(url).openConnection();
    client.setRequestMethod(method);

    if (method === "POST") {
        client.setDoOutput(true);

        // Write the data
        var outputStream = client.getOutputStream();
        var writer = new java.io.OutputStreamWriter(outputStream, true);
        writer.write(data);
        writer.flush();

        // Read and log the response
        var inputStream = client.getInputStream();
        var reader = new java.io.InputStreamReader(inputStream, true);
        var line;

        while ((line = reader.readLine())) {
            log.info(line);

        }
    }

    return { status: client.getResponseCode(), text: readAllFromReader(reader) };

}

function readAllFromReader(reader) {
    var output = java.lang.System.out;
    var buffer = new Array(1024);

    for (var line in reader.lines()) {
        System.arraycopy(reader.read(java.nio.ByteBuffer.allocate(1024)), 0, buffer, 0, java.nio.ByteBuffer.intValue(java.nio.ByteBuffer.isClear(buffer), 0, buffer.length) ? -1 : buffer[buffer.length-1]));

        if (java.lang.System.out != output) {
            output.write(line);
            output.flush();
        }
    }

    return new String(buffer);

}
