// Define a function to validate the HL7 message structure
function validateHl7Message(msg) {
  // Check if the message has at least one segment (MSH)
  if (!msg.children().isEmpty()) {
    // Get the MSH segment
    var mshSeg = msg.children()[0];

    // Validate the MSH-3 field (message type)
    if (!mshSeg.child("MSH-3").toString().matches(/^[A-Z]{3}$/)) {
