      throw new Error("Invalid HL7 message: " + mshSeg.child("MSH-4").toString());
    }

    // ... add more validation logic as needed ...
  } else {
    throw new Error("Invalid HL7 message");
  }
}

// Call the function to validate the HL7 message structure
