// Function to parse an HL7 message and extract necessary information
function parseHl7Message(hl7Message) {
  try {
    const parsedMessage = new HL7Message(hl7Message);

    // Extract MSH-9 (Event Type)
    const eventType = parsedMessage.getSegment('MSH').getField(9, 1);

    // Extract MSH-5 (Receiving Facility)
    const receivingFacility = parsedMessage.getSegment('MSH').getField(5, 1);

    return { eventType, receivingFacility };
  } catch (error) {
    log.error(`Error parsing HL7 message: ${error}`);
    throw new Error("Failed to parse HL7 message");
  }
}

// Function to route the message based on MSH-9 and MSH-5
function routeMessage(hl7Message, parsedData) {
  try {
    // Example routing logic (this should be dynamically generated based on your environment)
    if (parsedData.eventType === 'ADT^A04' && parsedData.receivingFacility === 'HOSPITAL') { // Admit/Discharge Notification - Hospital
      log.info(`Routing message for ADT-04 - HOSPITAL`);

      // Example of routing logic (this should be dynamically generated based on your environment)
      routeTo('admission-discharge-channel-id', hl7Message);
    } else if (parsedData.eventType === 'ORU^R01' && parsedData.receivingFacility === 'LAB') { // Order/Results Notification - Laboratory
      log.info(`Routing message for ORU-R01 - LAB`);

      // Example of routing logic (this should be dynamically generated based on your environment)
      routeTo('laboratory-results-channel-id', hl7Message);
    } else {
      throw new Error("Unsupported event type or receiving facility");
    }
  } else {
    log.info(`Routing message for unknown MSH-9 and MSH-5`);

    // Example of routing logic (this should be dynamically generated based on your environment)
    routeTo('default-channel-id', hl7Message);
  }
}

