// Function to parse FHIR R4 CarePlan and extract relevant data
function parseFhirCarePlan(carePlan) {
    var careProvider = carePlan.careProvider[0];
    var patientId = careProvider.identifier[0].system + "_" + careProvider.identifier[0].value;

    return { 
        careProvider: careProvider.name.family + " " + careProvider.name.given.join(" ") ,
        patientId: patientId
    };
}

// Function to construct and format the HL7 v2 segment(s)
function buildHl7v2Segment(carePlanData) {
    var hl7v2Segment = "MSA|AA|" + carePlanData.careProvider + "|" + carePlanData.patientId;

    return [hl7v2Segment];
}

// Main function to handle the conversion
function convertToFhirHl7v2(fhirCarePlan, hl7v2Segments) {
