```javascript
// Function to parse FHIR R4 CarePlan and extract relevant data
function parseFhirCarePlan(carePlan) {
    var patientName = carePlan.patient.display + " (" + carePlan.patient.family + ", " + carePlan.patient.given.join(" ") + ")";
    var patientId = carePlan.identifier[0].system + "_" + carePlan.identifier[0].value;

    // Example of extracting other relevant data
    var procedureCode = carePlan.extension.find(function(extension) {
        return extension.url === "http://example.com/procedure-code"
    });
    if (procedureCode) {
        var procedureName = procedureCode.text;
    } else {
        procedureName = "Unknown Procedure";
    }

    // Example of extracting other relevant data
    var practitionerId = carePlan.participant[0].individual.display + " (" + carePlan.participant[0].individual.family + ", " + carePlan.participant[0].individual.given.join(" ") + ")";
    var practitionerName = practitionerId;

    return {
        patientName: patientName,
        patientId: patientId,
        procedureCode: procedureName,
        practitionerId: practitionerId
    };
}

// Function to construct and format the HL7 v2 segment(s)
function createHl7v2Segment(carePlanData) {
    var hl7v2Segment = "MSH|^~\\&|Mirth Connect||Target System||20230401123456+0800||ORU^R01^O01|123456789|P|2.5\r";

    // Example of constructing and formatting the HL7 v2 segment(s)
    hl7v2Segment += "EVN|^~\\&|20230401123456+0800||||\r";
    hl7v2Segment += carePlanData.patientName + "^" + carePlanData.patientId + "^Patient^" + carePlanData.procedureCode + "^Procedure^" + carePlanData.practitionerId + "\r";

    return hl7v2Segment;
}

// Main function to handle the conversion
function convertToFhirHl7(carePlan) {
    try {
        var fhirCarePlan = parseFhirCarePlan(carePlan);

        // Construct and format the HL7 v2 segment(s)
        var hl7v2Segment = createHl7v2Segment(fhirCarePlan);

        return hl7v2Segment;
    } catch (e) {
        logger.error("Error during conversion: " + e.message);
        throw new Error("Failed to convert FHIR R4 CarePlan to HL7 v2 Segment(s)");
    }
}

