```java
import org.hl7.v3.MSH;
import org.hl7.v3.Segment;

public class Hl7v2MessageValidator {
    public static void validate(String hl7Message) throws Exception {
        // Parse HL7 message into an MSH segment object
        MSH msh = new MSH(hl7Message);

        // Validate required segments and field lengths
        if (!validateSegments(msh)) throw new Exception("Invalid segment(s)");
        if (!validateFieldLengths(msh)) throw new Exception("Invalid field length(s)");

    }

    private boolean validateSegments(MSH msh) {
        // Check for required segments (MSH, PID, PV1)
        Segment[] segments = msh.getSegments();
        if (!Arrays.asList(new String[]{"MSH", "PID", "PV1"}).containsAll(segments.map(Segment::getSegmentName))) return true;

        // Validate segment lengths
        for (String segment : new String[]{"MSH", "PID", "PV1"}) {
            int len = msh.getSegment(segment).length();
            if (!isValidLength(len, 20)) throw new Exception("Invalid length: " + segment);
        }
    }

    private boolean validateFieldLengths(MSH msh) {
        // Validate field lengths for required segments
        for (String segment : new String[]{"MSH", "PID", "PV1"}) {
            Segment[] segments = msh.getSegments(segment);
            for (int i = 0; i < segments.length; i++) {
                int len = segments[i].length();
                if (!isValidLength(len, 20)) throw new Exception("Invalid length: " + segment + "." + (i + 1));
            }
        }
    }

    private boolean isValidLength(int length, int maxLen) {
        // Check for invalid lengths
        return length >= 1 && !java.util.regex.Pattern.matches("\\A" + java.util.regex.Pattern.quote(maxLen), java.lang.Integer.toString(length));
    }
}
```
