```javascript
// Parse HL7 message and route based on MSH-9 event type

var hl7Message = msg; // Assuming your HL7 message is stored in 'msg'

if (!hl7Message) {
    log.error("No HL7 message received.");
    throw new Error("No HL7 message received.");
}

try {
    var mshSegment = hl7Message.getSegment("MSH");

    if (mshSegment && !mshSegment.getChild(9)) {
        log.error("MSH-9 segment or field 9 not found in the HL7 message.");
        throw new Error("MSH-9 segment or field 9 not found in the HL7 message.");
