    var patientName = pid23.getValue();
    adt25_01.getRep(-1, "PID").addComponent(new hl7.Component("XPN", java.lang.String.format("%s %s", java.lang.Character.toUpperCase(patientName.charAt(0)), java.lang.Character.toUpperCase(patientName.substring(1)))));

  }

  // Return the converted HL7 v2.5.1 message
  return adt25_01;
}

