try {
  // Get the current channel configuration
  var channelConfig = getChannelConfiguration();

  // Create an E4X XML writer to write the output file
  var xmlWriter = java.io.FileWriter(filePath);
  org.dom.DOMOutputTarget xmlOut = new org.dom.DOMOutputTarget(xmlWriter);

  // Set the XML namespace and schema names
  var xmlns = "http://www.mirth.org";
  var xsiSchemaName = "urn:hl7-org";

  // Create an E4X XML document to write the channel configuration to
  var doc = org.w3c.dom.DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();

  // Set the root element name and namespace URI
  var rootNodeName = "ChannelConfig";
  var rootNodeNamespaceURI = xmlns;

  // Add each segment/field group as a separate XML node child of the root node
  for (var i in channelConfig.getSegments()) {
    var segment = channelConfig.getSegments()[i];
    for (var j = 0; j <= segment.getFieldCount(); j++) {
      if (j == 0 || !segment.getName().equals(j)) {
        org.w3c.dom.Element rootNodeChild;
        doc.appendChild(rootNodeChild);
        rootNodeChild.setNamespaceURI(rootNodeNamespaceURI);
        rootNodeChild.setName(rootNodeName + "-child-" + i + "-" + j);

        // Add each field as a separate XML node child of the segment/field group
        for (var k = 0; k < segment.getFieldCount(); k++) {
          org.w3c.dom.Element segmentField;
          rootNodeChild.appendChild(segmentField);
          segmentField.setNamespaceURI(rootNodeNamespaceURI);
          segmentField.setName(segment.getName() + "-child-" + i + "-" + j + "-" + k);

          // Add each field value as a separate XML node child of the segment/field group
          for (var l = 0; l < segment.getField(i).getFieldCount(); l++) {
            org.w3c.dom.Element segmentFieldValue;
            segmentField.appendChild(segmentValue);
            segmentValue.setNamespaceURI(rootNodeNamespaceURI);
            segmentValue.setName(segment.getName() + "-child-" + i + "-" + j + "-" + k + "-" + l);

            // Write the field value to the XML node
            var writer = java.io.FileWriter("/path/to/output/" + fileName.replace(".xml", ".log"));
            org.apache.log4j.Logger.getLogger().format(writer, segmentValue.getName(), segmentValue.getText());
          }
        }
      } else {
        rootNodeChild.setNamespaceURI(rootNodeNamespaceURI);
        rootNodeChild.setName(rootNodeName);

        // Write the root node name to the XML node
        var writer = java.io.FileWriter("/path/to/output/" + fileName.replace(".xml", ".log"));
        org.apache.log4j.Logger.getLogger().format(writer, rootNodeChild.getName(), rootNodeChild.getText());
      }
    }
  }

  // Close the E4X XML writer
  xmlWriter.close();

  // Write the output file to disk
  java.io.File f = new java.io.File(filePath);
  f.createNewFile();
} catch (e) {
  log.error("Error exporting channel configuration: " + e.getMessage());
}
```
