**HL7v2 Segment Parser (Java)**

Here's an example code snippet that demonstrates how to parse an HL7 v2 segment using Java:
```java
import java.util.ArrayList;
import java.util.List;

public class Hl7v2SegmentParser {
    public static void parse(HL7v2Message message) throws Exception {
        // Get the segment(s) from the message
        List<HL7v2Segment> segments = new ArrayList<>();
        for (String segment : message.getSegments()) {
            HL7v2Segment hl7v2Segment = new HL7v2Segment(segment);
            segments.add(hl7v2Segment);
        }

        // Loop through each segment and parse its fields
        for (HL7v2Segment segment : segments) {
            String fieldSeparator = "|"; // default value, can be updated later

            while (!segment.isEmpty()) {
                HL7v2Field field = new HL7v2Field(segment.substring(0, segment.indexOf("|")));
                if (!field.getRepetitions().isEmpty()) { // repeating fields (e.g. PID-5)
                    for (int i = 1; i <= field.getRepetitions(); i++) {
                        parse(field.getValue() + "|" + fieldSeparator);
                    }
                    segment = segment.substring(0, segment.indexOf("|") - 1); // update the segment
                } else if (!field.getComponent(2).isEmpty()) { // repeating fields (e.g. PID-5)
                    for (int i = 1; i <= field.getRepetitions(); i++) {
                        parse(field.getComponent(2) + "|" + fieldSeparator);
                    }
                    segment = segment.substring(0, segment.indexOf("|") - 1); // update the segment
                } else if (!field.getComponent(3).isEmpty()) { // repeating fields (e.g. PID-5)
                    for (int i = 1; i <= field.getRepetitions(); i++) {
                        parse(field.getComponent(3) + "|" + fieldSeparator);
                    }
                    segment = segment.substring(0, segment.indexOf("|") - 1); // update the segment
                } else if (!field.getComponent(4).isEmpty()) { // repeating fields (e.g. PID-5)
                    for (int i = 1; i <= field.getRepetitions(); i++) {
                        parse(field.getComponent(4) + "|" + fieldSeparator);
                    }
                    segment = segment.substring(0, segment.indexOf("|") - 1); // update the segment
                } else if (!field.getComponent(5).isEmpty()) { // repeating fields (e.g. PID-5)
                    for (int i = 1; i <= field.getRepetitions(); i++) {
                        parse(field.getComponent(5) + "|" + fieldSeparator);
                    }
                    segment = segment.substring(0, segment.indexOf("|") - 1); // update the segment
                } else { // simple field
                    parse(segment + "|" + fieldSeparator);
                }

                segment = segment.substring(0, segment.indexOf("|"));
            }
        }
    }

    private static void parse(String value) throws Exception {
        if (value.contains("|")) { // escaped delimiter(s)
            for (String component : value.split("\\|")); // iterate over the components
            System.out.println("Escaped Delimiter: " + component);
        } else if (!value.isEmpty()) { // null field
            System.out.println("Null Field");
        }
    }
}
```
