// Function to log data
function log(message, status) {
    var logger = java.util.logging.Logger.getLogger("MirthConnect");
    var handler = new java.util.logging.StreamHandler({
        write: function(level, msg) {
            if (level == java.lang.System.OUT) {
                logger.severe(msg);
            } else if (level == java.lang.System.err) {
                logger.severe(msg);
            }
        }
    });
    logger.addHandler(handler);

    var formatter = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss:SSS zzz");
    var date = formatter.format(new Date()) + " - " + level.toString() + ": " + msg;

    handler.write(date + " - Status: " + status);
}

// Main transformation logic
