    // Example HL7 v2 message (this should be dynamically fetched from your source connector)
    var hl7Message = new com.mirth.connect.model.datatypes.HL7v2DataType();
    var pidSegment = hl7Message.getPID();

    if (!pidSegment) throw new Error("No PID segment found in the HL7 message");

    // Extract patient details
    var familyName = pidSegment.getField(5, 1);
    var givenNames = pidSegment.getField(5, 2).split('^');
    var mrn = pidMessage.getPID().getField(3, 1);

