        resourceType: "Patient",
        identifier: [
            {
                use: "official",
                type: {
                    coding: [
                        {
                            system: "http://terminology.hl7.org/CodeSystem/v2-0203",
                            code: "MR"
                        }
                    ]
                },
                value: mrn
            }
        ],
        name: [
            {
                use: "official",
                family: givenNames[0],
                given: givenNames.slice(1)
            }
        ]
    };

    // Example HTTP sender channel with the necessary configuration
    var url = "https://your-api-endpoint.com/fhir/Patient";
    var headers = new java.util.HashMap();
    headers.put("Content-Type", "application/json");

    var response = router.routeMessageByChannelId("http-sender-channel-id", JSON.stringify(fhirResource), null, headers);

    // Log source and destination patient records
    log(mrn + " - Source", "Success");
    log(JSON.stringify(fhirResource) + " - Destination", "Success");

} catch (e) {
    // Error handling (log error details)
    var formatter = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss:SSS zzz");
    var date = formatter.format(new Date()) + " - Status: Error"
