To convert a CSV patient roster to a FHIR R4 Bundle of Patient resources using Mirth Connect, you will need to follow these steps:

1. Parse the incoming HL7 message.
2. Extract and process data from the CSV file.
3. Create and populate FHIR Patient resource objects.
4. Assemble an FHIR R4 Bundle.

Below is a complete example in JavaScript for Mirth Connect that accomplishes this task. This script assumes you have access to a database connection, HTTP sender channel, and global map values (if needed).

```javascript
// Function to parse the incoming HL7 message
function parseHL7Message(message) {
    var patientName = message['PID']['PID.5'][0]['PID.5.1'].toString();  // Family name
    var mrn = message['PID']['PID.3'][0]['PID.3.1'].toString();          // MRN

    return { patientName: patientName, mrn: mrn };
}

// Function to fetch data from a database connection
function getPatientFromDatabase(mrn) {
    var dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        'org.postgresql.Driver',
        'jdbc:postgresql://localhost:5432/clinical',
        'mirth_user',
        $('db_password')
    );

    try {
        var result = dbConn.executeCachedQuery(
            "SELECT patient_id, address FROM patients WHERE mrn = ?", [mrn]
        );

        if (result.next()) {
            return { patientId: result.getString('patient_id'), address: result.getString('address') };
        }
    } finally {
        dbConn.close();
    }

    throw new Error("No data found in the database for MRN: " + mrn);
}

// Function to create and populate a FHIR Patient resource
function createFhirPatient(patientName, patientId, address) {
    var fhirPatient = {
        resourceType: 'Patient',
        id: patientId,
        text: new Text().setFormat('http://hl7.org/fhir/StructureDefinition/v2-0168').setValue(new HumanName({ use: 'official', family: [patientName] }).toString()),
        identifier: [
            {
                use: 'official',
                system: 'http://hospital.example.com/mrn',
                value: patientId
            }
        ],
        address: [
            {
                use: 'home',
                line: [address]
            }
        ]
    };

    return fhirPatient;
}

// Function to assemble an FHIR R4 Bundle
function createFhirBundle(fhirPatients) {
    var fhirBundle = {
        resourceType: 'Bundle',
        type: 'collection',
        entry: []
    };

    for (var i in Object.values(fhirPatients)) {
        fhirBundle.entry.push(
            new Object().set('resource', fhirPatients[i])
        );
    }

    return fhirBundle;
}

// Main transformation logic
try {
    var hl7Message = msg;  // Assuming the HL7 message is available as a JavaScript object

    var patientData = parseHL7Message(hl7Message);
    var dbResult = getPatientFromDatabase(patientData.mrn);

    if (!dbResult) throw new Error("Failed to retrieve data from database");

    var fhirPatients = createFhirBundle({ [patientData.patientName]: createFhirPatient(patientData.patientName, dbResult.patientId, dbResult.address)) };

    // Log the FHIR Bundle for debugging
    logger.info(JSON.stringify(fhirPatients));

    // Optionally send an HTTP sender channel to transmit the FHIR Bundle
    var url = 'https://your-fhir-server.com/fhir/Patient';
    var headers = new java.util.HashMap();
    headers.put('Authorization', 'Bearer ' + $('access_token'));
    headers.put('Content-Type', 'application/json');

    router.routeMessageByChannelId('http-sender-channel-id', JSON.stringify(fhirPatients), headers);

} catch (e) {
    logger.error("Error processing HL7 message: " + e.message);
    channelMap.put('error', new Error(e));
}
```

### Explanation:
1. **parseHL7Message**: Extracts patient name and MRN from the incoming HL7 message.
2. **getPatientFromDatabase**: Retrieves data from a database connection based on the MRN.
3. **createFhirPatient**: Creates an FHIR Patient resource object with the provided data.
4. **createFhirBundle**: Assembles an FHIR R4 Bundle of Patient resources.

### Error Handling:
- The script includes basic error handling using `try-catch` blocks to catch and log any exceptions that occur during the processing process.

