To create a patient search API in Mirth Connect using HL7 v2, we need to follow these steps:

1. Define an HTTP Listener connector to receive incoming requests.
2. Parse the incoming message (HL7v2) to extract the necessary information.
3. Perform the database query to retrieve patient details based on the provided parameters.
4. Log the search parameters for debugging and auditing purposes.

Below is a complete Mirth Connect script that fulfills this request:

```javascript
// Define an HTTP Listener connector to receive incoming requests

function handleIncomingMessage(message) {
    try {
        // Parse the incoming HL7v2 message
        var pid = extractSegmentFromMessage("PID", 1, "3");  // Extract Patient ID (MRN)

        if (!pid) throw new Error("Patient ID not found in the HL7v2 message.");

        // Define database connection and query parameters
        var dbConn = DatabaseConnectionFactory.createDatabaseConnection(
            'org.postgresql.Driver',
            'jdbc:postgresql://localhost:5439/clinical',
            $('db_user'), $('db_password')
        );

        try {
            var result = dbConn.executeCachedQuery(
                "SELECT * FROM patients WHERE mrn = ?", [pid]
            );

            if (!result.next()) throw new Error("No patient details found for the given MRN.");

            // Log search parameters
            log.info("Patient Search Parameters - PID: " + pid);

            // Process and store retrieved data (example)
            var patientName = extractSegmentFromMessage("PID", 1, "5");  // Extract Patient Name
            var familyName = extractSegmentFromMessage("PID", 1, "6.2");   // Extract Family Name
            var givenNames = [];
            if ("F" in pid) {
                for (var i = 7; pid["F"].childIndex(i, i + 3) != null; i++) {
                    givenNames.push(pid["F"][i].toString());
                }
            }

            log.info("Patient Name: " + familyName + ", Given Names: " + givenNames.join(", "));

            // Example processing and storing data
            storeAndLog(patientName, familyName, givenNames);

        } finally {
            dbConn.close();
        }
    } catch (e) {
        log.error("Error during database query or logging: " + e.message);
        throw e;
    }
}

function extractSegmentFromMessage(segmentType, level1, level2) {
    var pid = message.get("PID");

    if ("PID" in pid && pid.childIndex(level1, level1 + 3) != null && pid.childIndex(level1, level1 + 4) != null &&
        (pid.childIndex(level1, level1 + 5) == null || !pid.children(level1).childIndex(level1 + 5)).any()) {
        return pid.child(level2).toString();
    }

    throw new Error("Segment and field not found in the HL7v2 message.");
}

function storeAndLog(patientName, familyName, givenNames) {
    // Example processing and storing data
    log.info("Storing Patient Details - Patient Name: " + patientName + ", Family Name: " + familyName,
               ", Given Names: " + givenNames.join(", "));

    // Code to store the retrieved patient details in a database or perform any other action

