// Function to parse and map data from an HL7 v2 message
function createAllergyIntoleranceFromHL7v2(hl7Message) {
    // Initialize the FHIR AllergyIntolerance resource
    var allergyIntolerance = new Object();

    // Map PID-3 (Patient identifier)
    if (hl7Message['PID']['PID.3']) {
        allergyIntolerance.identifier = [{
            system: "http://hospital.example.org", // Example system, you should use a dynamic method to fetch this from your HL7 source
            value: hl7Message['PID']['PID.3'][0]['PID.3.1'].toString()
        }];
    }

    // Map PID-5 (Patient name)
    if (hl7Message['PID']['PID.5']) {
        allergyIntolerance.patient = { reference: "Patient/" + getOrCreatePatientFromHL7v2(hl7Message) };

        var familyName = hl7Message['PID']['PID.5'][0]['PID.5.1'].toString();
        var givenNames = [];
        for (var i in hl7Message['PID']['PID.5']) {
            if (i == 0) { // Assuming PID-5.2 is the primary name
                allergyIntolerance.patient.display = [familyName];
            } else {
                givenNames.push(hl7Message['PID']['PID.5'][i]['PID.5.' + i.toString() + '.1'].toString());
                if (hl7Message['PID']['PID.5'][i]['PID.5.' + i.toString() + '.2']) {
                    allergyIntolerance.patient.display = givenNames.concat([familyName, hl7Message['PID']['PID.5'][i]['PID.5.' + i.toString() + '.1'].toString()]);
                }
            }
        }
    }

    // Map PID-7 (Patient birthDate)
    if (hl7Message['PID']['PID.7']) {
        allergyIntolerance.patient.birthDate = hl7Message['PID']['PID.7'][0]['PID.7.' + 0.toString() + '.1'].toString();
    }

    // Map AL1-3 and PID-3 to create a CodeableConcept for the AllergyIntolerance.code
    if (hl7Message['AL1'] && hl7Message['PID']['PID.3']) {
        var codeSystem = "http://terminology.hl7.org/CodeSystem/allergen-type"; // Example system, you should use a dynamic method to fetch this from your HL7 source
        allergyIntolerance.code = { coding: [{
            system: codeSystem,
            code: "unknown",
            display: "Unknown"
        }] };

        var al1_3 = hl7Message['AL1'][0]['AL1.' + 2.toString() + '.1'].toString();
        if (al1_3) {
            allergyIntolerance.code.coding.push({
                system: codeSystem,
                code: al1_3,
                display: "Unknown"
            });
        }
    }

    // Map AL1-4 and PID-3 to create a CodeableConcept for the AllergyIntolerance.substitutionStatus
    if (hl7Message['AL1'] && hl7Message['PID']['PID.3']) {
        var al1_4 = hl7Message['AL1'][0]['AL1.' + 2.toString() + '.1'].toString();
        allergyIntolerance.substitutionStatus = "unknown";

        if ("R" == al1_4) { // Assuming 'R' is the code for a specific status
            allergyIntolerance.substitutionStatus = "active";
        }
    }

    // Map AL1-5 and PID-3 to create a CodeableConcept for the AllergyIntolerance.code
    if (hl7Message['AL1'] && hl7Message['PID']['PID.3']) {
        var al1_4 = hl7Message['AL1'][0]['AL1.' + 2.toString() + '.1'].toString();
        allergyIntolerance.code.coding.push({
            system: codeSystem,
            code: al1_4,
            display: "Unknown"
        });

        if ("R" == al1_4) { // Assuming 'R' is the code for a specific status
            allergyIntolerance.code.coding[0].code = "allergy";
            allergyIntolerance.code.coding[0].display = "Allergic Hypersensitivity";
        }
    }

    // Map AL1-6 and PID-3 to create an identifier for the AllergyIntolerance.resource
    if (hl7Message['AL1'] && hl7Message['PID']['PID.3']) {
        var al1_5 = hl7Message['AL1'][0]['AL1.' + 2.toString() + '.1'].toString();
        allergyIntolerance.identifier.push({
