    const xml = new XML(fhirJson);
    if (!xml2js.validate(xml, fhirSchema)) {
      console.error(`Invalid FHIR R4 JSON: ${fhirJson}`);
      return;
    }

    console.log(`FHIR R4 JSON is valid!`);
  } catch (error) {
    console.error(error);

  }
}

