To create a FHIR subscription for real-time ADT (Admission/Discharge/Transfer) notifications using the Epic FHIR R4 API, you will need to follow these steps:

1. Register your application at App Orchard.
2. Generate an RSA key pair and upload the public key.
3. Create a signed JWT assertion.
4. Exchange the JWT for an access token.
5. Use the Bearer token to make requests to the FHIR server.

Here is an example of how you might create a subscription using Python and the `requests` library:

```
import jwt
import time
from datetime import datetime, timedelta
import requests

# Step 1: Register your application at App Orchard.
app_orchard_url = "open.epic.com"
client_id = "your_client_id"

# Step 2: Generate an RSA key pair and upload the public key.
private_key = """-----BEGIN OF TEXT-----\n\nMIICMDCCABAGAAKQ7U4D1U5T6O7C8S9L0R1A2B3C4D5E6F7G8H9I0J11K12L13M14N15O16P17Q18R19S20T21U22V23W24X25Y26Z27\n-----END OF TEXT-----"""

# Step 3: Create a signed JWT assertion.
def create_jwt(client_id, private_key):
    payload = {
        "iss": client_id,
        "aud": "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4",
        "exp": int((datetime.now() + timedelta(minutes=1)).timestamp()),
        "iat": int(datetime.now().timestamp())
    }
    return jwt.encode(payload, private_key, algorithm="RS256")

# Step 4: Exchange the JWT for an access token.
def get_access_token(client_id):
    url = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4/oauth2/token"
    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }
    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": create_jwt(client_id, private_key)
    }
    response = requests.post(url, headers=headers, data=data)
    if response.status_code == 200:
        return response.json()["access_token"]
    else:
        raise Exception("Failed to get access token")

# Step 5: Use the Bearer token to make requests to the FHIR server.
def subscribe_for_adt_access_points(access_token):
    url = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4/Subscription"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {access_token}"
    }
    data = {
        "resourceType": "subscription",
        "callbackUrl": "https://your_callback_url.com",
        "resource": "/Patient/$export",
        "status": "active"
    }
    response = requests.post(url, headers=headers, json=data)
    if response.status_code == 201:
        return response.json()["id"]
    else:
        raise Exception("Failed to subscribe for ADT access points")

# Step 6: Poll the status of the subscription.
