// Function to extract and store information from IN1 segments
function extractAndStoreIn1Segments(message) {
    try {
        // Get all IN1 segments from the message
        var in1Segments = message.get("MSH").getReps(0, "PID", true).getReps(0, "IN1");

        if (in1Segments.length == 0) {
            log.warn("No IN1 segments found in the HL7 message.");
        } else {
            // Initialize an array to store insurance plans
            var insurancePlans = [];

            for each (var in1Segment in in1Segments) {
                // Extract and store information from each IN1 segment
                var setID = in1Segment.get(0).toString();
                var planId = in1Segment.get(2, 0, 0).toString();  // Assuming the first insurance plan ID is available
                var companyId = in1Segment.get(3, 0, 0).toString();
                var companyName = in1Segment.get(4, 0, 0).toString();

                // Store information from each IN1 segment
                insurancePlans.push({
                    setID: setID,
                    planId: planId,
                    companyId: companyId,
                    companyName: companyName
                });

            }

        }
    } catch (e) {
        log.error("Error parsing HL7 message for IN1 segments: " + e.message);

    }
}

// Main transformer logic
