    // Extract and store information from IN1 segments
    extractAndStoreIn1Segments(msg);

    // Log the extracted insurance plans
    if (insurancePlans.length > 0) {
        log.info("Extracted Insurance Plans: " + JSON.stringify(insurancePlans));
    }

} catch (e) {
    log.error("Error during HL7 message processing: " + e.message);
}
