   - Select "TCP Listener".

2. **Configure the TCP listener**:
   - Set up the TCP listener with appropriate details (e.g., port, IP address).
   - Ensure that the source connector is configured correctly.

### Transformer Step

1. **Add an additional transformer step**:
   - Click on "Connectors" and then click the "+" icon to create a new connector.
   - Select "Scripted Source Connector".

2. **Configure the scripted source connector**:
   - Add the following JavaScript code to parse the message and route it based on the MSH-9 event type.

```javascript
// Parse the HL7 message
var hl7Message = msg.getSegment("MSH");
if (hl7Message) {
    var eventType = hl7Message.getField(9, 1);

    // Route messages based on the MSH-9 event type
    switch (eventType) {
        case "ADT^A04": // Example for an ADT A04 message
            routeMessage("admission", msg.toString());
            break;
        case "ORU^R01": // Example for an ORU R01 message
        default:
            log.error("Unsupported event type: " + eventType);
    }
} else {
    log.error("MSH segment not found in the HL7 message");
}

// Function to route messages based on different destinations
function routeMessage(destinationName, hl7Message) {
    try {
        // Example of routing a message using another connector (e.g., HTTP Sender)
        var httpSender = new com.mirth.connect.model.connectors.http.HttpDispatcherConnector();
        httpSender.setUrl("http://your-api-url/" + destinationName);
        httpSender.setHeaderMap({
            "Content-Type": "application/hl7"
        });

        // Send the HL7 message to another connector
        var response = httpSender.send(hl7Message, null, 30000); // Wait for up to 30 seconds

        if (response.getStatusCode() == 200) {
            log.info("Message routed successfully: " + destinationName);
        } else {
            log.error("Failed to route message: " + destinationName + ", Status Code: " + response.getStatusCode());
        }
    } catch (e) {
        log.error("Error routing message: " + destinationName, e);
    }
}
```

