import java.util.ArrayList;
import java.util.List;

import org.hl7.v3.MSHSegment;
import org.hl7.v3.Segment;

public class Hl7v2MessageValidator {
  public static void validate(HL7v2Message message) throws Exception {
    // Check MSH header segment
    if (!isValidMSHHeader(message.getMSH())) throw new Exception("Invalid MSH header");

    // Required segments and field lengths
    List<Segment> requiredSegments = Arrays.asList(
      new Segment(Segment.ID_SEGMENT, "PID", 10), // Patient Identification (PID)
      new Segment(Segment.ID_SEGMENT, "PV1", 20) // Visit/Admit Discharge Notification (PV1)

    for (Segment segment : requiredSegments) {
      if (!isValidSegment(message.getSegments().contains(segment))) throw new Exception("Invalid " + segment.getId());
    }

    // Field lengths
    if (!isValidFieldLengths(message.getMSH().getField(3), 10)) throw new Exception("Invalid MSH-3 field length");

    public boolean isValidMSHHeader(MSHSegment msh) {
      // Check MSH header segment ID and value
      return "HL7" == msh.getId() && "V2.0" == msh.getValue();
    }

    public boolean isValidSegment(List<Segment> segments, Segment segment) {
      for (Segment requiredSegment : requiredSegments) {
        if (!segments.contains(requiredSegment)) return false;
      }
      return true;
    }

    public boolean isValidFieldLengths(String field1Value, int field1Length) {
      // Check MSH-3 field length
      if (!java.util.regex.Pattern.matches("^[A-Z0-9]{10}$", field1Value)) throw new Exception("Invalid " + field1Value);
      return true;
    }
  }
}
