    // Initialize variables
    var allergyIntolerance = new Object();

    // Extract relevant fields from the HL7 v2 AL1 segment
    try {
        var al1Segment = hl7Message.get("AL1");

        if (al1Segment == null || !al1Segment.hasChildren()) {
            throw new Error("No AL1 segments found in the message.");
        }

        // Extract and map data from the HL7 v2 AL1 segment
        var al1Child = al1Segment.getChild(0);
        var patientId = al1Child.getChild(3).toString();  // PID-3: Patient ID (MRN, SSN)
        var allergenCodeSystem = "http://terminology.hl7.org/CodeSystem/v2-0206";  // Code system for AllergyIntolerance.code
        var allergenText = al1Child.getChild(4).toString();  // PID-4: Patient ID (Family^Given^Middle)

        if (!patientId) {
            throw new Error("Patient ID not found in the message.");
        }

        if (!allergenCodeSystem || !allergenText) {
            throw new Error("Allergen code system and text not provided.");
        }

        // Create a FHIR AllergyIntolerance resource
        allergyIntolerance.resourceType = "AllergyIntolerance";
        allergyIntolerance.id = generateUniqueId();  // Generate a unique ID for the AllergyIntolerance resource

        var identifier = new Object();
        identifier.use = "official";
        identifier.system = allergenCodeSystem;
        identifier.value = patientId;

        allergyIntolerance.identifier = [identifier];

        var codeableConcept = new Object();
        codeableConcept.coding = [
            {
                system: allergenCodeSystem,
                code: generateUniqueId(),  // Generate a unique ID for the Coding.code
                display: allergenText
            }
        ];

        allergyIntolerance.code = codeableConcept;

        var status = "active";  // Set the status of the AllergyIntolerance resource

        allergyIntolerance.status = status;

    } catch (e) {
        log.error("Error parsing HL7 v2 message: " + e.message);
        throw new Error("Failed to create FHIR AllergyIntolerance resource.");
      }
}

