var fhirClient = Packages.org.milyn.payload.XMLPayload;

/**
 * Parses the incoming HL7 message.
 * @param {XML} hl7Message - The FHIR R4 Patient resource to be sent.
 * @returns {String[]} - An array of patient IDs from the CSV file.
 */
function parseHL7(hl7Message) {
    var pidSegments = hl7Message['PID'];
    if (pidSegments == null || pidSegments.length() == 0)
        throw new Error("No PID segments found in the HL7 message.");

    var patientIds = [];
    for each (var pidSegment in pidSegments) {
        var pid3Field1 = pidSegment[2][1].toString();
        if (pid3Field1 != null && !pid3Field1.isEmpty())
            patientIds.push(pid3Field1);
    }

    return patientIds;
}

/**
 * Parses the CSV file and creates FHIR Patient resource objects.
 * @param {String[]} - An array of patient IDs from the HL7 message.
 * @returns {Array} - An array containing all created FHIR R4 Bundle resources.
 */
function parseCSV(patientIds) {
    var fhirBundle = new Packages.org.milyn.payload.XMLPayload();
    var bundleEntryList = new java.util.ArrayList();

    for each (var patientId in patientIds) {
        var pidSegment = <pid xmlns="http://www.hl7.org/fhir/structdef/patient">
            <id value="{patientId}"/>
            <name>
                <use>official</use>
                <family>{patientId}</family>
            </name>
        </pid>;

        var fhirPatientResource = new Packages.org.milyn.payload.XMLPayload();
        fhirBundle.add(new pidSegment);
        fhirBundle.get(0).add(fhirPatientResource);

        bundleEntryList.add(fhirPatientResource);
    }

    return [fhirBundle];
}

/**
 * Sends the FHIR R4 Bundle to a server.
 * @param {Array} - An array containing all created FHIR R4 Bundle resources.
 */
function sendFHIRBundle(fhirBundle) {
    var url = 'https://your-api-url.com/fhir/Patient';
    var headers = new java.util.HashMap();
    headers.put('Authorization', 'Bearer ' + $('access_token'));
    headers.put('Content-Type', 'application/json');

    try {
        router.routeMessageByChannelId('http-sender-channel-id', fhirBundle[0].toString());
    } catch (e) {
        logger.error("Failed to send FHIR Bundle: " + e.message);
    }
}

/**
 * Main transformation logic.
 */
function transform() {
    var pidSegments = msg['PID'];
    if (!pidSegments || !pidSegments.length()) throw new Error("No PID segments found in the HL7 message.");

    try {
        var patientIds = parseHL7(pidSegments);
        var fhirBundles = parseCSV(patientIds);

        for each (var bundle in fhirBundles) {
            sendFHIRBundle(fhirBundles, bundle);
        }
    } catch (e) {
        logger.error("Error during transformation: " + e.message);
    }

    return msg;
}
```

### Explanation:
1. **parseHL7**: This function parses the incoming HL7 message to extract patient IDs.
2. **parseCSV**: This function simulates parsing a CSV file and creating FHIR Patient resource objects based on the extracted data.
