To parse an HL7 v2 ADT^A01 message and extract all patient demographics from the PID segment using Mirth Connect, you can use JavaScript scripting in a transformer step of your channel. Below is an example code snippet that demonstrates how to achieve this:

```javascript
// Function to parse an HL7 v2 ADT^A01 message and extract all patient demographics from the PID segment

function parsePatientDemographics(hl7Message) {
    try {
        // Create a new E4X XML object for parsing the HL7 message
        var pidSegment = hl7Message['PID'];

        if (pidSegment == null || pidSegment.length() == 0) {
            throw new Error("No PID segments found in the HL7 message.");
        }

        var patientName = pidSegment[1]['XPN'][2][1].toString(); // Patient Name
        var familyName = pidSegment[1]['XPN'][5][1].toString();   // Family Name (Family^Given^Middle)
        var givenNames = [];

        if (pidSegment[1]['XPN'][5] != null) {
            for each (var name in pidSegment[1]['XPN'][5]) {
                givenNames.push(name[2][1].toString());  // Given Names
            }
        }

        var familyNameComponents = familyName.split('^');
        if (familyNameComponents.length > 0) {
            var prefix = familyNameComponents[0];
            var suffix = familyNameComponents[1];

            patientName = prefix + ' ' + givenNames.join(' ') + ' ' + suffix;
        }

        var mrn = pidSegment[3]['XPN'][2][1].toString();          // MRN
        var dob = pidSegment[7].toString();                            // Date of Birth

        return {
            patientName: patientName,
            givenNames: givenNames.join(' '),
            familyNameComponents: familyNameComponents,
            mrn: mrn,
            dob: dob
        };
    } catch (e) {
        log.error("Error parsing HL7 message for PID segment extraction: " + e.message);
        throw new Error("Failed to parse HL7 message.");
    }
}

// Example usage in a transformer step of your channel

