    log.info('Extracted Given Names: ' + pidData.givenNames);
    log.info('Extracted Family Name Components: ' + pidData.familyNameComponents.join(', '));
    log.info('MRN (Patient Identifier List): ' + pidData.mrn);
    log.info('Date of Birth (PID-7): ' + pidData.dob);

    // You can also store the data in globalMap for further processing
    globalMap.put(pidData.patientName, pidData.patientName);
}
