```
const axios = require('axios');

function tryAgain(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      func();
      break;
    } catch (error) {
      if (retries < maxRetries) {
        console.log(`Error calling API: ${error.response.status} ${error.response.statusText}`);
        retries++;
        setTimeout(() => tryAgain(func), 1000 * 2 ** i); // wait for 1 second and retry
      } else {
        throw error;
      }
    }
  }
}

async function patientApiCall(patientId) {
  const apiEndpoint = 'https://example.com/patient-api';
  const headers = {'Content-Type': 'application/json'};
  const data = {patient: patientId};

  tryAgain(() => axios.post(apiEndpoint, JSON.stringify(data), {headers}))
    .then((response) => console.log(`API call successful: ${response.status} ${response.statusText}`))
    .catch((error) => throw error);
}

// Example usage:
