from fastapi import Depends, HTTPException
from sqlalchemy import create_engine, Column, Integer, String
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

# Create an instance of the Base class (the base is defined in the __init__ method)
class Patient(Base):
    __tablename__ = 'patients'

# Map each Python object to a table with the same name. This will allow you to use this class as a parameter for your API endpoints.
engine = create_engine('sqlite:///path/to/db.sqlite3')
Base.metadata.create_table(engine)

class PatientAPI(FastAPI):
    def __init__(self):
        self.db = sessionmaker(autocommit=False, autoflush=False, bind=engine).make_context()

    @api_operation('GET', '/patients/{id}')
    def get_patient(self, id: int) -> dict:
        return {'name': str(self.db.query(Patient).filter_by(id=id).first().name)}

    @api_operation('POST', '/patients')
    def create_patient(self, data: dict) -> Response:
        patient = Patient(**data)
        self.db.add(patient)

    @api_operation('GET', '/patients')
    def get_patients(self) -> list[dict]:
        patients = [str(patient.name) for patient in self.db.query(Patient).all()]
        return {'patients': patients}

    @api_operation('PUT', '/patients/{id}')
    def update_patient(self, id: int, data: dict) -> Response:
        patient = self.db.query(Patient).filter_by(id=id).first()
        patient.name = data['name']
        self.db.commit()

    @api_operation('DELETE', '/patients/{id}')
