  try {
    // Call our drop duplicates function above
    if (!dropDuplicates(message)) {
      // If we reached this point, then we have a duplicate! Drop the message!
      return false;
    }
  } catch (e) {
    // Log an error if something goes wrong
    log.error("Error processing message: " + e.getMessage());
  }

  // Otherwise, let's allow this message to pass through
  return true;
}

// Set our filter function as the filter's logic
filter = filter;
