const axios = require('axios');

function tryAgain(maxRetries, url) {
  let attempts = 0;
  while (attempts < maxRetries) {
    try {
      const response = await axios.get(url);
      // Log the full request and response
      console.log(`Request: ${url}`, response.data);
      return response;
