This function takes as input a FHIR R4 Patient resource and returns an updated version of the same resource with all sensitive information removed. This is particularly important when working with research datasets, where confidentiality and anonymity are crucial.
```python
import java.util.ArrayList;
import java.util.List;

// Anonymize patient data (research datasets)
public static void anonymizePatientData(FhirR4 Patient patient) {
  // Check if the input patient resource has any sensitive information
  if (!patient.getBirthDate().isEmpty() || !patient.getName().get(0).getGiven().isEmpty()) {
    // Create a new, updated patient resource with all sensitive information removed
    FhirR4 anonymizedPatient = new FhirR4(Patient.class);

    // Remove birth date and name (given names) from the anonymized patient resource
    anonymizedPatient.setBirthDate(null);
    List<String> givenNames = new ArrayList<>();
    for (String givenName : patient.getName().get(0).getGiven()) {
      givenNames.add(givenName.replaceFirst("[A-Z]", "*"));
    }
    anonymizedPatient.getName().add(new FhirR4(Patient.Name.class, givenNames));

    // Remove address and telecom information from the anonymized patient resource
    anonymizedPatient.getAddress().clear();
    anonymizedPatient.getTelecom().clear();

    // Return the updated, anonymized patient resource
    return anonymizedPatient;
  } else {
    // If no sensitive information is present in the input patient resource, simply return a copy of the original value
    FhirR4 anonymizedPatient = new FhirR4(Patient.class);
    anonymizedPatient.setBirthDate(patient.getBirthDate());
    anonymizedPatient.getName().add(new FhirR4(Patient.Name.class, patient.getName().get(0).getGiven()));
    return anonymizedPatient;
  }
}
