// Define a retry mechanism with exponential backoff and circuit breaker
public void retryApi(String apiEndpoint, int maxRetries) {
    int retries = 0;
    long backoffMillis = initialBackoffMillis;

    while (retries < maxRetries) {
        // Try to call the EHR API (e.g. using a library like OkHttp)
        Response response = new OkHttpClient().newCall(apiEndpoint).execute();

        if (!response.isSuccessful()) { // check if the API returned an error
            // Exponential backoff and circuit breaker logic!
            retries++;
            backoffMillis *= 2; // grow our initial backoff time (1 second) exponentially

            if (retries <= maxRetries && !isCircuitOpen()) {
                log.info("Circuit broken. Retrying...");
            } else {
                log.error("API failed to respond. Giving up.");
                return;
            }
        } else {
            // API successful! No need for exponential backoff or circuit breaker logic
            break;
        }
    }

    // If we reached the maximum number of retries, give up!
    if (retries == maxRetries) {
        log.error("API failed to respond. Giving up.");
        return;
    }
}
