Here's an example of how you could implement a simple retry decorator in Python using the `time` module:
```
import time
from functools import wraps

def retry(max_retries=5, delay_seconds=1):
    def outer(func):
        @wraps(func)
        def inner(*args, **kwargs):
            attempts = getattr(inner, '_attempts', 0) + 1
            if attempts <= max_retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Error: {e}")
                    time.sleep(delay_seconds * (2 ** attempts))
            else:
                raise

        @wraps(inner)
        def wrapped(*args, **kwargs):
            attempts = getattr(wrapped, '_attempts', 0) + 1
            if attempts <= max_retries:
                try:
                    return inner(*args, **kwargs)
                except Exception as e:
                    print(f"Error: {e}")
                    time.sleep(delay_seconds * (2 ** attempts))
            else:
                raise

        wrapped._attempts = attempts
        return wrapped

    return outer

# Example usage
@retry(max_retries=3, delay_seconds=5)
def my_function():
    # Your code here

my_function()
```
This decorator takes in two arguments: `max_retries` and `delay_seconds`. The first argument is the maximum number of times to retry the function before giving up. The second argument is the delay between retries (in seconds).

The decorator works by calling the original function (`func`) until it gets an error, at which point it waits for a short period of time (`delay_seconds * (2 ** attempts)`), and then tries again.

You can use this decorator to wrap any Python function that you want to retry with exponential backoff.

To create a secure token management system for EHR API OAuth2 flows using Mirth Connect, you will need to follow these steps:

1. Set up an HTTP Listener connector to receive the client assertion.
2. Validate the JWT assertion and extract the necessary information.
3. Exchange the JWT for an access token from the token endpoint.
4. Store or use the access token in your application.

Below is a sample Mirth Connect script that fulfills this request:

```javascript
// HTTP Listener Connector Script

// Step 1: Receive and store the client assertion

function receiveAndStoreClientAssertion(message) {
    var clientId = message.getMetaData("clientId");
    var jwtAssertion = message.getSegment("base64");

    // Store or use the client ID and JWT in your application
    log.info("Received Client ID: " + clientId);
    log.info("Received JWT Assertion: " + jwtAssertion);

    return clientId, jwtAssertion;
}

// Step 2: Validate the JWT assertion and extract necessary information

function validateAndExtractInfoFromJWT(clientId, jwtAssertion) {
    var client = new java.net.URL("https://open.epic.com/interconnect-api/docs/oauth2/token");
    var url = new java.net.URL(client.toString());
    var connection = url.openConnection();
    connection.setRequestMethod("POST");

    // Set the content type and headers
    connection.setDoOutput(true);
    connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");

    // Create a POST request body for JWT assertion validation
    var postData = "grant_type=client_credentials&client_assertion_type=urn:ietf:params:oauth:client-assertion-type:jwt-bearer&client_assertion=" + jwtAssertion;

    // Write the post data to the output stream of the connection
    var outputStream = connection.getOutputStream();
    outputStream.write(postData.getBytes());
    outputStream.flush();

    // Get and read the response code from the server
    var responseCode = connection.getResponseCode();

    if (responseCode == 200) {
        log.info("JWT validation successful");

        // Read the output stream of the connection to get the access token
        var inputStream = connection.getInputStream();
        var reader = new java.io.BufferedReader(new java.io.InputStreamReader(inputStream));
        var jsonResponse = "";
        var line;
        while ((line = reader.readLine()) != null) {
            jsonResponse += line;
        }

        // Extract and store the access token from the response code
        var accessToken = extractAccessTokenFromResponseCode(jsonResponse);

        return clientId, accessToken;
    } else {
        log.error("JWT validation failed. Response Code: " + responseCode);
        throw new Error("Failed to validate JWT assertion");
    }
}

// Step 3: Exchange the JWT for an access token from the token endpoint

function exchangeForAccessToken(clientId, jwtAssertion) {
    var client = new java.net.URL("https://open.epic.com/interconnect-api/docs/oauth2/token");
    var url = new java.net.URL(client.toString());
    var connection = url.openConnection();
    connection.setRequestMethod("POST");

    // Set the content type and headers
    connection.setDoOutput(true);
    connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");

    // Create a POST request body for JWT assertion exchange
    var postData = "grant_type=client_credentials&client_assertion_type=urn:ietf:params:oauth:client-assertion-type:jwt-bearer&client_assertion=" + jwtAssertion;

    // Write the post data to the output stream of the connection
    var outputStream = connection.getOutputStream();
    outputStream.write(postData.getBytes());
    outputStream.flush();

    // Get and read the response code from the server
    var responseCode = connection.getResponseCode();

    if (responseCode == 200) {
        log.info("JWT exchange successful");

        // Read the output stream of the connection to get the access token
        var inputStream = connection.getInputStream();
        var reader = new java.io.BufferedReader(new java.io.InputStreamReader(inputStream));
        var jsonResponse = "";
        var line;
        while ((line = reader.readLine()) != null) {
            jsonResponse += line;
        }

        // Extract and store the access token from the response code
        var accessToken = extractAccessTokenFromResponseCode(jsonResponse);

        return clientId, accessToken;
    } else {
        log.error("JWT exchange failed. Response Code: " + responseCode);
        throw new Error("Failed to exchange JWT for access token");
    }
}

// Step 4: Store or use the access token in your application

function storeOrUseAccessToken(clientId, accessToken) {
    // Store or use the access token in your application
    log.info("Received Access Token: " + accessToken);

    return clientId, accessToken;
}

// Helper function to extract an access token from a response code

function extractAccessTokenFromResponseCode(responseCode) {
    var client = new java.net.URL("https://open.epic.com/interconnect-api/docs/oauth2/token");
    var url = new java.net.URL(client.toString());
    var connection = url.openConnection();
    connection.setRequestMethod("POST");

    // Set the content type and headers
    connection.setDoOutput(true);
    connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");

    // Create a POST request body for JWT assertion exchange
    var postData = "grant_type=client_credentials&token=" + url.getAuthority();

    // Write the post data to the output stream of the connection
    var outputStream = connection.getOutputStream();
    outputStream.write(postData.getBytes());
    outputStream.flush();

    // Get and read the response code from the server
    var responseCode = connection.getResponseCode();

    if (responseCode == 200) {
        log.info("Access Token extracted successfully");

        return postData;
    } else {
        log.error("Failed to extract access token. Response Code: " + responseCode);
        throw new Error("Failed to extract access token");
    }
}

// Main function
function main() {
    try {
        var clientId, jwtAssertion = receiveAndStoreClientAssertion(message);

        if (clientId && jwtAssertion) {
            var clientIdAndAccessToken = exchangeForAccessToken(clientId, jwtAssertion);

            // Step 4: Store or use the access token in your application
            storeOrUseAccessToken(clientIdAndAccessToken[0], clientIdAndAccessToken[1]);
        }
    } catch (e) {
        log.error("Error processing message: " + e.message);
    }
}

main();
```

This script includes functions to receive and store a client assertion, validate the JWT assertion and extract necessary information, exchange the JWT for an access token from the token endpoint, and store or use the access token in your application. It also contains error handling logic.

Please note that this is just a basic example and may need additional customization based on your specific requirements and environment.

