To create a FHIR subscription for real-time ADT (Admission/Discharge/Transfer) notifications using an Epic FHIR R4 API connection, you will need to follow these steps:

1. Register your application at App Orchard.
2. Generate an RSA key pair and upload the public key.
3. Create a signed JWT assertion.
4. Exchange the JWT for an access token.
5. Use the Bearer token to make requests to the FHIR server.

Here is an example of how you might create a subscription using Python and the `requests` library:

```
import requests
import jwt

# Step 1: Register your application at App Orchard
app_orchard_url = "open.epic.com"
client_id = "your_client_id"

# Step 2: Generate an RSA key pair and upload the public key.
private_key_file_path = "/path/to/private_key.pem"
public_key_file_path = "/path/to/public_key.pem"

# Step 3: Create a signed JWT assertion.
def create_jwt(private_key_file_path):
    with open(private_key_file_path, "r") as f:
        private_key = f.read()

    payload = {
        "iss": client_id,
        "aud": app_orchard_url
    }

    jwt_token = jwt.encode(payload, private_key, algorithm="RS256")
    return jwt_token

# Step 4: Exchange the JWT for an access token.
def get_access_token(jwt):
    url = f"{app_orchard_url}/oauth2/token"
    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }
    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": jwt
    }

    response = requests.post(url, headers=headers, data=data)
    if response.status_code == 200:
        return response.json().get("access_token")
    else:
        raise Exception(f"Failed to get access token: {response.text}")

# Step 5: Use the Bearer token to make requests to the FHIR server.
def subscribe_for_adt_access_points(access_token):
    url = f"{app_orchard_url}/fhir/subscription"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {access_token}"
    }
    data = {
        "resourceType": "Subscription",
        "callbackUrl": "https://your_callback_url.com/callback",
        "resource": "Observation",
        "status": "active"
    }

    response = requests.post(url, headers=headers, json=data)
    if response.status_code == 201:
        return response.headers.get("Location")
    else:
        raise Exception(f"Failed to subscribe for ADT access points: {response.text}")

# Step 6: Poll the status of your subscription.
def poll_subscription_status(status_url):
    url = f"{status_url}/status"
    headers = {
        "Authorization": f"Bearer {access_token}"
    }

    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json().get("output")
    else:
        raise Exception(f"Failed to poll subscription status: {response.text}")

# Step 7: Poll the content of your subscription.
def poll_subscription_content(content_url):
    url = f"{content_url}/data"
    headers = {
        "Authorization": f"Bearer {access_token}"
    }

    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.text
    else:
        raise Exception(f"Failed to poll subscription content: {response.text}")

# Example usage
jwt_token = create_jwt(private_key_file_path)
access_token = get_access_token(jwt_token)

status_url = subscribe_for_adt_access_points(access_token)
poll_subscription_status(status_url, status_url)

content_url = poll_subscription_content(status_url, status_url)
print(content_url)
