// Import necessary libraries
var hl7apy = Packages.ca.uhn.hl7v2.model.v25;
var fhirResources = Packages.org.hl7.fhir.r4;

function convertToFHIR(hl7Message) {
    try {
        // Parse the HL7 message
        var pidSegment = hl7Message.get("PID");
        var evnSegment = hl7Message.get("EVN");

        if (!pidSegment || !evnSegment) throw new Error("Invalid HL7 message format");

        // Extract data from PID and EVN segments

        var patientName = pidSegment.getChild(5).toString();
        var ssnNumber = pidSegment.getChild(3).toString();
        var birthDate = pidSegment.getChild(7).toString();

        if (!patientName || !ssnNumber) throw new Error("Invalid HL7 message format");

        // Create a FHIR Patient resource
        var patientResource = fhirResources.Patient.create().setId(generateUUID()).build();
        patientResource.addIdentifier()
            .setSystem("http://hospital.example.org")
            .setValue(ssnNumber)
            .setType(new fhirResources.CodeableConcept().addCoding(
                new fhirResources.Coding("http://terminology.hl7.org/CodeSystem/v2-0203", "SSN", null))
            );

        var name = pidSegment.getChild(5).toString();
        if (name) {
            patientResource.addName()
                .setUse(fhirResources.Name.Use.OFFICIAL)
                .addFamily(name.split(" ")[1])
                .addGiven(name.split(" ")[0]);
        }

        // Create a FHIR Encounter resource
        var encounterResource = fhirResources.Encounter.create().setId(generateUUID()).build();
        encounterResource.addIdentifier()
            .setSystem("http://hospital.example.org")
            .setValue(evnSegment.getChild(3).toString())
            .setType(new fhirResources.CodeableConcept().addCoding(
                new fhirResources.Coding("http://terminology.hl7.org/CodeSystem/v2-0203", "ADT^A01", null))
            );

        // Add the patient to the encounter
        var relatedReference = pidSegment.getChild(5).toString();
        if (relatedReference) {
            encounterResource.addRelatedResource()
                .setReference("Patient/" + relatedReference)
                .setType(new fhirResources.CodeableConcept().addCoding(
                    new fhirResources.Coding("http://terminology.hl7.org/CodeSystem/v2-0203", "ADT^A01", null))
                ));
        }

        // Return the FHIR resources as JSON
        return JSON.stringify(patientResource, null, 4) + "\n" +
               JSON.stringify(encounterResource, null, 4);

    } catch (e) {
        logger.error("Error converting HL7 to FHIR: " + e.message);
        throw new Error(e.message);
    }
}

function generateUUID() {
    return java.util.UUID.randomUUID().toString();
}
