        headers = {
            "Authorization": f"Bearer {access_token}"
        }
        response = requests.get(status_url, headers=headers)
        if response.status_code == 200:
            status = next((line.split("\n")[0] for line in response.text.split("\n") if "status" in line), None)
            print(f"Bulk Export Status: {status}")

            # Check and handle different statuses
            if status == "failed":
                raise Exception("Bulk export failed")
            elif status == "completed":
                return response.headers["Output"]
            else:
