import ca.uhn.hl7v2.HL7Message;
import ca.uhn.hl7v2.datatypes.Segment;

public void parseHL7(HL7Message message) {
    // Check if the message contains any Z-segments at all
    for (Segment segment : message.getSegments()) {
        if (segment.getId().startsWith("Z")) { // ZPD is a custom Z-segment, so we can assume it's this one
