function transform(msg, meta) {
    // Parse the HL7 message to extract the MSH-9 (Event Type) field
    var mshSegment = msg.get("MSH");
    if (!mshSegment || !mshSegment.getChild(8)) {
        log.error("Invalid HL7 message: Missing or missing 'MSH-9' segment.");
        throw new Error("Invalid HL7 message.");
    }

    var eventType = mshSegment.getChild(8).toString();

    // Route the message based on the event type
    switch (eventType) {
