            routeMessage(msg, meta, "admission-discharge-channel-id");
            break;
        case "ORU^R03":  // Example for an Order Status Update
        case "OBR^O05":  // Example for a Laboratory Result Update
            routeMessage(msg, meta, "laboratory-result-channel-id");
            break;
        default:
            log.info("Unhandled event type: " + eventType);
    }

    return msg;  // Return the original message
}

function routeMessage(message, metadata, destinationId) {
    try {
        // Create a new channel map to store routing information
        var channelMap = router.getChannelMap(destinationId);

        if (!channelMap) {
