Here's the code:
```javascript
// Import required libraries
importPackage(hl7);
importPackage(java.text);

// Define the conversion function
function convertAdt(adtMessage) {
  // Create an empty HL7 v2.5.1 message
  var adt25_01 = new hl7.Message();

  // Set the MSH-3 (message type) segment to "ADT"
  adt25_01.addSegment(new hl7.Segment("MSH", "ADT"));

  // Loop through each PID-3 (patient name) repetition and convert it to v2.5.1 format
  for (var i = 0; i < atdMessage.getReps("PID-3"); i++) {
    var pid23 = atdMessage.getRep(i, "PID-3");
    adt25_01.addSegment(new hl7.Segment("PID", "P" + java.lang.Integer.toString(i + 1)));

    // Convert the patient name to v2.5.1 format (e.g., Firstname Lastname)
    var patientName = pid23.getValue();
    adt25_01.getRep(adt25_01.getReps() - 1).addSegment(new hl7.Segment("XPN", "FN" + java.lang.String.valueOf(patientName)));

    // Add a blank separator character (|) to the end of each patient name
    patientName += "|" + java.lang.Character.MIN_VALUE;

    adt25_01.getRep(adt25_01.getReps() - 1).addSegment(new hl7.Segment("XPN", "FN" + java.lang.String.valueOf(patientName)));
  }

  // Return the converted HL7 v2.5.1 message
  return adt25_01;
}

// Example usage:
