        // Load the HL7 message from a file or database, for example
        // ...
    }

    public static List<LabResult> parseOruSegment(String hl7Message) {
        // Parse the ORU^R01 segment and extract lab results with units and reference ranges
        List<LabResult> labResults = new ArrayList<>();
        String[] segments = hl7Message.split("\\|");

        for (String segment : segments) {
            if (segment.startsWith("ORU")) { // Check for an ORU^R01 segment
                int i;
                for ((i = 0; ; i++) i++) {
                    if (!segment.contains("|" + i + "|")) break;

                    String[] fields = segment.split("\\|");

                    for (int j = 0; j < fields.length; j++) {
                        if (fields[j].startsWith("OBX")) { // Check for an OBX segment
                            LabResult labResult = new LabResult();
                            labResult.setUnit(fields[3]); // Extract the unit of measurement
                            labResult.setValue(fields[4]); // Extract the value

                            // Extract and store reference ranges, if available
                            String[] refRanges = fields[5].split("\\^");
                            for (int k = 0; k < refRanges.length; k++) {
                                if (k > 0) { // Skip the first range (no data)
                                    labResult.setRefRange(refRanges[k]);
                                }
                            }

                            labResults.add(labResult);
                        }
                    }
                }
            }
        }

        return labResults;
    }
}

