const fhirSchemaR4 = require('fhir-schema-r4');

function validateFhirJson(fhirJson: string) {
  try {
    const json = new XML(fhirJson);
    if (!json.resourceType || !/^[A-Z0-9_-]+$/.test(json.resourceType)) {
      console.error(`Invalid FHIR resource type: ${json.resourceType}`);
