**HL7v2 Message Validation Code**
```javascript
// Import the hl7js library (https://github.com/hl7-org/hl7-js)
var hl7 = require('hl7');

function validateHl7Message(message) {
  // Check if the MSH header is present and valid
  var mshHeader = message.getSegment('MSH');
  if (!mshHeader || !/^[A-Z0-9]+$/.test(mshHeader.getValue())) return 'Invalid Message';

  // Required segments: PID, PV1, and OBX (for Observation-based messages)
  ['PID', 'PV1'].forEach((segment) => {
    var segmentValue = message.getSegment(segment);
    if (!segmentValue || !/^[A-Z0-9]+$/.test(segmentValue.getValue())) return 'Invalid Message';
  });

  // Check field lengths:
	* MSH: 12 characters (e.g., "MSH|...") for the MSH-1-6 field
	+ PID: 30 characters (e.g., "PID|...") for the PID-3-5 and PID-7 fields

  if (!/^[A-Z0-9]+$/.test(message.getSegment('MSH').getValue().substring(11, 23))) return 'Invalid Message';

  // Check required segments:
	* OBX (for Observation-based messages): present and valid
	+ IN1: absent or present and valid

  if (!/^[A-Z0-9]+$/.test(message.getSegment('OBX').getValue())) return 'Invalid Message';
}

// Example usage:
var hl7Message = new hl7.Message();
hl7Message.addSegment(new hl7.Segment('MSH', '...'));
hl7Message.addSegment(new hl7.Segment('PID', '...'));

validateHl7Message(hl7Message);
