4. Exchange the JWT for an access token from the token endpoint.

Below is a Python script that demonstrates how to achieve this using the `requests` library:

```python
import jwt
import time
from datetime import datetime, timedelta
import requests

# Constants
APP_ORCHARD_URL = "https://open.epic.com"
TOKEN_ENDPOINT = f"{APP_ORCHARD_URL}/oauth2/token"

# RSA key pair and public key upload details are not provided in this example.

def create_jwt_assertion():
    # Create a JWT assertion with the required claims
    payload = {
        "iss": "<your-client-id>",
        "sub": "<your-client-id>",
        "aud": TOKEN_ENDPOINT,
        "exp": int((datetime.utcnow() + timedelta(minutes=5)).timestamp()),
        "iat": int(datetime.utcnow().timestamp())
    }

    # Sign the JWT assertion using your RSA key pair
    signed_jwt = sign_jwt(payload)  # This function should be implemented based on your RSA signing logic

    return signed_jwt

def exchange_token_for_access_token(signed_jwt):
    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }

    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": signed_jwt
    }

    try:
        response = requests.post(TOKEN_ENDPOINT, headers=headers, data=data)

        if response.status_code == 200:
            return response.json().get("access_token")
        else:
            raise Exception(f"Failed to exchange token: {response.text}")
    except requests.RequestException as e:
        print(f"Request exception: {e}")
        exit(1)

def get_access_token():
    signed_jwt = create_jwt_assertion()

    try:
        access_token = exchange_token_for_access_token(signed_jwt)

        if not access_token:
            raise Exception("Failed to obtain an access token")

        return access_token
    except Exception as e:
        print(f"Error getting access token: {e}")
        exit(1)

def main():
    try:
        # Get the access token
        access_token = get_access_token()

        # Example of using the Bearer token for a FHIR API call
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get("https://your-fhir-server.com/your-endpoint", headers=headers)

        if response.status_code == 200:
            print(f"FHIR server response: {response.text}")
        else:
            raise Exception(f"Failed to make FHIR API call: {response.text}")

    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()
```

### Explanation

1. **create_jwt_assertion**: This function creates a JWT assertion with the required claims and signs it using your RSA key pair.

2. **exchange_token_for_access_token**: This function exchanges the signed JWT for an access token from the token endpoint.

3. **get_access_token**: This function orchestrates the process of creating, signing, and exchanging the JWT for an access token.

4. **main**: This is a simple example of making a GET request to a FHIR API using the Bearer token obtained in `get_access_token`.

