// Function to parse the FHIR R4 CarePlan resource
function parseFhirCarePlan(fhirMessage) {
    var carePlan = fhirMessage.get("resource");

    // Extract relevant data from the FHIR R4 CarePlan
    var patientId = carePlan.get("subject").get("reference").split("/")[1];
    var carePlanCode = carePlan.get("code").toHuman();
    var status = carePlan.get("status");

    return {
        patientId: patientId,
        carePlanCode: carePlanCode,
        status: status
    };
