// Function to construct and send an HL7 v2 message
function sendHl7v2Message(hl7Message) {
    try {
        // Construct the HL7 v2 message
        var hl7Segment = "MSH|^~\\&|Mirth Connect|||20230401123456||ORU^R01^O01|1234567890|P|2.5\r";
        hl7Segment += "EVN|A04|" + new Date() + "|CNE|1.3.6.1.4.1.1259.1.10.11.12.1||" + hl7Message.patientId + "^&amp;MRN&amp;" + hl7Message.carePlanCode + "&amp;OBS&amp;" + new Date() + "\r";

        // Send the HL7 v2 message
        var response = sendRequest("POST", "https://your-hl7-api-url.com/sendHl7v2", hl7Segment, {"Content-Type": "text/plain"});

        if (response.status == 200) {
            log.info("HL7 v2 message sent successfully: " + response.body);
        } else {
            throw new Error("Failed to send HL7 v2 message: " + response.status + " - " + response.body);
        }
    } catch (e) {
        log.error("Error sending HL7 v2 message: " + e.message);

        // Log error details
        var errorMessage = "Error sending HL7 v2 message\n" +
                             "Status Code: " + e.response.status + "\n" +
                             "Response Body: " + e.response.body

        return errorMessage;
    }
}

// Main function to handle the conversion and sending of an FHIR R4 CarePlan to an HL7 v2 message
function convertAndSend(fhirMessage) {
    try {
        // Parse the FHIR R4 CarePlan resource
        var hl7Message = parseFhirCarePlan(fhirMessage);

        // Construct and send an HL7 v2 message
        log.info("Sending HL7 v2 Message: " + JSON.stringify(hl7Message));

        return sendHl7v2Message(hl7Message);
    } catch (e) {
        log.error("Error converting and sending FHIR R4 CarePlan to HL7 v2 message: " + e.message)

