Here's an example of how you could implement a simple retry wrapper in JavaScript using the `axios` library:
```
const axios = require('axios');

function tryAgain(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      func();
      break;
    } catch (error) {
      if (!/retrying/.test(error.message)) {
        console.log(`Error calling API: ${error}`);
        if (retries < maxRetries-1) {
          setTimeout(() => tryAgain(func, retries+1), 1000 * i);
        }
        return;
      }
    }
  }
}

async function patientApiCall(patientId, apiEndpoint) {
  const axiosConfig = axios.defaults;
  axios.setInterceptors(axios.interceptors);

  async function callPatientApi() {
    try {
      await axios.get(`${apiEndpoint}/${patientId}`, axiosConfig);
      console.log(`API call successful: ${patientId}`);
    } catch (error) {
      if (!/retrying/.test(error.message)) {
        console.error(`Error calling API: ${error}`);
        tryAgain(() => callPatientApi());
      }
    }
  }

  await callPatientApi();
}

// Example usage:
const patientId = '12345';
const apiEndpoint = 'https://example.com/patient-api';

patientApiCall(patientId, apiEndpoint);
```
