**Segment Parser Code**
```python
import re

def parse_hl7_segment(segment):
    """
    Parses an HL7 v2 segment into its constituent parts (fields).

    Args:
        * segment: The raw HL7 v2 segment as a string.
    Returns:
        * A dictionary containing the parsed field values, with keys representing the field names.
    """

    def _parse_field(field):
        """
        Parses an individual HL7 v2 field into its constituent parts (components).

        Args:
            * field: The raw HL7 v2 field as a string.
        Returns:
            * A list of strings containing the parsed component values, with no leading or trailing whitespace characters.
        """

        def _strip_whitespace(str_val):
            return re.sub(r'\s+', '', str_val)

        if not field.startswith('|'):
            # Field does not start with the pipe character (|), so it's simply a single value
            return [field]
        elif field.endswith('|') and '|' in field[1:-1]:
            # Field ends with a pipe character, and contains an embedded repetition sequence
            field_values = []
            for i, _component_value_ in enumerate(re.findall(r'(\S+)(?:|.+?)+', field[1:-1])):
                if i == 0:  # First component (no leading whitespace characters)
                    field_values.append(_strip_whitespace(_component_value_))
                else:
                    field_values.extend([_strip_whitespace(_component_value_.replace('|', ''))])
            return [f'{i+1}:{field_values[i].replace("", "")}{"|".join(field_values[i].split(" "))+"|"}' for i in range(len(field_values))]
        elif '|' not in field[1:-1]:
            # Field does not contain an embedded repetition sequence
            return [re.sub(r'\S+', '\\&\\', _component_value_).strip() for _component_value_ in re.findall(r'(\S+)(?:|.+?)+', field)]

    parsed_fields = {}
    for i, _segment_component_ in enumerate(segment.split('|')):
        if i == 0:  # First segment component (no leading whitespace characters)
            parsed_fields[_segment_component_] = _parse_field(_segment_component_.replace('', '|'))
        elif _segment_component_.startswith('|'):
            # Segment component ends with a pipe character, and contains an embedded repetition sequence
            for _component_value_ in re.findall(r'(\S+)(?:|.+?)+', _segment_component_[1:-1]):
                parsed_fields[_segment_component_] = [f'{i}:{parsed_fields[_segment_component_].replace("", "")}{"|".join([_strip_whitespace(_component_value_.replace('|', ''))])+"|"}' for i in range(len(parsed_fields[_segment_component_]))]
    return dict(**[k: v[0] if not v else [f'{i}:{v[0].replace("", "")}{"|".join(v[:1].split(" "))+"|"}{v[1]}{"|" + v[2][0] if len(v) > 2 else ""}' for i, _component_value_ in enumerate(re.findall(r'(\S+)(?:|.+?)+', v))]) for k, v in parsed_fields.items()])
