1. **Register your application** at App Orchard.
2. **Generate RSA key pair**, upload the public key, and create a signed JWT assertion.
3. Exchange the JWT for an access token from the token endpoint.

Below is a Python script using `requests` library to achieve this. This example includes error handling and comments:

```python
import requests
from datetime import datetime

# Constants
BASE_URL = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4"
TOKEN_ENDPOINT = f"{BASE_URL}/oauth2/token"

def generate_jwt_assertion():
    # Generate RSA key pair, upload the public key, and create a signed JWT assertion.
    # This is an example of how you might do this using PyJWT (Python's JSON Web Token library)

    import jwt

    payload = {
        "iss": "<your-client-id>",
        "aud": TOKEN_ENDPOINT,
        "exp": int((datetime.now() + timedelta(minutes=1)).timestamp()),
        "iat": int(datetime.now().timestamp())
    }

    # Sign the JWT with your RSA private key
    signed_jwt = jwt.encode(payload, "<your-rsa-private-key>", algorithm="RS256")

    return signed_jwt

def get_access_token(signed_jwt):
    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }
    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": signed_jwt
    }

    try:
        response = requests.post(TOKEN_ENDPOINT, headers=headers, data=data)

        if response.status_code == 200:
            return response.json().get("access_token")
        else:
            print(f"Failed to get access token: {response.text}")
            raise Exception("Failed to get access token")

    except requests.RequestException as e:
        print(f"Request exception: {e}")
        raise

def make_fhir_request(access_token, endpoint, method="GET", headers=None):
    if not headers:
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

    try:
        response = requests.request(method, endpoint, headers=headers)

        if response.status_code == 200:
            return response.json()
        elif response.status_code == 401 and "Unauthorized" in response.text.lower():
            print("Access token has expired. Please re-authenticate and retry.")
            raise Exception("Access token has expired. Please re-authenticate and retry.")
        else:
            print(f"Request failed: {response.text}")
            raise Exception(f"Request failed: {response.text}")

    except requests.RequestException as e:
        print(f"Request exception: {e}")
        raise

# Example usage
if __name__ == "__main__":
    signed_jwt = generate_jwt_assertion()

    try to get the access token and make a FHIR request
    endpoint = "<your-fhir-endpoint>"
    method = "GET"
    headers = {
        "Accept": "<your-accept-type>"
    }

    try:
        fhir_data = make_fhir_request(access_token, endpoint, method=method, headers=headers)

        if fhir_data:
            print("FHIR Data Received:")
            print(fhir_data)

    except Exception as e:
        print(e)

```

### Explanation:

1. **generate_jwt_assertion**: This function generates a signed JWT assertion using your RSA private key.

2. **get_access_token**: This function exchanges the JWT for an access token from the token endpoint.

3. **make_fhir_request**: This function makes a GET request to a FHIR resource and handles authentication and error handling.
   - It checks if the response status code is 401 (Unauthorized) and logs that the access token has expired.
   - If any other HTTP status codes fail, it prints an error message.

### Error Handling:
- **Request Exceptions**: The script includes basic exception handling for network-related issues during HTTP requests.
- **Authorization Errors**: It checks for a specific HTTP status code 401 (Unauthorized) to handle cases where the access token has expired.

