        log.info("HL7 v2 Message Sent: " + hl7Segment);
    } catch (e) {
        log.error("Failed to send HL7 v2 message: " + e.message);
    }
}

// Main function to handle the conversion and sending of an FHIR R4 CarePlan
function convertAndSendFhirCarePlan(fhirMessage, hl7v2Message) {
    try {
        // Parse the FHIR R4 CarePlan resource
        var carePlanData = parseFhirCarePlan(fhirMessage);

        // Construct and send the HL7 v2 message
        sendHl7v2Message(carePlanData);

        log.info("FHIR R4 CarePlan Converted and Sent: " + fhirMessage.toString() + ", HL7 v2 Message Sent: " + hl7v2Message);
