// Get the current message
var msg = connectorMap.get('message');

// Check if the message is an ADT (Admission/Discharge Transfer) message
if (msg.getMessageType() == 'ADT') {
  // Loop through each segment in the message
  for each (seg in msg.getSegments()) {
    // Get the current segment name and field number
    var segName = seg.getName();
    var fieldName = seg.getFieldNumber();

    // Check if this is an MSH-9 or EVN-2 segment, which needs to be upgraded
    if ((segName == 'MSH' && fieldName == 9) || (segName == 'EVN' && fieldName == 2)) {
      // Get the current field value and repeat it 5 times
      var fieldValue = seg.getField(fieldName);
      for each (i in [0, 1, 2, 3, 4]) {
        // Add a new segment to the message with the same name as this one, but with an incremented field number
        msg.addSegment(segName + '.' + fieldName.toString() + i.toString());
        // Set the value of that new segment to the repeat of the current field value
        msg.getSegments()[msg.getSegments().length() - 1].setField(fieldName, fieldValue);
      }
    }
  }

  // Send a response back to the sender with an OK status code and no error message
  connectorMap.put('response', 'OK');
} else {
  // If this is not an ADT message, then just send a success response back to the sender
  connectorMap.put('response', 'Success');
}
