Here's an example of how you could implement a simple retry wrapper in JavaScript using the `axios` library:
```
const axios = require('axios');

function tryAgain(func, maxRetries=0) {
  if (maxRetries > 0) {
    setTimeout(() => tryAgain(func), 1000); // wait for 1 second before trying again
    return;
  }

  func().then((response) => console.log(`Request successful: ${response.data}`));
}

function patientApiCall(patientId, apiEndpoint, maxRetries=0) {
  axios.get(`${apiEndpoint}/${patientId}`)
    .then((response) => tryAgain(() => response.data))
    .catch((error) => {
      if (maxRetries > 0) {
        console.log(`Error calling API: ${error.response.status} - retrying...`);
        setTimeout(() => patientApiCall(patientId, apiEndpoint, maxRetries + 1)), 1000); // wait for 1 second before trying again
      } else {
        console.error(`Error calling API: ${error.response.status}`);
      }
    });
}
```
This code defines two functions:

* `tryAgain` takes a function as an argument and logs the full request and response. If the request is successful, it returns.
