// Define regular expressions for required segments and field lengths
var PID_REGEX = /PID\|.*?~&/; // Patient Identification Segment (PID)
var PV1_REGEX = /PV1\|.*?~&/; // Visit/Admit Discharge Notification Segment (PV1)

// Define a function to validate the HL7 v2 message
function validateHL7v2Message(message) {
