      log.error("Required segment(s) missing: " + message);
      return false;
    }

    // Check field lengths for each segment
    var pidSegment = message.substring(message.indexOf(PID_REGEX), message.indexOf(PID_REGEX) + 10));
    if (pidSegment.length() < 20) throw new Error("Invalid PID Segment Length");

    var pv1Segment = message.substring(message.indexOf(PV1_REGEX), message.indexOf(PV1_REGEX) + 10));
    if (pv1Segment.length() < 30) throw new Error("Invalid PV1 Segment Length");

    // If we reach this point, the HL7 v2 message is valid!
    log.info("HL7 v2 Message Valid: " + message);
    return true;
  } catch (e) {
    log.error("Error validating HL7 v2 message: " + e.getMessage());
    return false;
  }
}

