```javascript
// Import required libraries
const hl7 = require('hl7-js');
const { HL7Message } = require('@mirth/connect-client');

// Define a function to validate an HL7 v2 message
function validateHl7Message(message) {
  // Check MSH header (1.0)
  if (!message.getMSH().getHeader().getValue()) throw new Error('Invalid MSH header');

  // Required segments and field lengths:
  const requiredSegments = ['PID', 'PV1'];
  const segmentLengths = {};

  for (const segment in message.getSegments()) {
    if (requiredSegments.includes(segment.getName())) {
      // Check segment length
      if (!segment.getLength() || !/^[0-9]+$/.test(String(segment.getLength()))) throw new Error(`Invalid ${segment} segment length: ${segment.getLength()}`);

      // Store the segment length for later use
      segmentLengths[segment.getName()] = segment.getLength();
    }
  }

  // Check message type (MSH-3)
  if (!['ORM'].includes(message.getMSH().getHeader().getValue())) throw new Error('Invalid Message Type: ' + message.getMSH().getHeader().getValue());

  // No errors found! The message is valid!
}
```
