```javascript
const oauthClient = require('oauth-2.0-client-id')(clientId);

app.post('/token', (req, res) => {
  const clientId = req.body.client_id;
  const clientSecret = req.body.client_secret;

  if (!clientId || !clientSecret) {
    // Error: invalid client ID or secret
    return res.status(401).send({ error: 'Invalid credentials' });
  }

  const accessToken = oauthClient.getAccessToken(clientId, clientSecret);

  if (!accessToken) {
    // Error: unable to issue access token
    return res.status(500).send({ error: 'Unable to issue access token' });
  }

  req.body.accessToken = accessToken;
  res.json();
});

app.post('/verify-token', (req, res) => {
  const accessToken = req.body.accessToken;

  if (!accessToken) {
    // Error: invalid or missing access token
    return res.status(401).send({ error: 'Invalid or missing access token' });
  }

  oauthClient.verifyAccessToken(accessToken);

  if (!oauthClient.isVerified()) {
    // Error: unable to verify access token
    return res.status(500).send({ error: 'Unable to verify access token' });
  }
  req.body.accessToken = accessToken;
  res.json();
});
