**Filter Code:**
```javascript
// Set the filter name and description
var name = "Drop Duplicates";
var desc = "Remove duplicates from incoming messages";

// Define a function to drop duplicate messages based on MSH-10 control ID
function dropDuplicates(message) {
  // Get the message's MSH-10 segment (Message Control ID)
  var msh10 = message.getSegment("MSH").getComponent(10).getValue();

  // Check if this is not a new message (i.e., no duplicates so far)
  if (!mirthUtil.isNewMessage(message)) {
    // If we've reached this point, it means we have a duplicate!
    log.info("Dropping duplicate: " + msh10);
    return; // Drop the message
  }
}

// Define our filter function
function filter(message) {
  try {
    // Apply the drop duplicates logic above
    dropDuplicates(message);

    // If we reached this point, it means we didn't find any duplicates. Let's let the message pass through!
    log.info("Message " + msh10 + " is not a duplicate; allowing it to pass");
  } catch (e) {
    // Log an error if our filter function fails
    log.error("Error filtering message: " + e.getMessage());
  }
}

// Register our filter function with Mirth
mirthUtil.registerFilter(name, desc, filter);
```
