**Segment Parser Code**
```python
import re

def parse_hl7_segment(segment):
    """
    Parse an HL7 v2 segment (MSH, PID, PV1, etc.) into its constituent parts (fields).

    Args:
        * segment: The raw HL7 v2 segment string (e.g. "MSH|^~\&|...").

    Returns:
        A dictionary containing the parsed field values and names.
    """

    def _escape_delimiter(match):
        return match.group(1).replace("|", "^")

    def _strip_null_values(value):
        if value.startswith("^") and value.endswith("~"):
            return value[1:-1]
        else:
            return value

    hl7_segment_regex = re.compile(r"([^\|]+)(?:\^~&)?")
    segment_parts = [part.strip() for part in hl7_segment_regex.findall(segment)]

    parsed_fields = {}

    for i, field in enumerate(segment_parts):
        if i == 0:  # MSH-1 (Message Header)
            parsed_fields["Message Header"] = _escape_delimiter(field)
        elif i > 2 and not re.match(r"^[0-9]+$|~", field):  # PV1-3 (Admit Date/Time) or similar
            parsed_fields[f"{i} {field.replace('^', '^~&')}.1"] = _strip_null_values(_escape_delimiter(field))

    return {"MSH": parsed_fields.get("Message Header")}
```
