// Define an HTTP Listener connector to receive incoming requests

function handleIncomingMessage(message) {
    try {
        // Parse the incoming HL7v2 message
        var pidSegment = getFirstChildOfMessage(message, "PID");

        if (pidSegment == null) {
            log.error("No PID segment found in the HL7v2 message.");
            throw new Error("Invalid HL7v2 format.");
        }

        // Extract patient details from the PID segment
        var pid3Field = getFirstChildOfChildren(pidSegment, "PID.3");

        if (pid3Field == null) {
            log.error("No Patient ID found in the PID-3 field of the HL7v2 message.");
            throw new Error("Invalid HL7v2 format.");
        }

        var pid5Field = getFirstChildOfChildren(pidSegment, "PID.5");

        if (pid5Field == null) {
            log.error("No Patient Name found in the PID-5 field of the HL7v2 message.");
            throw new Error("Invalid HL7v2 format.");
        }

        var pid6Field = getFirstChildOfChildren(pidSegment, "PID.6");

        if (pid6Field == null) {
            log.error("No Patient ID found in the PID-6 field of the HL7v2 message.");
            throw new Error("Invalid HL7v2 format.");
        }

        var pid7Field = getFirstChildOfChildren(pidSegment, "PID.7");

        if (pid7Field == null) {
            log.error("No Patient DOB found in the PID-7 field of the HL7v2 message.");
            throw new Error("Invalid HL7v2 format.");
        }

        var pid8Field = getFirstChildOfChildren(pidSegment, "PID.8");

        if (pid8Field == null) {
            log.error("No Patient Gender found in the PID-8 field of the HL7v2 message.");
            throw new Error("Invalid HL7v2 format.");
        }

        var pid11Field = getFirstChildOfChildren(pidSegment, "PID.11");

        if (pid11Field == null) {
            log.error("No Patient Address found in the PID-11 field of the HL7v2 message.");
            throw new Error("Invalid HL7v2 format.");
        }

        var pid13Field = getFirstChildOfChildren(pidSegment, "PID.13");

        if (pid13Field == null) {
            log.error("No Patient Account Number found in the PID-13 field of the HL7v2 message.");
            throw new Error("Invalid HL7v2 format.");
        }

        var pid18Field = getFirstChildOfChildren(pidSegment, "PID.18");

        if (pid18Field == null) {
            log.error("No Patient Account Number found in the PID-18 field of the HL7v2 message.");
            throw new Error("Invalid HL7v2 format.");
        }

        var pid3Value = pid3Field.getChild(1).toString();
        var pid5Name = pid5Field.getChild(0, 1) + " " + pid5Field.getChild(0, 0);
        var pid6AccountNumber = pid6Field.getChild(1).toString();

        // Perform the database query to retrieve patient details
        var dbConn = DatabaseConnectionFactory.createDatabaseConnection(
            'org.postgresql.Driver',
            'jdbc:postgresql://localhost:5432/clinical',
            $('db_user'), $('db_password')
        );

        try {
            var result = dbConn.executeCachedQuery(
                "SELECT * FROM patients WHERE id = ?", [pid3Value, pid6AccountNumber]
            );

            if (!result.next()) {
                log.error("No patient details found for ID: " + pid3Value);
                throw new Error("Patient not found.");
            }

            var patientDetails = result.getString('patient_details');

            // Log the search parameters
            log.info("Search Parameters - Patient ID: " + pid3Value, 
                      "  , Patient Name: " + pid5Name, 
                      ", Account Number: " + pid6AccountNumber);

            return new Response(200, null, patientDetails);
        } finally {
            dbConn.close();
        }
    } catch (e) {
        log.error("Error parsing HL7v2 message or performing database query: " + e.message);

        var errorResponse = new Response(500, "Internal Server Error", 
                                            {"Content-Type": "application/json"}, 
                                            JSON.stringify({"error": e.message}) );

        return errorResponse;
    }
}
```

