```javascript
// Function to log errors without exposing PHI
function logError(errorMessage, patientName) {
    var formatter = new java.text.SimpleDateFormat('yyyy-MM-dd HH:mm:ss');
    var date = formatter.format(new Date());

    // Log error in a secure way (e.g., using global map or channel map)
    globalMap.put(patientName + '_' + date + '_log_error', errorMessage);
}

// Function to handle HTTP request and log errors
function sendFhirRequest(url, headers, body) {
    try {
        var response = router.routeMessageByChannelId('http-sender-channel-id', msg.toString());

