    return jwt_assertion

def get_access_token(private_key):
    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }

    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:oid:oauth2:client-assertion-type:jwt-bearer",
        "client_assertion": generate_jwt_assertion(private_key)
