As a healthcare integration expert specializing in mirth, I'll provide you with a complete answer to create an HL7 v2 ORU^R01 parser that extracts lab results with units and reference ranges.

**Parser Code**
```java
import java.util.ArrayList;
import java.util.List;

import ca.uhn.hl7v2.HL7Message;
import ca.uhn.hl7v2.datatypes.CWE;
import ca.uhn.hl7v2.datatypes.NM;
import ca.uhn.hl7v2.datatypes.ST;
import ca.uhn.hl7v2.parser.ParserException;
import ca.uhn.hl7v2.util.Util;

public class LabResultExtractor {
    public static void extractLabResults(HL7Message message) throws ParserException {
        // Check if the message is an ORU^R01 (Unsolicited Observation Report)
        if (!message.getMSH().getMsgType().equals("ORU^R01")) return;

        // Get all OBX segments in the message
        List<ca.uhn.hl7v2.datatypes.OBX> obxSegments = new ArrayList<>();
        for (int i = 1; i <= message.getOBXReps(); i++) {
            obxSegments.add(message.getOBX(i));
        }

        // Loop through each OBX segment and extract lab results
        for (ca.uhn.hl7v2.datatypes.OBX obxSegment : obxSegments) {
            String observationId = getObservationId(obxSegment);
            NM value = getValue(obxSegment);
            ST units = getUnits(obxSegment);

            // Extract reference range(s)
            List<ST> refRanges = new ArrayList<>();
            for (int i = 1; i <= obxSegment.getRNGRs().size(); i++) {
                refRanges.add(obxSegment.getRNGRs().get(i).getValue());
            }

            System.out.println("Observation ID: " + observationId);
            System.out.println("Value: " + value.getValue() + " " + units.getText());
            System.out.println("Reference Range(s): ");

            for (ST refRange : refRanges) {
                System.out.print(refRange.getValue() + " - ");
            }
        }
    }

    private static String getObservationId(ca.uhn.hl7v2.datatypes.OBX obxSegment) throws ParserException {
        // Extract observation ID from OBX-3
        CWE cwe = (CWE) obxSegment.getOBX3().getValue();
        return cwe.getCodeSystem().getNamespaceID() + "." + cwe.getCode();

    }

    private static NM getValue(ca.uhn.hl7v2.datatypes.OBX obxSegment) throws ParserException {
        // Extract value from OBX-5
        NM nm = (NM) obxSegment.getOBX5().getValue();
        return nm;
    }

    private static ST getUnits(ca.uhn.hl7v2.datatypes.OBX obxSegment) throws ParserException {
        // Extract units of measurement from OBX-6
        CWE cwe = (CWE) obxSegment.getOBX6().getValue();
        return cwe.getCodeSystem().getNamespaceID() + "." + cwe.getCode();

    }
}
