        List<LabResult> labResults = parseOruSegment(hl7Message);

        // Print or store the extracted lab results, for example
        System.out.println("Extracted Lab Results:");
        for (LabResult result : labResults) {
            System.out.println(result.getTestName() + ": " + result.getValue() + " (" + result.getUnits() + ")");
        }
    }

    public static String loadHl7Message(String filePath) {
        // Load the HL7 message from a file or database, for example
        // ...
    }

    public static List<LabResult> parseOruSegment(String hl7Message) {
        // Parse the ORU^R01 segment and extract lab results with units and reference ranges
        List<LabResult> labResults = new ArrayList<>();
        String[] segments = hl7Message.split("\\|");

        for (String segment : segments) {
            if (segment.startsWith("ORU")) { // Check for an ORU^R01 segment
                int startIdx = segment.indexOf("|") + 1;
                int endIdx = segment.lastIndexOf("|");

                for (int i = startIdx; i <= endIdx; i++) {
                    String[] fields = segment.substring(i, i + 5).split("\\|");
                    if (fields[0].equals("OBX")) { // Check for an OBX segment
                        LabResult labResult = new LabResult();
                        labResult.setTestId(fields[2]);
                        labResult.setValue(segment.substring(startIdx + 1, endIdx));
                        labResult.setUnits(segment.substring(startIdx + 5, endIdx));

                        labResults.add(labResult);
                    }
                }
            }
        }

        return labResults;
    }
}

