            throw new Error("Invalid HL7v2 format");
        }

        var mrn = getFieldValue(pidSegment, 3, 1); // Assuming MRN is always present in a patient ADT^A01 message

        if (!mrn) {
            log.error("No MRN found in the PID segment of the HL7v2 message.");
            throw new Error("Invalid HL7v2 format");
        }

        // Perform the database query to retrieve patient details
