        }
    } catch (e) {
        log.error("Error processing HL7v2 message: " + e.message);
        throw e;
    }
}

// Helper function to extract the MRN from a PID segment
function getFieldValue(segment, fieldNumber, subFieldNumber) {
    var fields = segment.split("\^");

    for (var i = 1; i <= fieldNumber; i++) {
        if (i == fieldNumber && !subFieldNumber || !fields[i].split("~").length > subFieldNumber - 1) {
            return null;
        }

        if (i < fieldNumber && !fields[i].split("~").includes(subFieldNumber)) {
            throw new Error("Invalid HL7v2 format");
        }
    }

    for each (var f in fields) {
        var s = f.split("\^~\\&");

        for each (var sf in s) {
            if (!sf.includes("|")) {
                return sf;
            }
        }
    }

    return null;
}
```

