To create a FHIR bulk data export client for population health analytics using Epic's SMART on FHIR API, you will need to follow these steps:

1. Register your application at App Orchard (open.epic.com).
2. Generate an RSA key pair and upload the public key.
3. Create and sign an JWT assertion.
4. Exchange the JWT for a bearer token from the token endpoint.
5. Kick-off a bulk data export using the `$export` operation.
6. Poll status to check when the job is complete.
7. Download NDJSON files as needed.

Below belows Python script demonstrates how to achieve this:

```python
import requests
import jwt
from datetime import datetime, timedelta

# Constants
BASE_URL = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4"
TOKEN_ENDPOINT = f"{BASE_URL}/oauth2/token"

# RSA key pair and public key upload details are not shown here as they need to be generated and uploaded in App Orchard.

def create_jwt_assertion():
    # Create a JWT assertion with the necessary claims
    payload = {
        "iss": "<your-client-id>",
        "sub": "<your-client-id>",
        "aud": TOKEN_ENDPOINT,
        "exp": datetime.utcnow() + timedelta(seconds=3600),  # Token expires in 1 hour
        "jti": str(uuid.uuid4())
    }

    # Sign the JWT assertion with your RSA key pair (not shown here)
    signed_jwt = sign_jwt(payload)  # This function should be implemented based on your signing logic

    return signed_jwt

def get_access_token(signed_jwt):
    # Create a request to exchange the JWT for an access token
    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": signed_jwt
    }

    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }

    response = requests.post(TOKEN_ENDPOINT, data=data, headers=headers)

    if response.status_code == 200:
        return response.json().get("access_token")
    else:
        raise Exception(f"Failed to get access token: {response.text}")

def kick_off_bulk_export(access_token):
    # Create a request to kick-off a bulk data export
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json"
    }

    response = requests.get(f"{BASE_URL}/$export", headers=headers)

    if response.status_code == 202:
        return response.headers["Location"]
    else:
        raise Exception(f"Failed to kick-off bulk data export: {response.text}")

def poll_status(status_url, access_token):
    # Poll status until the job is complete
    while True:
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get(status_url, headers=headers)

        if response.status_code == 200 and "output" in response.json():
            return [file["url"] for file in response.json()["output"]]
        elif response.status_code != 202:
            raise Exception(f"Failed to poll status: {response.text}")

        time.sleep(5)  # Wait before polling again

def download_files(file_urls, access_token):
    # Download NDJSON files
    for file_url in file_urls:
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get(file_url, headers=headers)

        if response.status_code == 200:
            with open(f"{file_url.split('/')[-1]}", "w") as output_file:
                output_file.write(response.text)
        else:
            raise Exception(f"Failed to download file: {response.text}")

def main():
    try:
        # Step 1: Create a JWT assertion
        signed_jwt = create_jwt_assertion()

        # Step 2: Get an access token
        access_token = get_access_token(signed_jwt)

        # Step 3: Kick-off a bulk data export
        status_url = kick_off_bulk_export(access_token)

        # Step 4: Poll status until the job is complete
        file_urls = poll_status(status_url, access_token)

        # Step 5: Download NDJSON files
        download_files(file_urls, access_token)

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
```

### Explanation:

1. **create_jwt_assertion**: This function should be implemented based on your RSA key pair signing logic.
2. **get_access_token**: Exchanges the JWT for an access token.
3. **kick_off_bulk_export**: Kicks-off a bulk data export and returns the status URL.
4. **poll_status**: Polls status until the job is complete and downloads NDJSON files.

### Error Handling:
- The script includes basic error handling using `try-except` blocks to catch and log exceptions.

### Comments:
- Comments are included for each step of the process, including comments about HTTP requests and file operations.

