    public static List<LabResult> parseOruSegment(String hl7Message) {
        // Parse the ORU^R01 segment and extract lab results with units and reference ranges
        List<LabResult> labResults = new ArrayList<>();
        String[] segments = hl7Message.split("\\|");
        for (String segment : segments) {
            if (segment.startsWith("ORU|R")) { // Check for an ORU^R01 segment
                int i;
                for (i = 0; i < 3; i++) { // Loop through the repeating OBX segments
                    String obxSegment = segment.substring(segment.indexOf("|") + 1, segment.lastIndexOf("|"));
                    if (obxSegment.startsWith("OBX|")) { // Check for an OBX segment
                        LabResult labResult = extractLabResult(obxSegment);
                        labResults.add(labResult);
                    }
                }
            }
        }

        return labResults;
    }

    public static LabResult extractLabResult(String obxSegment) {
        String[] fields = obxSegment.split("\\|");
        if (fields.length >= 5) { // Check for the required field values
            LabResult labResult = new LabResult();
            labResult.setTestId(fields[2].substring(3)); // Extract the test ID
            labResult.setValue(fields[1]); // Extract the observation value
            labResult.setUnits(fields[3]); // Extract the units of measurement
            return labResult;
        }
    }

