function maskPatientIdentifiers(message) {
    var mrn = message.getSegment("PID").getField(3); // Assuming MRN is in PID-3 segment and field 1
    var ssn = message.getSegment("PID").getField(4); // Assuming SSN is in PID-4 segment and field 1

