// Import required libraries
import java.util.regex.Pattern;
import java.util.regex.PatternMatcher;

// Define a simple regex pattern for HL7 v2 message validation
var hl7v2Pattern = /MSH\|.*?~\^~&/; // Check MSH header and required segments

function validateHL7Message(message) {
  try {
    // Validate the incoming message against our regex pattern
    if (!hl7v2Pattern.matcher(message).matches()) {
      throw new Error("Invalid HL7 v2 message: " + message);
    }

    // Check for required segments (MSH, PID, PV1)
    var segments = message.split("~");
    if (!Array.prototype.includes(segments, "MSH", true)) || !Array.prototype.includes(segments, "PID", true) || !Array.prototype.includes(segments, "PV1", true) {
      throw new Error("Invalid HL7 v2 message: " + message);
    }

    // Check for required field lengths (e.g., MSH-3)
    var mshSegments = segments.filter((segment) => segment.startsWith("MSH|"));
    if (!mshSegments[0].substring(4, 8).match(/^[A-Z0-9]{5}$/)) {
      throw new Error("Invalid HL7 v2 message: " + message);
    }

    // Return a success response
    console.log("HL7 v2 message validated successfully!");
} catch (error) {
  // Handle errors and exceptions
  console.error(error.getMessage());
}
