```javascript
// Import popular libraries:
const { hl7 } = require('hl7-js');
const { regex } = require('regex');

// Define a function to validate an HL7 v2 message
function validateHl7Message(message) {
  // Check MSH header requirements:
  if (!/MSH\|.*?~/.test(message)) throw new Error('Invalid MSH header');
  if (!/MSA\|.*?~/.test(message)) throw new Error('Missing or invalid MSA segment');

  // Verify required segments and field lengths:
  const hl7Segments = ['PID', 'PV1', 'OBX'];
  hl7Segments.forEach((segment) => {
    if (!hl7.message().includes(segment + '|')) {
      throw new Error(`Invalid ${segment} segment`);
    }
    if (segment === 'PID' && !/PID-5:.*~/.test(message)) {
      throw new Error('Missing or invalid Patient Identification (XPN) segment');
    } else if (segment === 'PV1' && !/PV1-2:.*~/.test(message)) {
      throw new Error('Invalid Visit Number (VSN) segment');
    }
  });

  // Verify field lengths:
  const hl7Fields = ['MSH', 'PID', 'OBX'];
  hl7Segments.forEach((segment) => {
    if (segment === 'HL7') {
      if (!/MSH-3:.*~/.test(message)) throw new Error('Invalid MSH-3: Message Type');
      if (!/MSH-4:.*~/.test(message)) throw new Error('Invalid MSH-4: Processing ID');
    } else {
      hl7Fields.forEach((field) => {
        if (segment === 'HL7' && !hl7.message().includes(field + '|')) {
          throw new Error(`Invalid ${field} field`);
        }
        if (!/PID-5:.*~/.test(message)) throw new Error('Missing or invalid Patient Identification (XPN) segment');
      });
    }
  });

  // Verify API endpoint and authentication
  const apiEndpoint = 'https://example.com/api';
  const authToken = 'your_secret_token_here';

  if (!/Authorization:.*?~/.test(message)) throw new Error('Invalid Authorization header');
  if (hl7.message().includes(apiEndpoint + '|')) {
    // Verify API endpoint authentication
    const authResponse = await fetch(apiEndpoint, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: message });
    if (!/200/.test(authResponse.headers['Set-Status'])) throw new Error('Invalid API endpoint authentication');
  }
}

