            if (given.child('FN') != null) {
                givenNames.push(given.child('FN')[2][1].toString()); // Given names (first, middle)
            }
        }

        var familyNameDisplay = familyName + ' ' + givenNames.join(' ');

        var mrn = pidSegment[3]['XPN'][4][1].toString();          // MRN
        var dob = pidSegment[7].toString();                             // Date of Birth

        var genderCodeMap = {
            "M": "Male",
            "F": "Female"
        };

        if (pidSegment[8] != null) {
            var administrativeSex = pidSegment[8]['CE'][1].toString();
            var genderDisplay = genderCodeMap[administrativeSex] || 'Unknown';
        }

        var address = [];

        for each (var addr in pidSegment['PID.11']) {
            var streetAddress = pidSegment['PID.11'][0]['XAD'][2][1].toString(); // Street Address
            var city = pidSegment['PID.11'][0]['XAD'][3][1].toString();          // City
            var stateOrProvince = pidSegment['PID.11'][0]['XAD'][4][1].toString() || pidSegment['PID.11'][0]['XAD'][5][1].toString();  // State/County or Country
            var zipOrPostalCode = pidSegment['PID.11'][0]['XAD'][6][1].toString();  // Zip/Postal Code
            var country = pidSegment['PID.11'][0]['XAD'][7][1].toString() || pidSegment['PID.11'][0]['XAD'][8][1].toString();  // Country/Other

            address.push({
                street: streetAddress,
                city: city,
                stateOrProvince: stateOrProvince,
                zipOrPostalCode: zipOrPostalCode,
                country: country
            });
        }

        var phoneNumber = pidSegment[12]['XTN'][1].toString();  // Home Phone Number

        return {
            patientName: familyNameDisplay,
            givenNames: givenNames.join(' '),
            mrn: mrn,
            dob: dob,
            gender: genderDisplay,
            address: address,
            phoneNumber: phoneNumber
        };
    } catch (e) {
