const axios = require('axios');

function tryAgain(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      func();
      break;
    } catch (error) {
      if (!/retrying/.test(error.message)) { // log and retry only if the error is not due to a human error
        console.log(`Error calling API: ${error.response.status} ${error.response.statusText}`);
        setTimeout(() => tryAgain(func, maxRetries=i+1), 1000*(i+1)); // wait for 1 second before trying again
      }
    }
  }
}

