```java
import ca.uhn.fhir.model.api.Bundle;
import ca.uhn.fhir.model.api.ElementFactory;
import org.hl7.fhir.r4.model.Patient;

public class AnonymizePatientData {
    public static Patient anonymize(Patient patient) throws Exception {
        // Create a new patient resource with the same ID as the input
        Patient anonymizedPatient = new Patient(patient.getId());

        // Replace sensitive information (names, addresses)
        List<String> names = patient.getName().stream()
                .map(name -> name.getGiven().get(0).getValue())
                .collect(Collectors.toList());
        String redactedName = "ANONYMOUS";
        for (String name : names) {
            anonymizedPatient.addName(new HumanName().setUse(HumanName.Use.OFFICIAL).addGiven(redactedName));
        }

        List<Address> addresses = patient.getAddress();
        Address redactedAddress = new Address();
        redactedAddress.setUse(Address.Use.HOME);
        for (Address address : addresses) {
            anonymizedPatient.addAddress(redactedAddress);

            // Replace street address with a generic one
            String redactedStreetAddress = "123 ANY STREET";
            redactedAddress.getLine().clear();
            redactedAddress.getLine().add(new HumanName().setUse(HumanName.Use.OFFICIAL).addGiven(redactedStreetAddress));

            // Set city, state, and zip/postal code to unknown values
            anonymizedPatient.getAddress().get(0).setCity("UNKNOWN");
            anonymizedPatient.getAddress().get(0).setState("UNKNOWN");
            anonymizedPatient.getAddress().get(0).setPostalCode("00000");

            // Set country to "Unknown" (default value)
            anonymizedPatient.getAddress().get(0).setCountry("US");

            // Set birthDate and gender to unknown values
            anonymizedPatient.setBirthDate(null);
            anonymizedPatient.setGender(Patient.Gender.UNKNOWN);

        }

        return anonymizedPatient;
    }
}
