    var patientName = globalMap.get("patientName");
    var mrn = globalMap.get("mrn");

    if (!patientName || !mrn) throw new Error("Required data not found in the global map");

    // Create a FHIR Patient resource object
    var fhirPatientResource = {
        resourceType: "Patient",
        identifier: [
            {
                system: "http://hospital.example.com/mrn",
                value: mrn,
                type: { coding: [{ system: "http://terminology.hl7.org/CodeSystem/v2-0203", code: "MR" }] }
