    var fhirPatientJson = JSON.stringify(fhirPatientResource);

    // Assemble an HTTP POST request to send the FHIR Bundle
    var url = "https://your-fhir-server.com/fhir/Patient";
    var contentType = "application/json";

    var httpSender = new Packages.java.net.HttpsURLConnection(new Packages.java.net.URL(url));
    httpSender.setRequestMethod("POST");
    httpSender.setRequestProperty("Content-Type", contentType);
    httpSender.setDoOutput(true);

    // Write the FHIR Bundle to the output of the request
    var outputStream = httpSender.getOutputStream();
    outputStream.write(fhirPatientJson.getBytes());
    outputStream.flush();
