public class HL7v2Validator {
    public static void validate(HL7Message message) throws Exception {
        // Check MSH header
        String mshHeader = message.getMSH().getHeader();
        if (!mshHeader.equals("HL7V2")) throw new Exception("Invalid MSH Header");

        // Required segments and field lengths
        boolean valid = true;
        for (HL7Message segment : message.getSegments()) {
            if (!segment.getName().equals("PID") && !segment.getName().equals("PV1")) continue;

            switch (segment.getName()) {
                case "PID":
                    CX patientId = (CX) segment.getField(3);
                    ID patientName = (ID) segment.getField(5);

                    // Check required fields and lengths
                    if (!patientId.getValue().matches("[A-Z]{2}-[0-9]{6}") || !patientName.getComponent(1).equals("John Doe")) {
                        throw new Exception("Invalid PID Segment");
                    }
                    break;

                case "PV1":
                    ID visitNumber = (ID) segment.getField(4);

                    // Check required fields and lengths
                    if (!visitNumber.getValue().matches("[0-9]{6}-[A-Z]{2}")) {
                        throw new Exception("Invalid PV1 Segment");
                    }
                    break;
            }
        }

        // Validate HL7 v2 message structure (optional)
        if (!message.getStructure().equals(HL7Message.STRUCTURE_HL7V2)) {
            System.out.println("HL7v2 Message is not a valid XML schema");

            // TO DO: implement your desired error handling or logging mechanism
        }
    }
}
```
