function handleIncomingMessage(message) {
    try {
        // Parse the incoming HL7v2 message
        var pid = parsePIDSegment(message);

        if (!pid) throw new Error("No PID segment found in the HL7v2 message");

        // Extract patient details from the PID segment
        var mrn = pid.get(3, 1);  // MRN (Patient Identifier List)
        var familyName = pid.get(5, 0).split('^')[1];  // Family Name

        // Perform a database query to retrieve patient details
        var dbConn = DatabaseConnectionFactory.createDatabaseConnection(
            'org.postgresql.Driver',
            $('db_password'),
            $('patient_id')
        );

        try {
            var result = dbConn.executeCachedQuery(
                "SELECT * FROM patients WHERE mrn = ?", [mrn]
            );

            if (!result.next()) throw new Error("No patient found with the given MRN");

            // Log the search parameters
            log.info("Patient Search - MRN: " + mrn, familyName);

            // Return a successful response (e.g., HTML)
            return "<html><body><p>Search successful.</p></body></html>";

        } finally {
            dbConn.close();
        }
    } catch (e) {
        // Log any errors that occur during the process
        log.error("Error performing patient search: " + e.message);

        // Return an error response (e.g., HTML)
        return "<html><body><p>Error: " + e.message + "</p></body></html>";
    }
}

// Function to parse and extract PID segment details from an HL7v2 message
