function tryAgain(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      func();
      break;
    } catch (error) {
      if (!/timeout/.test(error.message)) {
        console.error(`Error calling API: ${error}`);
        return;
      }
      retries++;
      if (retries < maxRetries) {
