    var adt = new Packages.ca.uhn.hl7v2.model.v25.message.ADT^A01(message);

    // Extract necessary segments and fields
    var pidSegment = adt.PID(1);  // Patient Identification Segment
    var evnSegment = adt.EVN(1);  // Event Type Segment

