Here's an example of how we can use this package to validate FHIR R4 JSON against the official schema:
```typescript
import * as fs from 'fs';
import * as xml2js from 'xml2js';

const fhirSchemaR4 = require('fhir-schema-r4');

function validateFhirJson(fhirJson: string): boolean {
  const fhirXml = new XML('<FHIR><' + FHIR_FACETS.map((facet) =>.facet.toString()) + '</FHIR>');
  const errors = [];

  try {
    // Load the FHIR R4 schema into a JavaScript object
    const fhirSchemaR4Xml = fs.readFileSync('/path/to/fhir-schema-r4.xsd', 'utf8');
    const fhirSchemaR4XmlJs = xml2js.parseString(fhirSchemaR4Xml);

    // Validate the FHIR JSON against the official schema using XSD validation
    try {
      const errors = xss.validate({ xmlns: ['http://www.w3.org/2005/XMLSchema']: 'http://www.w3.org/2005/XMLSchema' } as any, fhirXml, fhirSchemaR4XmlJs);
      if (errors.length > 0) return false;

      // If the validation was successful, then we can consider the FHIR JSON to be valid
      console.log(`FHIR R4 JSON is valid: ${fhirJson}`);
    } catch (error) {
      errors.push(error.message);

      // If there were any errors during XSD validation, then let's throw an error and exit out of our function
      if (!errors[0].includes('XSD validation failed')) throw new Error(`Error validating FHIR R4 JSON: ${fhirJson} - ${errors[0]}`);
    }
  } catch (error) {
    console.error(error.message);

    // If there were any errors during XSD loading, then let's throw an error and exit out of our function
    if (!error.message.includes('XSD loading failed')) throw new Error(`Error validating FHIR R4 JSON: ${fhirJson} - ${errors[0]}`);
  }

  return true;
}

// Example usage:
const fhirJson = '<FHIR><' + FHIR_FACETS.map((facet) =>.facet.toString()) + '</FHIR>';
if (!validateFhirJson(fhirJson)) console.error(`Error validating FHIR R4 JSON: ${fhirJson}`);
```
Note that this code uses the `xml2js` package to load in the official schema for FHIR R4 as an XML string, and then uses XSD validation using the `xss` library to validate our FHIR JSON against the official schema.

