    public static List<LabResult> parseOruSegment(String hl7Message) {
        // Parse the ORU^R01 segment and extract lab results with units and reference ranges
        List<LabResult> labResults = new ArrayList<>();
        String[] segments = hl7Message.split("\\|");

        for (String segment : segments) {
            if (segment.startsWith("ORU|R")) { // Check for an ORU^R01 segment
                int i;
                for (i = 0; i < 3; i++) { // Loop through the repeating OBX segments
                    String obxSegment = segments[i * 2 + 1];
                    if (!obxSegment.startsWith("OBX")) continue;

                    LabResult labResult = new LabResult();
                    labResult.setTestId(obxSegment.substring(4, 20).trim());
                    labResult.setValue(obxSegment.substring(21, 35).trim());
                    labResult.setUnits(obxSegment.substring(36, 50).trim());

                    // Extract the reference range (low/normal/high) and abnormal flags
                    String refRange = obxSegment.substring(51, 75).trim();
                    int lowVal = Integer.parseInt(refRange.split("-")[0]);
                    int highVal = Integer.parseInt(refRange.split("-")[1]);

                    labResult.setRefRange(new Range(lowVal, highVal));

                    // Add the lab result to our list
                    labResults.add(labResult);
                }
            }
        }

        return labResults;
    }
}

