```
// Define our filter's name and description
var name = "Drop Duplicates";
var desc = "Remove duplicate messages based on MSH-10 control ID";

// Set up our filter's input and output message types (HL7v2)
inputMessage = hl7v2;
outputMessage = hl7v2;

// Define a function to drop duplicates
function dropDuplicates(message) {
  // Get the current message's `MSH-10` segment value
  var msh10Value = message.getSegment("MSH").getValue(10);

  // Check if we've seen this control ID before (i.e., it's not a duplicate)
  if (!seenControlIds[msh10Value]) {
    // If not, store the value in our "seen" map and continue processing
    seenControlIds[msh10Value] = true;
  } else {
    // If we have seen this control ID before (i.e., it's a duplicate), drop the message
    return false; // Return an error code to indicate that we can't process this message further
  }
}

// Define our filter's logic
function filter(message) {
  // Check if our input message is not null or empty
  if (!message || !message.isEmpty()) {
    // If so, drop any duplicate messages (i.e., those with the same MSH-10 control ID)
    var dropped = false;
    for each (var msg in getMessages(inputMessage)) {
      if (!dropDuplicates(msg)) {
        continue; // Skip this message if it's not a duplicate
      }
      outputMessage.add(msg); // Send non-duplicate messages to our output queue

      // If we reached this point, we can't process any further - drop out!
      return false;
    }

    // If we made it past this point, then all input messages have been processed successfully!
  } else {
    // Log an error if our input message is null or empty
    log.error("Error processing message: " + message);
  }
}

// Define our filter's configuration (e.g., a simple `true`/`false` boolean)
var config = true;

// Set up our filter's logic to run on each incoming message
inputMessage.filter(filter, config);

// Log an informational message if we reached this point
log.info("Filtered out duplicate messages: " + outputMessage.size());
```
