```javascript
const { HL7Message } = require('hl7v2');
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');

const app = express();
app.use(bodyParser.text());
app.use(cors());

// Example routes for different message types and facilities

function routeMessage(message) {
  try {
    const hl7Message = new HL7Message(message);

    // Extract MSH-9 (Event Type)
    var eventType = hl7Message.getSegment('MSH').getField(9);

    if (!eventType || !['ADT', 'ORU'].includes(eventType)) throw "Unsupported event type";

    // Example routing logic
    switch (eventType) {
      case 'ADT':
        routeAdtMessage(message, hl7Message.getSegment('EVN').getField(2)); // Route ADT messages based on MSH-5 receiving facility
        break;
      case 'ORU':
        routeOruMessage(message, hl7Message.getSegment('OBX').getField(3)); // Route ORU messages based on MSH-5 receiving facility
      default:
        throw "Unsupported event type";

    function routeAdtMessage(adtMessage, receivingFacility) {
      console.log(`Routing ADT message to ${receivingFacility}`);

      // Example of routing logic (e.g., sending a POST request)
      fetch('http://your-api-url/adt', {
        method: 'POST',
        headers: { 'Content-Type': 'application/fhir+json' },
        body: JSON.stringify(adtMessage, null, 2),
      })
        .then(response => response.json())
        .then(data => console.log(`ADT message routed to ${receivingFacility}:`, data))
    }

    function routeOruMessage(orunMessage, receivingFacility) {
      console.log(`Routing ORU message to ${receivingFacility}`);

      // Example of routing logic (e.g., sending a POST request)
      fetch('http://your-api-url/oru', {
        method: 'POST',
        headers: { 'Content-Type': 'application/fhir+json' },
        body: JSON.stringify(orunMessage, null, 2),
      })
        .then(response => response.json())
        .then(data => console.log(`ORU message routed to ${receivingFacility}:`, data))
    }
  } catch (error) {
    console.error("Error processing HL7 message:", error);
  }
}

