  try {
    const adtMessage = routeAdtMessage(req.body, 'newFacility');
    return res.json(adtMessage);
  } catch (error) {
    console.error("Error routing HL7 message:", error);
    throw new Error("Failed to route ADT message");
  }
}

// Example route for ORU messages
