import ca.uhn.hl7v2.HL7Message;
import ca.uhn.hl7v2.datatypes.CX;
import ca.uhn.hl7v2.datatypes.ID;

public class HL7v2Validator {
    public static void validate(HL7Message message) throws Exception {
        // Check MSH header
        String mshHeader = message.getMSH().getHeader();
        if (!mshHeader.equals("HL7V2")) throw new Exception("Invalid MSH Header");

        // Required segments and field lengths
        for (HL7Segment segment : message.getSegments()) {
            switch (segment.getName()) {
                case "MSH":
                    validateMshSegment(segment);
                    break;
                case "PID" or case "PV1": // Patient Identification or Visit Admit/Discharge Notification segments
                    validateRequiredSegments(segment, 5); // Check field lengths for required segments
                    break;
            }
        }

    }

    private static void validateMshSegment(HL7Segment msh) throws Exception {
        CX sendingApplication = (CX) msh.getMSH().getSendingApplication();
        ID receivingFacility = (ID) msh.getMSH().getReceivingFacility();

        if (!sendingApplication.getValue().equals("Your Organization Name")) throw new Exception("Invalid Sending Application");
        if (!receivingFacility.getValue().equals("Your Hospital/Facility Name")) throw new Exception("Invalid Receiving Facility");

    }

    private static void validateRequiredSegments(HL7Segment segment, int requiredFieldCount) throws Exception {
        for (int i = 1; i <= requiredFieldCount; i++) {
            CX field = (CX) segment.getPID().getPatientIdentification(i).getField();
            if (!field.getValue().equals("Your Expected Value")) throw new Exception("Invalid Field: " + segment.getName() + "." + i);

    }
}
