```
from fastapi import Depends, HTTPException
from sqlalchemy import create_engine, Column, Integer, String, DateTime
from sqlalchemy.ext.declarative import declarerootclass
from sqlalchemy.orm import sessionmaker

# Create an engine for the database and bind it to the session
engine = create_engine('sqlite:///patient_records.db')
base.metadata.create_table(engine)

class Patient(declarerootclass()):
    __table__name__ = 'patients'

class Record(Patient):
    id = Column(Integer, primary_key=True)
    name = Column(String)
    birthdate = Column(DateTime)

# Create a function that returns the database session
def get_db():
    return sessionmaker(autocommit=False)(engine)

@fastapi.post('/create_patient/')
def create_patient(name: str) -> dict:
    db = get_db()
    record = Record(name=name, birthdate=datetime.now())
    db.add(record)
    db.commit()
    return {'message': 'Patient created successfully'}

@fastapi.get('/get_patient/{id}/')
def get_patient(id: int) -> dict:
    db = get_db()
    patient = db.query(Record).filter_by(id=id).first()
    if not patient:
        raise HTTPException('No such patient')
    return {'name': str(patient.name)}

@fastapi.delete('/delete_patient/{id}/')
def delete_patient(id: int) -> dict:
    db = get_db()
    db.delete(Record, id=id)
    return {'message': 'Patient deleted successfully'}

@fastapi.put('/update_patient/{id}/')
def update_patient(id: int, name: str) -> dict:
    db = get_db()
    record = db.query(Record).filter_by(id=id).first()
    if not record:
        raise HTTPException('No such patient')
    record.name = name
    return {'message': 'Patient updated successfully'}

@fastapi.get('/get_patient_list/')
def get_patient_list() -> dict:
    db = get_db()
    patients = [str(patient) for patient in db.query(Record).all()]
    return {'patient_list': ', '.join(patients)}

```

