**HL7v2 Message Validator (Java)**

Create a new Java project and add the following code:
```java
import org.hl7.v3.MSH;
import org.hl7.v3.Segment;

public class Hl7v2MessageValidator {
    public static void validate(String hl7Message) throws Exception {
        // Parse HL7 message into an MSH object
        MSH msh = new MSH(hl7Message);

        // Validate required segments and field lengths
        if (!validateSegments(msh)) throw new Exception("Invalid segment(s)");
        if (!validateFieldLengths(msh)) throw new Exception("Invalid field length(s)");

    }

    private boolean validateSegments(MSH msh) {
        // Check for required segments (MSH, PID, PV1)
        Segment[] segments = msh.getSegments();
        if (!Arrays.asList(new String[]{"MSH", "PID", "PV1"}).containsAll(segments.map(Segment::getName))) return true;
        return false;
    }

    private boolean validateFieldLengths(MSH msh) {
        // Check for required field lengths (MSH-3, MSH-4)
        int[] fieldLengths = new int[]{3, 4};
        for (int i = 0; i < fieldLengths.length; i++) {
            if (!validateFieldLength(msh.getField(fieldLengths[i]), "HL7".length() + fieldLengths[i])) return true;
        }
        return false;

    }

    private boolean validateFieldLength(String hl7Value, int hl7Length) {
        // Check for required HL7 value length
        if (hl7Value.length() != hl7Length) return true;
        return false;
    }
}
```
