// Example HL7 v2 ADT^A01 message
var hl7Message = msg.get("message");

// Function to parse and extract data from HL7 v2 ADT^A01
function parseHl7v2(hl7Message) {
    var parsedData = {};

    // Extracting patient details
    if (hl7Message.include("PID")) {
        var pidSegment = hl7Message.get("PID");
        parsedData.patientName = pidSegment.get(5).toString();
        parsedData.patientId = pidSegment.get(3).toString();
        parsedData.gender = pidSegment.get(8).toString().toLowerCase() === "m" ? "male" : (pidSegment.get(8).toString().toLowerCase() === "f" ? "female" : "other");
    }

    // Extracting encounter details
    if (hl7Message.include("EVN")) {
        var evnSegment = hl7Message.get("EVN");
        parsedData.encounterId = evnSegment.get(2).toString();
        parsedData.encounterType = evnSegment.get(4).toString().toLowerCase() === "admit" ? "Admission" : (evnSegment.get(4).toString().toLowerCase() === "discharge" ? "Discharge" : "Other");
    }

    return {
        patientName: parsedData.patientName,
        patientId: parsedData.patientId,
        gender: parsedData.gender,
        encounterId: parsedData.encounterId,
        encounterType: parsedData.encounterType
    };
}

// Main function to convert HL7 v2 ADT^A01 to FHIR R4 Patient and Encounter resources
function convertToFhir(hl7Message) {
    try {
        var hl7v2Data = parseHl7v2(hl7Message);

        // Create FHIR R4 Patient Resource
        var patientResource = createFhirPatient(hl7v2Data.patientName, hl7v2Data.patientId, hl7v2Data.gender);

        // Create FHIR R4 Encounter Resource
        var encounterResource = createFhirEncounter(hl7v2Data.encounterId, hl7v2Data.encounterType);

        return {
            patient: patientResource,
            encounter: encounterResource
        };
    } catch (e) {
        log.error("Error during conversion: " + e);
        throw new Error("Failed to convert message");
    }
}

// Function to create a FHIR R4 Patient Resource
function createFhirPatient(patientName, patientId, gender) {
    var fhirPatient = {
        resourceType: "Patient",
        id: generateUniqueId(),
        name: [
            {
                use: "official",
                family: [patientName.split(" ")[1]],
                given: [patientName.split(" ")[0]]
            }
        ],
        identifier: [
            {
                system: "http://hospital.example.org/patient-id",
                value: patientId
            }
        ],
        gender: gender,
        telecom: []
    };

    return fhirPatient;
}

// Function to create a FHIR R4 Encounter Resource
function createFhirEncounter(encounterId, encounterType) {
    var fhirEncounter = {
        resourceType: "Encounter",
        id: generateUniqueId(),
        status: "completed", // Assuming all encounters are completed for simplicity
        subject: {
            reference: "Patient/" + generateUniqueId() // Temporary patient ID
        },
        type: [
            {
                coding: [
                    {
                        system: "http://terminology.hl7.org/CodeSystem/v2-0436",
                        code: encounterType,
                        display: "Encounter Type"
                    }
                ]
            }
        ],
        identifier: [
            {
                use: "official",
                value: encounterId
            }
        ]
    };

    return fhirEncounter;
}

// Function to generate a unique ID (simple example)
function generateUniqueId() {
    return new Date().replace(/[-:.]/g, "");
}
