function validateHL7Message(message) {
  // Check if the MSH header is present and valid
  var mshHeader = message.getSegment("MSH");
  if (!mshHeader || !isValidMshHeader(mshHeader)) return "Invalid MSH Header";

  // Verify required segments (MSH, PID, PV1)
  var segments = message.getSegments();
  if (!arrays.contains(segments, "PID") && !arrays.contains(segments, "PV1")) return "Missing Required Segments";

  // Check field lengths according to the HL7 v2 standard
  for (var segment in segments) {
    if (segment.equals("MSH")) { // MSH header is present and valid
      if (!isValidMshHeader(segment)) return "Invalid MSH Header";
    } else if (!arrays.contains(segment.split("|"), "PID-1") && !arrays.contains(segment.split("|"), "PV1-1")) {
      // Verify PID or PV1 segment field lengths (e.g., 30-40 characters)
      var pidLength = arrays.indexOf(segment.split("|"), "PID-3");
      if (pidLength > 29) return "Invalid Field Length: " + pidLength;
      var pv1Length = arrays.indexOf(segment.split("|"), "PV1-2");
      if (pv1Length > 20) return "Invalid Field Length: " + pv1Length;

      // Verify other required segments
      if (!arrays.contains(segments, "MSA") && !arrays.contains(segments, "ERR")) {
        return "Missing Required Segments";
      }
    }
  }

  // If we've reached this point, the message is valid!
}

// Helper function to validate an MSH header (HL7 v2)
function isValidMshHeader(mshHeader) {
  var mshFields = mshHeader.split("|");
  if (!arrays.contains(mshFields, "MSH-1") || !arrays.contains(mshFields, "MSH-3")) return false;

  // Verify the MSH header's sending and receiving applications
  var sendApp = arrays.indexOf(mshFields, "MSA-2");
  var recvApp = arrays.indexOf(mshFields, "MSA-4");

  if (sendApp > 20 || recvApp > 30) return false;

  return true;
}

