```typescript
import { FHIRSchemaR4 } from 'fhir-schema-r4';

const fhirSchema = new FHIRSchemaR4();

function validateFhirJson(fhirJson: string): boolean {
  try {
    // Load the FHIR R4 JSON into a JavaScript object using the `json` module
    const jsonData = JSON.parse(fhirJson);

    // Validate the FHIR R4 JSON against the official schema using the fhir-schema-r4 package
    if (!fhirSchema.validate(jsonData)) return false;

    return true;
  } catch (error) {
    console.error(`Error validating FHIR R4 JSON: ${error}`);
    return false;
  }
}

