// Source Connector: TCP Listener (Configure as needed)

// Transformer

function transform() {
    // Parse the HL7 message to extract the MSH-9 segment
    var mshSegment = msg.get("MSH");

    if (!mshSegment) {
        log.error("No 'MSH' segment found in the HL7 message.");
        return;
    }

    try {
        // Extract the event type from the MSH-9 segment
        var eventType = mshSegment.getChild(9).toString();

        // Define a function to route messages based on the event type
        switch (eventType) {
            case "ADT^A01":  // Example for an ADT A01 message
                routeMessage("admit", msg);
                break;
            case "ORU^R03":  // Example for an ORU R03 message
                routeMessage("order", msg);
                break;
            default:
                log.info("Unhandled event type: " + eventType);

        }

    } catch (e) {
        log.error("Failed to parse HL7 message or extract event type: " + e.message);

    }
}

function routeMessage(destinationName, hl7Message) {
    try {
        // Configure and send the HL7 message to different destinations
        var adtConnector = channelMap.get("adtConnector");
        if (adtConnector) {
            adtConnector.send(hl7Message);
            log.info("Message routed to ADT connector: " + destinationName);

        } else {
            log.error("No ADT connector configured for routing messages.");

        }

    } catch (e) {
        log.error("Failed to route message to destination: " + e.message);

    }
}
```

