```python
import requests
from datetime import datetime, timedelta
import jwt

# Constants
APP_ORCHARD_URL = "https://open.epic.com"
BACKEND SERVICES_URL = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4/oauth2/token"

# RSA key pair and public key upload details (this is a placeholder)
RSA_KEY_PAIR = {
    "private_key": """
-----BEGIN PRIVATE KEY-----
MIICMGCCAGQAAQAEAAQEA...
-----END OF SIGNATURE-----""",

    "public_key": """
-----BEGIN PUBLIC KEY-----
MIGfMA0GA2IBADQEQAQAA4DAB... 
-----END OF SIGNATURE-----"""
}

# Function to create a signed JWT assertion
def generate_jwt_assertion(private_key, client_id):
    payload = {
        "iss": client_id,
        "aud": BACKEND SERVICES_URL,
        "exp": datetime.utcnow() + timedelta(seconds=3600),  # Token expires in 1 hour
        "iat": datetime.utcnow()
    }

    return jwt.encode(payload, private_key, algorithm="RS256")

# Function to exchange the JWT for an access token
def get_access_token(client_id):
    client_assertion = generate_jwt_assertion(RSA_KEY_PAIR["private_key"], client_id)
    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }

    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": client_assertion
    }

    response = requests.post(BACKEND SERVICES_URL, headers=headers, data=data)

    if response.status_code == 200:
        return response.json().get("access_token")
    else:
        raise Exception(f"Failed to get access token: {response.text}")

# Function to schedule an appointment
def schedule_appointment(patient_id):
