```
import re

def redact_phi(hl7_message):
    # Define a dictionary to store the extracted PHI values
    phi_values = {}

    try:
        # Extract patient name (XPN segment)
        xpn_segment = hl7_message.split('XPN|')[1].strip()
        if xpn_segment:
            for xpn in re.findall(r'([^\^]+)', xpn_segment):
                phi_values['Patient_Name'] = f'{xpn}'

    except Exception as e:
        print(f"Error extracting patient name: {str(e)}")

    try:
        # Extract SSN number (PID-3 field)
        pid_3_field = hl7_message.split('PID|')[2].strip()
        if pid_3_field and re.search(r'([0-9]{10})', pid_3_field):
            phi_values['SSN_Number'] = f'{re.findall(r"[0-9]+", pid_3_field)[0]}'

    except Exception as e:
        print(f"Error extracting SSN number: {str(e)}")

    try:
        # Extract MRN number (PID-2 field)
        pid_2_field = hl7_message.split('PID|')[1].strip()
        if pid_2_field and re.search(r'([0-9]+)', pid_2_field):
            phi_values['MRN_Number'] = f'{re.findall(r"[0-9]+", pid_2_field)[0]}'

    except Exception as e:
        print(f"Error extracting MRN number: {str(e)}")

    return phi_values

# Example usage
