            throw new Error("Failed to get access token");
        }
    } catch (e) {
        log.error("Error calling web service: " + e.message);
        throw e;
    }
}

// Helper function
function callWebService(url, method, headers, data) {
    var client = java.net.URL(new java.net.URL(url)).openConnection();
    client.setRequestMethod(method);

    for (var key in headers) {
        client.setRequestProperty(key, headers[key]);
    }

    if (method == "POST" || method == "PUT") {
        client.setDoOutput(true);

        var outputStream = client.getOutputStream();
        outputStream.write(data.getBytes());
        outputStream.flush();
        outputStream.close();

        return new java.lang.StringBuilder(client.getInputStream().readAllBytes()).toString();
    } else if (method == "GET") {
        return new java.lang.StringBuilder(client.getInputStream().readAllBytes()).toString();
    }

    throw new Error("Unsupported HTTP method: " + method);
}

// Main script
try {
    var privateKey = generateRSAKeyPair().privateKey;
    var jwt = createAndSignJWT(privateKey, clientId);

    var accessToken = getAccessToken(jwt);

