const axios = require('axios');

function tryAgain(func, maxRetries=5) {
  let retries=0;
  for (let i=0; i<=maxRetries; i++) {
    try {
      func();
      break;
    } catch (error) {
      if (!/timeout/.test(error.message)) {
        console.log(`Error calling API: ${error}`);
        return;
      }
      retries++;
      if (retries < maxRetries) {
        console.log(`Retrying... attempt ${i+1}/${maxRetries}`);
        setTimeout(() => tryAgain(func), 1000 * i); // wait for 1 second before retrying
      } else {
        console.error('Failed to connect to API. Aborting.');
        return;
      }
    }
  }
}

