    var pid = new Array(message.getSegment("PID").getReps());

    // Check for SSN and MRN
    for (var i = 0; i < pid.length; i++) {
        if (pid[i].getField(2).toString().trim() != "" || pid[i].getField(3).toString().trim() != "") {
            return true;
        }

        // Check for patient name
        var familyName = pid[i].getField(5, 1).toString();
        var givenNames = pid[i].getField(5, 2).toString();
        if (familyName.trim() != "" && givenNames.trim() != "") {
            return true;
        }
    }

    // Check for SSN
    for (var i = 0; i < pid.length; i++) {
        var ssn = pid[i].getField(3, 1).toString();
        if (ssn.trim() != "") {
            return true;
        }
    }

    // Check for MRN
    for (var i = 0; i < pid.length; i++) {
        var mrn = pid[i].getField(2).toString();
        if (mrn.trim() != "") {
            return true;
        }
    }

    return false;
}

