import org.hl7.fhir.r4.model.Quantity;

public class LabResultExtractor {
    public static void extractLabResults(String hl7Message) throws Exception {
        // Parse the HL7 v2 message using an FHIR client library (e.g., HAPI)
        FhirClient fhirClient = new FhirClient();
        Bundle bundle = fhirClient.parseBundle(hl7Message);

        // Loop through each OBX segment in the ORU^R01 message
        for (Segment obxSeg : bundle.getEntry().get(0).getResource().getSegments(Observation.OBX)) {
            // Extract lab results with units and reference ranges from the OBX segment
            String observationId = getObservationId(obxSeg);
            Quantity quantityValue = extractQuantityValue(obxSeg);
            String unitOfMeasure = getUnitOfMeasure(obxSeg);

            if (quantityValue != null && !unitOfMeasure.isEmpty()) {
                // Create a new FHIR Observation resource to store the lab result
                Observation observation = fhirClient.createObservation();

                // Set the observation ID, value, and units from the OBX segment
                observation.setId(observationId);
                observation.setValue(quantityValue.getValue());
                observation.setUnits(unitOfMeasure);

                // Add any reference ranges (e.g., normal range) to the observation resource
                if (!getReferenceRange(getObservationId(obxSeg)).isEmpty()) {
                    Quantity quantityRange = extractQuantityValue(getReferenceRange(getObservationId(obxSeg)));
                    observation.setValue(quantityRange.getValue());
                    observation.setUnits(quantityRange.getUnitOfMeasure());
                }

                // Log or store the extracted lab result as needed
            }
        }
    }

    private static String getObservationId(Segment obxSeg) {
        // Extract the observation ID from the OBX segment using a regular expression (e.g., Java's `java.util.regex.Pattern` class)
        Pattern pattern = Pattern.compile("OBX-(5)\|(.*?)|");
        Matcher matcher = pattern.matcher(obxSeg.getValue());
        if (matcher.find()) return matcher.group();

        return "";
    }

    private static Quantity extractQuantityValue(Segment obxSeg) {
        // Extract the quantity value and units from the OBX segment using a regular expression (e.g., Java's `java.util.regex.Pattern` class)
        Pattern pattern = Pattern.compile("OBX-(5)\|(.*?)|([0-9.]+)([a-zA-Z]+)|");
        Matcher matcher = pattern.matcher(obxSeg.getValue());
        if (matcher.find()) {
            double value = Double.parseDouble(matcher.group(1));
            String unitOfMeasure = matcher.group(3) + " " + matcher.group(4);

            // Create a new FHIR Quantity resource to store the lab result
            Quantity quantityValue = fhirClient.createQuantity();

            // Set the quantity value and units from the OBX segment
            quantityValue.setValue(value);
            quantityValue.setUnitOfMeasure(unitOfMeasure);

            return quantityValue;
        }

        return null;
    }
