```
const axios = require('axios');

function tryAgain(maxRetries, delayMs) {
  let retries = 0;
  while (retries < maxRetries) {
    try {
      // make API call
      const response = await axios.get('/api/patient', { timeout: 10000 });

      if (!response.data) {
        log.error(`Error making API request: ${response.status}`);
        return;
      }

      console.log(`API request successful! Response: ${JSON.stringify(response.data)}`);
    } catch (error) {
      retries++;
      setTimeout(() => tryAgain(retries, delayMs), delayMs);
    }
  }
}

async function makeApiCall(patientId, maxRetries = 5, delayMs = 1000) {
  for (let i = 0; i <= maxRetries; i++) {
    try {
      // make API call
      const response = await axios.get(`/api/patient/${patientId}`, { timeout: 10000 });

      if (!response.data) {
        log.error(`Error making API request: ${response.status}`);
        return;
      }

      console.log(`API request successful! Response: ${JSON.stringify(response.data)}`);

      // log the full request and response
      const logMessage = `Request to retrieve patient data for ID ${patientId}: ${new Date()} - Response: ${JSON.stringify(response.data)}`;
      log.info(logMessage);

      break;
    } catch (error) {
      if (i === maxRetries) {
        throw error;
      }

      setTimeout(() => tryAgain(i, delayMs), delayMs);
    }
  }
}

