To ensure the integrity of our healthcare data exchange, we need to validate incoming messages against specific rules and constraints. We'll focus on verifying MSH header, required segments, and field lengths for this example.
```javascript
// Import required libraries
const hl7 = require('hl7-js');
const { HL7Message } = require('@mirth/connect-client');

// Define the validator function
function validateHl7Message(message) {
  // Check if the message is an HL7 v2 message (MSH-1)
  if (!message.getSegment(HL7Message.MSH).getComponent(1).getValue().startsWith('MSH')) return false;

  // Verify MSH header and required segments
  const msh = new hl7.Message(message);
  if (!msh.hasSegments([HL7Message.MSH, HL7Message.PID])) return false;
  if (!msh.getSegment(HL7Message.MSH).getComponent(3).getValue().startsWith('MSH')) return false;

  // Validate required segments (PID-1)
  const pid = new hl7.Message(message);
  if (!pid.hasSegments([HL7Message.PID, HL7Message.OBR])) return false;
  if (!pid.getSegment(HL7Message.PID).getComponent(1).getValue().startsWith('PID')) return false;

  // Verify field lengths (MSH-3)
  const msh3 = new hl7.Field(msh.getComponent(3));
  if (msh3.getLength() < 20) return false; // minimum length for MSH-3

  // Return true if the message passes all checks
  return true;
}
```
**Error Handling**

To handle errors, we'll use a try-catch block to catch any exceptions that might occur during validation. We'll also log an error message and return an error code (0x01) in case of failure.
```javascript
try {
  // Call the validator function with the incoming message as an argument
  if (!validateHl7Message(incomingMessage)) {
    // Log an error message and return an error code (0x01)
    console.error('Error validating HL7 v2 message:', incomingMessage);
    return 0x01;
  }
} catch (error) {
  // Log the exception as an error message
  console.error('Error occurred while validating HL7 v2 message:', error);

  // Return a failure code (0xFF)
  return 0xFF;
}
```
