// Define a function to route messages based on MSH-9 message type and MSH-5 receiving facility
function routeMessage(msg, meta) {
  // Get the value of the 'MSH-9' segment (message type)
  var messageType = msg['MSH']['MSH.9'].toString();

  // Define a map to store routing decisions based on message types and receiving facilities
  var routes = new java.util.HashMap();

  // Set default route for all messages
  routes.put('*', 'default-route');

  // Add custom routes for specific message types and receiving facilities
  routes.put('ADT-A01', 'admit-route'); // Admit/Discharge Transfer - Route to admit/discharge channel

  routes.put('ORU-R01', 'lab-result-route'); // Laboratory Observation Report - Route to lab result channel

  routes.put('PID-PV1', 'patient-visits-route'); // Patient Visit Notification - Route to patient visits channel

  // Get the value of the 'MSH-5' segment (receiving facility)
  var receivingFacility = msg['MSH']['MSH.5'].toString();

  // Loop through each route and route message based on MSH-9 message type and MSH-5 receiving facility
  for each (route in routes.keySet()) {
    if (routes.get(route).equals(messageType) && routes.get(route).equals(receivingFacility)) {
      router.routeMessage(routes.get(route), msg, meta);
    }
  }
}
```
This code defines a function `routeMessage` that takes an HL7 v2 message (`msg`) and its metadata (`meta`) as input. The function loops through each route stored in the `routes` map and routes the incoming message to the corresponding channel based on its MSH-9 message type and MSH-5 receiving facility.
