To create a FHIR bulk data export client for population health analytics using Epic's SMART on FHIR (OAuth 2.0) API, you will need to follow these steps:

1. Register your application at App Orchard.
2. Generate an RSA key pair and upload the public key.
3. Create a signed JWT assertion.
4. Exchange the JWT for an access token.
5. Kick-off a bulk data export using the `$export` operation.
6. Poll status until you receive a response from Epic's server.

Below is a Python script that demonstrates how to achieve this:

```python
import requests
import time
from datetime import datetime, timedelta

# Constants
BASE_URL = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4"
TOKEN_ENDPOINT = f"{BASE_URL}/oauth2/token"

# RSA key pair and JWT assertion (not shown for security reasons)

def get_access_token(client_assertion):
    # Step 1: Exchange the JWT for an access token
    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }
    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": client_assertion
    }

    response = requests.post(TOKEN_ENDPOINT, headers=headers, data=data)

    if response.status_code == 200:
        return response.json().get("access_token")
    else:
        raise Exception(f"Failed to get access token: {response.text}")

def kick_off_bulk_export(access_token):
    # Step 5: Kick-off a bulk data export
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/fhir+json",
        "Accept": "application/fhir+json"
    }
    url = f"{BASE_URL}/Patient/$export"

    response = requests.get(url, headers=headers)

    if response.status_code == 202:
        return response.headers["Location"]
    else:
        raise Exception(f"Failed to kick-off bulk data export: {response.text}")

def poll_status(status_url):
    # Step 6: Poll status until you receive a response from Epic's server
    headers = {
        "Authorization": f"Bearer {access_token}"
    }

    while True:
        time.sleep(5)  # Wait for 5 seconds before polling again

        response = requests.get(status_url, headers=headers)

        if response.status_code == 200:
            return response.json()
        elif response.status_code == 204:  # No content to export
            print("No data to export.")
            break
        else:
            raise Exception(f"Failed to poll status: {response.text}")

def download_files(file_urls):
    # Step 7: Download NDJSON files from output links
    for file_url in file_urls:
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get(file_url, headers=headers)

        if response.status_code == 200:
            with open(f"{file_url.split('/')[-1]}", "wb") as file:
                file.write(response.content)
            print(f"Downloaded: {file_url}")
        else:
            raise Exception(f"Failed to download file: {response.text}")

# Example usage
if __name__ == "__main__":
    client_assertion = "your_client_assertion_here"

    try:
        global access_token, status_url, output_links

        # Step 1: Get an access token
        access_token = get_access_token(client_assertion)

        # Step 2-3: Kick-off a bulk data export and poll status until you receive a response from Epic's server
        status_url = kick_off_bulk_export(access_token)
        output_links = poll_status(status_url)

        # Download NDJSON files from output links
        download_files(output_links)

    except Exception as e:
        print(f"Error: {e}")
```

This Python script includes functions to get an access token, kick-off a bulk data export, poll status until you receive a response from Epic's server, and download NDJSON files from output links.

