To convert an HL7 v2.3 ADT message to v2.5.1 format using a Mirth connector, we'll need to create a custom JavaScript script that takes advantage of the `hl7` and `java.text` packages.

Here's the code:
```javascript
// Import required libraries
importPackage(hl7);
importPackage(java.text);

// Define the conversion function
function convertAdt(adtMessage) {
  // Create an empty HL7 v2.5.1 message
  var adt25_01 = new hl7.Message();

  // Set the MSH-3 (message type) to ADT-A03 (update patient information)
  adt25_01.addSegment(hl7.Segment.MSH);
  adt25_01.getMSH().setValue("ADT-A03");

  // Iterate through each segment in the original HL7 v2.3 message
  for (var i = 0; i < atdMessage.getSegments().length(); i++) {
    var seg = atdMessage.getSegments()[i];

    // If we're dealing with a PID-1 (patient identification) segment, update the MSH-5 field
    if (seg.getName() == "PID" && seg.getComponent(1).getValue() != null) {
      adt25_01.addSegment(hl7.Segment.MSH);
      adt25_01.getMSH().setValue("ADT-A03");
      adt25_01.getMSH().setComponent5(atdMessage.getSegments()[i].getComponent(1).getValue());
    }
  }

  // Return the converted HL7 v2.5.1 message
  return adt25_01;
}

// Example usage:
var atd23Message = new hl7.Message("PID|1234567890^John Doe^Jane Smith");
var convertedAdt25_01 = convertAdt(atd23Message);

// Log the converted HL7 v2.5.1 message (for debugging purposes only!)
log.info(convertedAdt25_01.toString());
```
