importPackage(java.net);
importPackage(java.io);

function convertToFhir(hl7Message) {
    try {
        // Parse the HL7 message
        var pidSegment = hl7Message.split("\n")[1];  // Assuming PID segment is in the second line of the message
        var evnSegment = hl7Message.split("\n")[0];  // Assuming EVN segment is in the first line of the message

        // Extract data from HL7 segments
        var pidFields = pidSegment.split("|");
        var patientName = pidFields[5].split("^") + " " + pidFields[5].split("^")[1];
        var mrn = pidFields[3];
        var dob = pidFields[7];

        // Create FHIR Patient resource
        var fhirPatient = {
            resourceType: "Patient",
            identifier: [
                {
                    system: "http://hospital.example.com/mrn",
                    value: mrn,
                    type: { coding: [{ system: "http://terminology.hl7.org/CodeSystem/v2-0203", code: "MR" }] }
                }
            ],
            name: [
                {
                    use: "official",
                    family: pidFields[5].split("^")[1],
                    given: [pidFields[5].split("^")[0]]
                }
            ],
            gender: pidFields[8] == "M" ? "male" : pidFields[8] == "F" ? "female" : "unknown",
            birthDate: dob
        };

        // Create FHIR Encounter resource
        var fhirEncounter = {
            resourceType: "Encounter",
            identifier: [
                {
                    system: "http://hospital.example.com/encounters",
                    value: pidFields[4] + "-" + pidFields[5].split("^")[1]
                }
            ],
            status: "in-progress",
            subject: { reference: "Patient/" + fhirPatient.identifier[0].value },
            classCode: { coding: [{ system: "http://terminology.hl7.org/CodeSystem/v2-0116", code: pidFields[4] == "A" ? "AMB" : "IMP" }] }
        };

        // Log the FHIR resources
        log.info("FHIR Patient Resource: " + JSON.stringify(fhirPatient));
        log.info("FHIR Encounter Resource: " + JSON.stringify(fhirEncounter));

        return fhirPatient, fhirEncounter;
    } catch (e) {
        logger.error("Error converting to FHIR: " + e.message);
        throw new Error("Failed to convert message to FHIR");
    }
}

