To create a FHIR bulk data export client for population health analytics using Epic's SMART on FHIR (OAuth 2.0) API, you will need to follow these steps:

1. Register your application at App Orchard.
2. Generate an RSA key pair and upload the public key.
3. Create a signed JWT assertion.
4. Exchange the JWT for an access token.
5. Kick-off a bulk data export using the `$export` operation.
6. Poll status until you receive a response from Epic's server.

Below is a Python script that demonstrates how to achieve this:

```python
import requests
import jwt
from datetime import datetime, timedelta

# Constants
BASE_URL = "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4"
TOKEN_ENDPOINT = f"{BASE_URL}/oauth2/token"

# RSA key pair and public key upload details (not shown here)
RSA_KEY_PAIR = {
    "private_key": """
-----BEGIN PRIVATE KEY-----
MIICMDCCOM6gMDASAD...
-----END OF SIGNATURE-----""",

    "public_key": """
-----BEGIN PUBLIC KEY-----
MIGfMA0GAQKBQAWDQYJKXZJ9L3S6MDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwsMDAwMDA0MDAwMDAwMDAwMDAwMDAwsMDAwMDA1MjIyMTUyNTk4ODkw
-----END OF PUBLIC KEY-----""",

}

# Function to create a signed JWT assertion
def generate_jwt_assertion(private_key, client_id):
    payload = {
        "iss": client_id,
        "aud": BASE_URL,
        "exp": datetime.utcnow() + timedelta(seconds=3600),  # Token expires in 1 hour
        "iat": datetime.utcnow(),
        "jti": str(uuid.uuid4())
    }

    return jwt.encode(payload, private_key, algorithm="RS256")

# Function to exchange the JWT for an access token
def get_access_token(client_id):
    client_assertion = generate_jwt_assertion(RSA_KEY_PAIR["private_key"], client_id)
    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }

    data = {
        "grant_type": "client_credentials",
        "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
        "client_assertion": client_assertion
    }

    response = requests.post(TOKEN_ENDPOINT, headers=headers, data=data)

    if response.status_code == 200:
        return response.json().get("access_token")
    else:
        raise Exception(f"Failed to get access token: {response.text}")

# Function to kick-off a bulk data export
def start_bulk_export(access_token):
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json",
        "Accept": "application/fhir+json"
    }

    response = requests.get(f"{BASE_URL}/Patient/$export", headers=headers, stream=True)

    if response.status_code == 202:
        return response.headers["Location"]
    else:
        raise Exception(f"Failed to start bulk export: {response.text}")

# Function to poll status until the job is complete
def poll_status(status_url):
    headers = {
        "Authorization": f"Bearer {access_token}"
    }

    while True:
        response = requests.get(status_url, headers=headers)

        if response.status_code == 200 and "output" in response.json():
            return [link["url"] for link in response.json()["output"]]
        elif response.status_code == 202:
            print("Polling status...")
            time.sleep(5)  # Wait before polling again
        else:
            raise Exception(f"Failed to poll status: {response.text}")

# Function to download NDJSON files from output links
def download_files(file_urls):
    for file_url in file_urls:
        headers = {
            "Authorization": f"Bearer {access_token}"
        }

        response = requests.get(file_url, headers=headers)

        if response.status_code == 200:
            with open(f"{file_url.split('/')[-1]}", "wb") as f:
                f.write(response.content)
            print(f"Downloaded: {file_url}")
        else:
            raise Exception(f"Failed to download file: {response.text}")

# Main function
def main():
    client_id = RSA_KEY_PAIR["public_key"].split("\n")[0].strip()

    global access_token, status_urls

    # Step 1: Get an access token
    global access_token
    access_token = get_access_token(client_id)

    # Step 2: Kick-off a bulk data export
    status_url = start_bulk_export(access_token)

    # Step 3: Poll status until the job is complete
    status_urls = poll_status(status_url)

# Run the main function
if __name__ == "__main__":
