    var pidFields = pid.split('^');

    // Update PID-4 (Patient Name)
    if (pidFields[4]) {
        var familyName = pidFields[4].split(' ');
        pidFields[4] = familyName.pop() + ' ' + familyName.join(' ') + ' ' + familyName.pop();

        for each (var given in familyName) {
            pidFields[4] += given
        }
    }

    // Update PID-5 (Date/Time of Birth)
    if (pidFields[5]) {
        var dob = pidFields[5];
        pidFields[5] = new Date(dob).toISOString().replace('T',' ').replace('.000Z','');

        for each (var prefix in dob.split('^')) {
            pidFields[5] += prefix
        }
    }

    // Update PID-7 (Administrative Sex)
    if (pidFields[7]) {
        var adminSex = pidFields[7];

        switch (adminSex) {
            case 'M':
                pidFields[7] = 'Male'
                break;
            case 'F':
                pidFields[7] = 'Female'
                break;
            default:
                pidFields[7] = adminSex
                break
            }
    }

    // Update PID-8 (Administrative Sex)
    if (pidFields[8]) {
        var adminSex = pidFields[8];

        switch (adminSex) {
            case 'M':
                pidFields[8] = 'Male'
                break;
            case 'F':
                pidFields[8] = 'Female'
                break;
            default:
                pidFields[8] = adminSex
                break
            }
    }

    // Update PID-11 (Address)
    if (pidFields[10]) {
        var address = pidFields[10];

        for each (var line in address.split('^')) {
            pidFields[10] += line + '\r'
        }

        pidFields[10] = pidFields[10].replace(/\r/g,';')
    }

    // Update PID-13 (Phone Number Home)
    if (pidFields[12]) {
        var phoneNumber = pidFields[12];

        for each (var component in phoneNumber.split('^')) {
            pidFields[12] += component + '\r'
        }

        pidFields[12] = pidFields[12].replace(/\r/g,';')
    }

    // Update PID-5.1 (Set ID)
    if (pidFields[5]) {
        var setID = pidFields[5];

        for each (var identifier in setID.split('^')) {
            pidFields[5] += identifier + '\r'
        }

        pidFields[5] = pidFields[5].replace(/\r/g,';')
    }

    // Update PID-7.1 (Set ID)
    if (pidFields[7]) {
        var setID = pidFields[7];

        for each (var identifier in setID.split('^')) {
            pidFields[7] += identifier + '\r'
        }

        pidFields[7] = pidFields[7].replace(/\r/g,';')
    }

    // Update PID-3.1 (Set ID)
    if (pidFields[3]) {
        var setID = pidFields[3];

        for each (var identifier in setID.split('^')) {
            pidFields[3] += identifier + '\r'
        }

        pidFields[3] = pidFields[3].replace(/\r/g,';')
    }

    // Update PID-7.1 (Set ID)
    if (pidFields[7]) {
        var setID = pidFields[7];

        for each (var identifier in setID.split('^')) {
            pidFields[7] += identifier + '\r'
        }

        pidFields[7] = pidFields[7].replace(/\r/g,';')
    }

    // Update PID-3.1.1 (Assigning Authority)
    if (pidFields[3]) {
        var setID = pidFields[3];

        for each (var identifier in setID.split('^')) {
            pidFields[3] += identifier + '\r'
        }

        pidFields[3] = pidFields[3].replace(/\r/g,';')
    }

    // Update PID-7.1.1 (Assigning Authority)
    if (pidFields[7]) {
        var setID = pidFields[7];

        for each (var identifier in setID.split('^')) {
            pidFields[7] += identifier + '\r'
        }

        pidFields[7] = pidFields[7].replace(/\r/g,';')
    }

    return pidFields.join('\n');
}

