```javascript
// Function to split a message into multiple HL7 messages based on a custom delimiter
function splitMessages(message, delimiter) {
    var hl7Messages = [];

    // Example logic: Assuming the message contains multiple segments separated by CR (Carriage Return)
    var crDelimiter = "\r";

    if (!delimiter || !crDelimiter) throw new Error("Invalid input. Delimiters are required.");

    for (var i = 0; i <= message.length().split(delimiter).length() - 1; i++) {
        hl7Messages.push(message.substring(0, message.indexOf(delimiter, i * delimiter.length() + crDelimiter.length()) + crDelimiter.length()));

        if (i < hl7Messages.length()) {
            var nextDelim = message.indexOf(delimiter, i * delimiter.length() + crDelimiter.length());
            if (nextDelim != -1) {
                hl7Messages[hl7Messages.length()] += message.substring(i * delimiter.length(), nextDelim + crDelimiter.length());

                // Assuming CR is used to separate segments
                hl7Messages[hl7Messages.length()] += "\r" + crDelimiter;
            }
        }
    }

    return hl7Messages;
}

// Main transformer script
