    var messages = msg.split("\n");  // Assuming the message contains multiple lines

    for (var i in messages) {
        var hl7Message = splitMessages(messages[i], "\r");  // CR is used to separate segments

        if (hl7Messages.length() > i && !hl7Messages[i]) {
            throw new Error("Invalid HL7 segment. Delimiter not found.");
        }

        for each (var message in hl7Message) {
            channelMap.put("segment" + i, message);

            // Example logic: Assuming you want to log the messages
