const fhirSchemaR4 = require('fhir-schema-r4');

function validateFhirJson(fhirJson: string): boolean {
  const fhirXml = new XML('<FHIR><' + fhirJson.replace(/[^A-Z]/g,'') + '</FHIR>');</FHIR>
  try {
    // Try to parse the FHIR R4 JSON as an E4X XML node
    const e4xNode = org.w3.xml.dom.DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
    e4xNode.appendChild(org.w3.xml.dom.Element(e4xNode));

    // If we can't actually parse the FHIR R4 JSON, then it's probably invalid!
    if (!e4xNode.getChild(0)) {
      return false;
    }

    // Now that we have an E4X XML node, let's use it to validate our FHIR R4 JSON against the official schema
    const fhirXmlString = e4xNode.toString();
    try {
      const xml2js = new xml2js.Parser();
      const fhirXmlDom = org.w3.dom.DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument(fhirXmlString);
      const [node] = fhirXmlDom.getChilds();

      // If we can't actually parse the FHIR R4 JSON against the official schema, then it's probably invalid!
      if (!node child(0)) {
        return false;
      }

      // Now that we have an E4X XML node, let's use it to validate our FHIR R4 JSON against the official schema
      const fhirXmlDomString = fhirXmlDom.toString();
      try {
        const xml2jsParser = new xml2js.Parser({ debug: false });
        const [fhirXml] = xml2js.parseString(fhirXmlDomString, 'FHIR');

        // If we can't actually parse the FHIR R4 JSON against the official schema, then it's probably invalid!
        if (!fhirXml) {
          return false;
        }

        // Now that we have an E4X XML node, let's use it to validate our FHIR R4 JSON against the official schema
        const fhirSchemaR4 = new fhirSchemaR4.FHIR();
        try {
          fhirSchemaR4.validate(fhirXml);

          return true;
        } catch (error) {
          console.error(error);
          return false;
        }
      } catch (error) {
        console.error(error);
        return false;
      }
    } catch (error) {
      console.error(error);
      return false;
    }
  } catch (error) {
    console.error(error);
    return false;
  }

  // If we can't actually parse the FHIR R4 JSON, then it's probably invalid!
  return true;
}

