**Why?**

To ensure the integrity of our healthcare data exchange, we need to validate incoming messages against specific rules and constraints. We'll focus on creating an HL7 v2 message validator that checks MSH header, required segments, and field lengths.
```javascript
// Import required libraries
const hl7 = require('hl7-js');
const { v4_3 } = require('@mirth/connect/lib/regex');

// Define the HL7 v2 message validator function
function validateHl7Message(message) {
  // Check MSH header (Message Header)
  if (!message.startsWith(v4_3.MSH)) return 'Invalid MSH header';

  const msh = hl7.parseMsh(message);
  if (!msh.get(1).match(/^[A-Z0-9]{3}$/)) return `Invalid ${msh.get(1)}: ${msh.get(1).trim()}`;

  // Check required segments (MSH, PID, PV1)
  const segments = ['MSH', 'PID', 'PV1'];
  for (const segment of segments) {
    if (!message.includes(hl7.getSegment(segment))) return `Missing ${segment} segment`;
  }

  // Validate field lengths
  for (const segment in hl7.getSegments(message)) {
    const fields = hl7.getFieldCount(segment);
    for (let i = 1; i <= fields; i++) {
      if (!hl7.matchRegex(hl7.getSegment(segment), `^${v4_3[segment]}${i}[^0-9]*$`)) return `Invalid ${segment}/${i}: ${message.substring(0, message.indexOf(hl7.getSegment(segment)) + hl7.getSegment(segment).length)}`;
    }
  }

  // If we've reached this point, the message is valid!
