Here's an example of how you could implement a Python decorator for retry logic with exponential backoff:
```
import time
from functools import wraps

def retry(max_retries=5, min_delay_seconds=1, max_delay_seconds=None):
    if not max_delay_seconds:
        max_delay_seconds = max_delay_seconds

    def decorator(func):
        attempts = 0

        @wraps(func)
        def wrapped(*args, **kwargs):
            global attempts

            for attempt in range(attempts + 1):
                try:
                    return func(*args, **kwargs)

                except Exception as e:
                    if attempt == max_retries:
                        raise

                    delay_seconds = min_delay_seconds * (2 ** attempts - 1) if max_delay_seconds else None
                    print(f"Attempt {attempts} failed: {e}. Retrying in {delay_seconds:.6f} seconds...")

                    time.sleep(delay_seconds)

        return wrapped

    return decorator

# Example usage:
@retry(max_retries=3, min_delay_seconds=1, max_delay_seconds=4)
def example_function():
    # Your code here
    pass

example_function()
```
This decorator works by wrapping the original function with a new function that attempts to call the original function `attempts` times. If an exception is raised on each attempt, it will wait for `delay_seconds` seconds before trying again.

The delay between retries increases exponentially (2^attempts) if no success has been achieved after `max_retries`.

