        if (!patientName || !ssnNumber || !mrnNumber) throw new Error("Required PID segment fields are missing.");

        // Make an HTTP GET request to a FHIR server to fetch additional patient details
        var url = "https://fhir.example.com/Patient?identifier=" + mrnNumber;
        var headers = {
            "Authorization": "Bearer your_access_token",
            "Accept": "application/json"
        };

        var response = makeHttpRequest(url, "GET", null, headers);

        if (!response) throw new Error("Failed to fetch FHIR data.");

        // Parse the JSON response
        var fhirData = parseFhirResponse(response);

        // Log each row in a CSV format
        logPatientDetails(patientName, ssnNumber, mrnNumber, fhirData);
    } catch (e) {
        logger.error("Error processing message: " + e.message);
        throw e;
    }
}

function makeHttpRequest(url, method, data, headers) {
    var client = new Packages.java.net.URL(url).openConnection();
    client.setRequestMethod(method);

    for each (var header in headers) {
        client.setRequestProperty(header.key, header.value);
    }

    if (method === "GET" || method === "POST") {
        client.setDoOutput(false);
    } else if ("PUT", "DELETE").includes(method) {
        var outputStream = client.getOutputStream();
        var inputStream = new Packages.java.io.ByteArrayOutputStream(outputStream).toString();

        for each (var line in inputStream.split("\r")) {
            outputStream.write(line.getBytes());
            outputStream.flush();
            outputStream.write("\n");
        }

        outputStream.close();
    }

    return readResponse(client);
}

function parseFhirResponse(response) {
    var fhirData = new Packages.java.lang.String(response).toString().split("\n")[0].trim();

    // Example JSON format for simplicity
    var jsonData = { "data": fhirData };

    return jsonData;
}

function logPatientDetails(patientName, ssnNumber, mrnNumber, data) {
    var csvLog = patientName + "," + ssnNumber + "," + mrnNumber + "," + JSON.stringify(data) + "\r";

    // Example code to write the CSV log
    var fileWriter = new Packages.java.io.FileWriter("/path/to/log.csv", true);

    var outputStream = fileWriter.getOutputStream();
    var inputStream = new Packages.java.io.ByteArrayOutputStream(outputStream).toString();

    for each (var line in inputStream.split("\n")) {
        outputStream.write(line.getBytes());
        outputStream.flush();
        outputStream.write("\r");

        // Log the CSV log
        logger.info(csvLog);

        outputStream.close();
    }

    fileWriter.close();
}

function readResponse(connection) {
    var responseCode = new Packages.java.net.HttpsURLConnection(new Packages.java.net.URL(connection.getURL())).getResponseCode();

    if (responseCode >= 200 && responseCode < 300) {
        return new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(new Packages.java.io.ByteArrayReader(connection.getInputStream()))).lines().toArray(java.util.Arrays.asList());
    }

    throw new Error("Failed to read HTTP response. Status code: " + responseCode);
}
```

