            if fhir_resource.resourceType == "Patient":
                cda_section = ET.SubElement(cda_doc.encode('utf-8'), "{CDA_NAMESPACE}ClinicalDocument/{FHIR_RESOURCE_ID}/section")

            elif fhir_resource.resourceType in ["Observation", "ImagingStudy"]:
